const { singleFlight } = require('./single-flight.cjs');
const { app, BrowserWindow, ipcMain, dialog, Menu, shell, safeStorage, session, nativeImage, webContents } = require('electron');
const { autoUpdater } = require('electron-updater');
const { installRedactedConsole, redactSecrets } = require('./redact-console.cjs');
const {
  CodexAccountClient,
  codexStatusFromAccount,
  inspectCodexAccount,
  normalizeWorkingDirectory,
  resolveCodexInstallation,
  selectCodexSubscriptionModel,
  trustedCodexAuthUrl,
} = require('./codex-account.cjs');
const { probeLocalHttp } = require('./localhost-health.cjs');
const {
  isPerciOSShell, listWifiNetworks, getWifiStatus, connectToWifi,
  getBatteryStatus, getPowerActions, suspend, powerOff, reboot,
  getBrightness, setBrightness, getVolume, setVolume, toggleMute,
  listInstalledApps, launchApp,
} = require('./perci-os.cjs');
const {
  MAX_VOICE_RESPONSE_BYTES,
  prepareVoiceTranscription,
  readBoundedResponseText,
} = require('./voice-transcription.cjs');
const supermemoryProcess = require('./lib/supermemory-process.cjs');
const path = require('path');
const fsSync = require('fs');
const { spawn, spawnSync } = require('child_process');
const { getKlipitExtensionPath, normalizeKlipitHealth } = require('./lib/klipit.cjs');
const { createWorkspaceGrantRegistry } = require('./workspace-grants.cjs');
const { GUEST_POLICIES, KEYSAFE_GUEST_USER_AGENT, isAllowedKeySafeDownload, isNavigationAllowed, policyForOrigin, validateAttachment } = require('./guest-policy.cjs');
const { createCredentialStore, isSecureStorageAvailable, sanitizeAppData, stripCredentialUpdates } = require('./credential-store.cjs');
const { createModelBroker, validateLoopbackUrl } = require('./model-broker.cjs');
const { KEYSAFE_HEALTH_URL, KEYSAFE_ORIGIN, validateKeySafeHealth } = require('./keysafe-service.cjs');
const { pathToFileURL } = require('url');
const { randomUUID, randomBytes, createHash } = require('crypto');
const http = require('http');
const https = require('https');
const net = require('net');
const isDev = process.env.NODE_ENV === 'development';
const codexAccountClient = new CodexAccountClient();

// Packaged security checks use a disposable profile and never open the user's
// installed Perci profile. This override must run before any userData access.
if (process.env.PERCI_TEST_USER_DATA_DIR) {
  const testProfile = process.env.PERCI_TEST_USER_DATA_DIR;
  if (!path.isAbsolute(testProfile)) throw new Error('Test profile path must be absolute.');
  fsSync.mkdirSync(testProfile, { recursive: true, mode: 0o700 });
  app.setPath('userData', testProfile);
}

const workspaceGrants = createWorkspaceGrantRegistry({ fileSystem: fsSync.promises });
const protectedGuestSessions = new Map();
const keySafeGuestIds = new Set();
const selectedDatabasePaths = new Map();

async function isSelectedDatabase(event, dbPath) {
  assertTrustedMainFrame(event);
  if (typeof dbPath !== 'string' || !selectedDatabasePaths.get(event.sender.id)?.has(dbPath)) return false;
  try {
    const resolved = await fsSync.promises.realpath(dbPath);
    return resolved === dbPath && (await fsSync.promises.lstat(resolved)).isFile();
  } catch {
    return false;
  }
}

installRedactedConsole();

// macOS uses app.getName() for the "About <name>" menu item; package.json's
// "name" is lowercase ("perci"), so override it to the product name.
app.setName('Perci');

// Enrich process.env.PATH with common CLI locations, especially on macOS
if (process.platform === 'darwin' || process.platform === 'linux') {
  const home = app.getPath('home');
  const extraPaths = [
    path.join(home, '.local', 'bin'),
    path.join(home, '.hermes', 'node', 'bin'),
    path.join(home, 'bin'),
    '/opt/homebrew/bin',
    '/usr/local/bin'
  ];
  const currentPath = process.env.PATH || '';
  const pathParts = currentPath.split(path.delimiter);
  for (const extra of extraPaths) {
    if (!pathParts.includes(extra)) {
      pathParts.push(extra);
    }
  }
  process.env.PATH = pathParts.join(path.delimiter);
}

// Renderer crash log — written to userData so it survives packaged builds.
// Path is logged on startup so users can find it after a blank-screen failure.
let rendererLogPath = null;
const terminalServerToken = randomBytes(32).toString('base64url');
const MAX_RENDERER_LOG_BYTES = 1024 * 1024;
function getRendererLogPath() {
  if (rendererLogPath) return rendererLogPath;
  try {
    rendererLogPath = path.join(app.getPath('userData'), 'renderer.log');
  } catch (_) {
    rendererLogPath = path.join(require('os').tmpdir(), 'perci-renderer.log');
  }
  return rendererLogPath;
}
function appendRendererLog(line) {
  const redactedLine = redactSecrets(String(line || ''));
  const stamped = `[${new Date().toISOString()}] ${redactedLine}\n`;
  try {
    const logPath = getRendererLogPath();
    if (fsSync.existsSync(logPath) && fsSync.statSync(logPath).size + Buffer.byteLength(stamped) > MAX_RENDERER_LOG_BYTES) {
      fsSync.renameSync(logPath, `${logPath}.1`);
    }
    fsSync.appendFileSync(logPath, stamped, { encoding: 'utf8', mode: 0o600 });
    fsSync.chmodSync(logPath, 0o600);
  } catch (_) { /* diagnostic logging must never crash the app */ }
  try { console.log(`[renderer] ${redactedLine}`); } catch (_) { /* stdout may be unavailable */ }
}
function attachRendererDiagnostics(win) {
  const wc = win.webContents;
  wc.on('console-message', (_event, level, _message, line) => {
    const levels = ['log', 'warn', 'error', 'info'];
    const label = levels[level] || `lvl${level}`;
    appendRendererLog(`console.${label} source=renderer line=${Number(line) || 0}`);
  });
  wc.on('did-fail-load', (_e, errorCode) => {
    appendRendererLog(`did-fail-load code=${errorCode}`);
  });
  wc.on('render-process-gone', (_e, details) => {
    appendRendererLog(`render-process-gone reason=${details.reason} exitCode=${details.exitCode}`);
  });
  wc.on('preload-error', () => {
    appendRendererLog('preload-error category=load-failure');
  });
  wc.on('did-finish-load', () => {
    appendRendererLog('did-finish-load');
  });
  wc.on('will-navigate', (event, url) => {
    appendRendererLog('will-navigate');
    if (!isDev && isBundledAssetDocumentUrl(url)) {
      event.preventDefault();
      appendRendererLog('blocked-bundled-asset-navigation');
      return;
    }
    // The renderer is a single-page app and must never navigate its own top
    // frame. A stray form submit or anchor click that targets the app's origin
    // would otherwise trigger a full reload, wiping in-memory UI state (open
    // windows, scroll, unsaved input). Block same-origin top-frame navigations;
    // this does not affect Vite HMR (location.reload), the OpenClaw <webview>
    // (separate webContents), or external links (different origin).
    try {
      if (new URL(url).origin === new URL(wc.getURL()).origin) {
        event.preventDefault();
        appendRendererLog('blocked-self-navigation');
      }
    } catch {
      /* unparseable URL — leave default behavior */
    }
  });
  wc.on('did-navigate', () => {
    appendRendererLog('did-navigate');
  });
  wc.on('did-create-window', () => {
    appendRendererLog('did-create-window');
  });
}

let terminalServerProcess = null;
let keysafeServerProcess = null;
let mainWindow = null;
let splashWindow = null;
const keysafeServerToken = randomBytes(32).toString('base64url');
const keysafeServerNonce = randomBytes(24).toString('base64url');

function assertTrustedMainFrame(event) {
  const mainFrame = mainWindow?.webContents?.mainFrame;
  if (!mainWindow || mainWindow.isDestroyed() || event.sender !== mainWindow.webContents || event.senderFrame !== mainFrame) {
    throw new Error('Access Denied: privileged IPC requires Perci\'s trusted main frame.');
  }

  const frameUrl = event.senderFrame?.url || '';
  try {
    const parsed = new URL(frameUrl);
    const trusted = isDev
      ? parsed.origin === 'http://localhost:5173'
      : parsed.protocol === 'file:' && decodeURIComponent(parsed.pathname) === path.join(__dirname, '../dist/index.html');
    if (!trusted) throw new Error('untrusted origin');
  } catch {
    throw new Error('Access Denied: privileged IPC requires Perci\'s trusted origin.');
  }
}

function reloadPerciWindow(ignoreCache = false) {
  if (!mainWindow || mainWindow.isDestroyed()) return false;
  if (ignoreCache) {
    mainWindow.webContents.reloadIgnoringCache();
  } else {
    mainWindow.webContents.reload();
  }
  return true;
}


function isBundledAssetDocumentUrl(url) {
  let parsed;
  try {
    parsed = new URL(url);
  } catch {
    return false;
  }

  if (parsed.protocol !== 'file:') return false;
  const pathname = decodeURIComponent(parsed.pathname);
  return /\/dist\/assets\/[^/]+\.(?:js|css)$/.test(pathname)
    || /\/node_modules\/@webcontainer\/api\/dist\/.+\.js$/.test(pathname);
}

function requestJson(url, timeoutMs = 2000, headers = {}) {
  return new Promise((resolve) => {
    let parsed;
    try {
      parsed = new URL(url);
    } catch (err) {
      resolve({ ok: false, url, error: err.message });
      return;
    }

    const client = parsed.protocol === 'https:' ? https : http;
    const startedAt = Date.now();
    const req = client.get(parsed, { timeout: timeoutMs, headers }, (res) => {
      let body = '';
      res.setEncoding('utf8');
      res.on('data', chunk => { body += chunk; });
      res.on('end', () => {
        let data = null;
        try {
          data = body ? JSON.parse(body) : null;
        } catch (err) {
          resolve({
            ok: false,
            url,
            status: res.statusCode,
            error: `Invalid JSON response: ${err.message}`,
            latencyMs: Date.now() - startedAt
          });
          return;
        }

        resolve({
          ok: res.statusCode >= 200 && res.statusCode < 300,
          url,
          status: res.statusCode,
          data,
          latencyMs: Date.now() - startedAt
        });
      });
    });

    req.on('timeout', () => {
      req.destroy();
      resolve({ ok: false, url, error: 'Connection timed out', latencyMs: Date.now() - startedAt });
    });
    req.on('error', err => {
      resolve({ ok: false, url, error: err.message, latencyMs: Date.now() - startedAt });
    });
  });
}

function keySafeDirectory() {
  return app.isPackaged
    ? path.join(process.resourcesPath, 'keysafe')
    : path.join(app.getPath('home'), 'keysafe');
}

function keySafeVersion() {
  try {
    const manifest = JSON.parse(fsSync.readFileSync(path.join(keySafeDirectory(), 'package.json'), 'utf8'));
    return typeof manifest.version === 'string' ? manifest.version : null;
  } catch {
    return null;
  }
}

async function probeKeySafe() {
  const version = keySafeVersion();
  if (!version) return { ok: false, reason: 'installation-missing' };
  const result = await requestJson(KEYSAFE_HEALTH_URL, 1500, {
    Authorization: `Bearer ${keysafeServerToken}`,
  });
  return validateKeySafeHealth(result, { nonce: keysafeServerNonce, version });
}

const startKeySafeServer = singleFlight(async () => {
  const existing = await probeKeySafe();
  if (existing.ok) return { ok: true, alreadyRunning: true, identity: existing };
  if (!['unreachable', 'installation-missing'].includes(existing.reason)) {
    return { ok: false, error: `Port 4100 did not pass KeySafe identity verification (${existing.reason}). KeySafe was not attached.` };
  }

  const directory = keySafeDirectory();
  if (!fsSync.existsSync(path.join(directory, 'server.mjs')) || !fsSync.existsSync(path.join(directory, 'dist', 'index.html'))) {
    return { ok: false, error: 'KeySafe production files are missing. Run its production build first.' };
  }

  if (!keysafeServerProcess) {
    try {
      keysafeServerProcess = spawn(process.execPath, [path.join(directory, 'server.mjs')], {
        cwd: directory,
        env: {
          ...process.env,
          ELECTRON_RUN_AS_NODE: '1',
          KEYSAFE_SERVER_TOKEN: keysafeServerToken,
          KEYSAFE_SERVER_NONCE: keysafeServerNonce,
        },
        shell: false,
        stdio: ['ignore', 'ignore', 'ignore', 'ipc'],
      });
      keysafeServerProcess.unref();
      keysafeServerProcess.once('exit', () => { keysafeServerProcess = null; });
      keysafeServerProcess.once('error', () => { keysafeServerProcess = null; });
    } catch {
      keysafeServerProcess = null;
      return { ok: false, error: 'KeySafe could not be started.' };
    }
  }

  for (let attempt = 0; attempt < 30; attempt += 1) {
    await new Promise(resolve => setTimeout(resolve, 250));
    const health = await probeKeySafe();
    if (health.ok) return { ok: true, alreadyRunning: false, identity: health };
    if (!keysafeServerProcess) break;
  }
  return { ok: false, error: 'KeySafe did not pass its authenticated identity check.' };
});

function requestText(url, timeoutMs = 8000, headers = {}) {
  return new Promise((resolve) => {
    let parsed;
    try {
      parsed = new URL(url);
    } catch (err) {
      resolve({ ok: false, url, error: err.message });
      return;
    }

    if (!['http:', 'https:'].includes(parsed.protocol)) {
      resolve({ ok: false, url, error: 'Unsupported protocol' });
      return;
    }

    const client = parsed.protocol === 'https:' ? https : http;
    const startedAt = Date.now();
    const req = client.get(parsed, { timeout: timeoutMs, headers }, (res) => {
      let body = '';
      res.setEncoding('utf8');
      res.on('data', chunk => {
        body += chunk;
        if (body.length > 1_000_000) req.destroy(new Error('Response too large'));
      });
      res.on('end', () => {
        resolve({
          ok: res.statusCode >= 200 && res.statusCode < 300,
          url,
          status: res.statusCode,
          body,
          latencyMs: Date.now() - startedAt
        });
      });
    });

    req.on('timeout', () => {
      req.destroy();
      resolve({ ok: false, url, error: 'Connection timed out', latencyMs: Date.now() - startedAt });
    });
    req.on('error', err => {
      resolve({ ok: false, url, error: err.message, latencyMs: Date.now() - startedAt });
    });
  });
}

function requestJsonWithBody(url, { method = 'GET', body = null, headers = {}, timeoutMs = 12000 } = {}) {
  return new Promise((resolve) => {
    let parsed;
    try {
      parsed = new URL(url);
    } catch (err) {
      resolve({ ok: false, url, error: err.message });
      return;
    }

    if (!['http:', 'https:'].includes(parsed.protocol)) {
      resolve({ ok: false, url, error: 'Unsupported protocol' });
      return;
    }

    const client = parsed.protocol === 'https:' ? https : http;
    const payload = body == null
      ? null
      : (typeof body === 'string' ? body : JSON.stringify(body));

    const mergedHeaders = {
      Accept: 'application/json',
      ...(payload ? { 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(payload) } : {}),
      ...headers
    };

    const startedAt = Date.now();
    const req = client.request(parsed, { method, timeout: timeoutMs, headers: mergedHeaders }, (res) => {
      let raw = '';
      res.setEncoding('utf8');
      res.on('data', chunk => {
        raw += chunk;
        if (raw.length > 2_000_000) req.destroy(new Error('Response too large'));
      });
      res.on('end', () => {
        const contentType = res.headers['content-type'] || '';
        let parsedBody = null;
        if (raw && contentType.includes('application/json')) {
          try { parsedBody = JSON.parse(raw); }
          catch (err) { resolve({ ok: false, url, status: res.statusCode, error: `Invalid JSON: ${err.message}`, latencyMs: Date.now() - startedAt }); return; }
        }
        resolve({
          ok: res.statusCode >= 200 && res.statusCode < 300,
          url,
          status: res.statusCode,
          body: parsedBody,
          text: parsedBody == null ? raw : null,
          latencyMs: Date.now() - startedAt
        });
      });
    });

    req.on('timeout', () => {
      req.destroy();
      resolve({ ok: false, url, error: 'Connection timed out', latencyMs: Date.now() - startedAt });
    });
    req.on('error', err => {
      resolve({ ok: false, url, error: err.message, latencyMs: Date.now() - startedAt });
    });

    if (payload) req.write(payload);
    req.end();
  });
}

function decodeHtmlEntities(value = '') {
  return String(value)
    .replace(/&amp;/g, '&')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&#x2F;/g, '/')
    .replace(/&#(\d+);/g, (_match, code) => String.fromCharCode(Number(code)));
}

function stripHtml(value = '') {
  return decodeHtmlEntities(String(value).replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim());
}

function normalizeDuckDuckGoUrl(rawUrl = '') {
  try {
    const parsed = new URL(decodeHtmlEntities(rawUrl), 'https://duckduckgo.com');
    const uddg = parsed.searchParams.get('uddg');
    if (uddg) return decodeURIComponent(uddg);
    return parsed.toString();
  } catch {
    return '';
  }
}

function parseDuckDuckGoResults(html, maxResults = 6) {
  const results = [];
  const seen = new Set();
  const titlePattern = /<a[^>]+class="[^"]*\bresult__a\b[^"]*"[^>]+href="([^"]+)"[^>]*>([\s\S]*?)<\/a>/g;
  const snippetPattern = /<a[^>]+class="result__snippet"[\s\S]*?>([\s\S]*?)<\/a>|<div[^>]+class="result__snippet"[\s\S]*?>([\s\S]*?)<\/div>/;

  const titleMatches = [...html.matchAll(titlePattern)];
  for (let i = 0; i < titleMatches.length; i++) {
    if (results.length >= maxResults) break;
    const titleMatch = titleMatches[i];

    const url = normalizeDuckDuckGoUrl(titleMatch[1]);
    if (!url || seen.has(url) || !/^https?:\/\//i.test(url)) continue;
    seen.add(url);

    const nextIndex = titleMatches[i + 1]?.index || html.length;
    const block = html.slice(titleMatch.index, nextIndex);
    const snippetMatch = block.match(snippetPattern);
    const title = stripHtml(titleMatch[2]);
    const snippet = stripHtml(snippetMatch?.[1] || snippetMatch?.[2] || title);

    results.push({
      id: results.length + 1,
      title,
      url,
      content: snippet,
      score: 1,
      publishedDate: null
    });
  }

  return results;
}

const MONTH_NAMES = [
  'january', 'february', 'march', 'april', 'may', 'june',
  'july', 'august', 'september', 'october', 'november', 'december'
];

function parseHistoryDateFromQuery(query) {
  const text = String(query || '').toLowerCase();
  const monthPattern = new RegExp(`\\b(${MONTH_NAMES.join('|')})\\s+(\\d{1,2})\\b`, 'i');
  const monthMatch = text.match(monthPattern);
  if (monthMatch) {
    const month = MONTH_NAMES.indexOf(monthMatch[1].toLowerCase()) + 1;
    const day = Number(monthMatch[2]);
    if (month >= 1 && day >= 1 && day <= 31) return { month, day };
  }

  const numericMatch = text.match(/\b(\d{1,2})[/-](\d{1,2})(?:[/-]\d{2,4})?\b/);
  if (numericMatch) {
    const month = Number(numericMatch[1]);
    const day = Number(numericMatch[2]);
    if (month >= 1 && month <= 12 && day >= 1 && day <= 31) return { month, day };
  }

  const now = new Date();
  return { month: now.getMonth() + 1, day: now.getDate() };
}

function isHistoryDateQuery(query) {
  return /this day in history|on this day|historical events/i.test(String(query || ''));
}

function formatWikimediaHistorySources(data, month, day, maxResults = 8) {
  const events = Array.isArray(data?.events) ? data.events : [];
  return events.slice(0, maxResults).map((event, index) => {
    const primaryPage = Array.isArray(event.pages) ? event.pages[0] : null;
    const year = event.year ? `${event.year}: ` : '';
    return {
      id: index + 1,
      title: `${year}${stripHtml(event.text || primaryPage?.title || 'Historical event')}`,
      url: primaryPage?.content_urls?.desktop?.page || `https://en.wikipedia.org/wiki/${MONTH_NAMES[month - 1]}_${day}`,
      content: `${year}${stripHtml(event.text || '')}`,
      score: 1,
      publishedDate: null
    };
  });
}

async function searchWikimediaOnThisDay(query, maxResults = 8) {
  const { month, day } = parseHistoryDateFromQuery(query);
  const url = `https://api.wikimedia.org/feed/v1/wikipedia/en/onthisday/events/${month}/${day}`;
  const response = await requestJson(url, 8000, {
    'User-Agent': 'Perci/1.0 (https://perci.local)'
  });

  if (!response.ok) {
    return {
      ok: false,
      error: response.error || `Wikimedia on-this-day lookup failed with status ${response.status || 'unknown'}`,
      sources: []
    };
  }

  const sources = formatWikimediaHistorySources(response.data, month, day, maxResults);
  return {
    ok: sources.length > 0,
    query,
    sources,
    provider: 'wikimedia-onthisday',
    error: sources.length > 0 ? null : 'No Wikimedia on-this-day events found'
  };
}

function commandExists(command, extraPaths = []) {
  const envPath = [process.env.PATH || '', ...extraPaths].filter(Boolean).join(path.delimiter);
  const result = spawnSync('which', [command], {
    env: { ...process.env, PATH: envPath },
    encoding: 'utf8'
  });
  return result.status === 0 ? result.stdout.trim() : '';
}

function getJanCommandPath() {
  const home = app.getPath('home');
  return commandExists('jan', [
    path.join(home, '.local', 'bin'),
    '/opt/homebrew/bin',
    '/usr/local/bin'
  ]);
}

function findJanModelFiles() {
  const home = app.getPath('home');
  const modelsRoot = path.join(home, 'Library', 'Application Support', 'Jan', 'data', 'llamacpp', 'models');
  const models = [];

  function walk(dir) {
    let entries = [];
    try {
      entries = fsSync.readdirSync(dir, { withFileTypes: true });
    } catch {
      return;
    }

    for (const entry of entries) {
      const fullPath = path.join(dir, entry.name);
      if (entry.isDirectory()) {
        walk(fullPath);
        continue;
      }
      if (entry.name !== 'model.gguf') continue;

      const modelDir = path.dirname(fullPath);
      const id = path.relative(modelsRoot, modelDir).split(path.sep).join('/');
      let size = null;
      try {
        size = fsSync.statSync(fullPath).size;
      } catch {}
      models.push({ id, name: id, path: fullPath, size });
    }
  }

  walk(modelsRoot);
  return models.sort((a, b) => a.id.localeCompare(b.id));
}

async function probeOpenAICompatibleProvider({ id, name, endpoints }) {
  for (const endpoint of endpoints) {
    const modelsUrl = `${endpoint.replace(/\/$/, '')}/v1/models`;
    const result = await requestJson(modelsUrl);
    if (result.ok) {
      const models = Array.isArray(result.data?.data)
        ? result.data.data
            .filter(model => model.id && !String(model.id).toLowerCase().includes('embed'))
            .map(model => ({ id: model.id, name: model.id, owned_by: model.owned_by }))
        : [];
      return {
        id,
        name,
        status: models.length > 0 ? 'ready' : 'running-empty',
        endpoint,
        modelCount: models.length,
        models,
        latencyMs: result.latencyMs
      };
    }
  }

  return {
    id,
    name,
    status: 'offline',
    endpoint: endpoints[0],
    modelCount: 0,
    models: [],
    error: 'Local API server is not reachable'
  };
}

async function discoverModelProviders() {
  const [ollamaTags, lmStudio, janApi6767, janApi1337, openClawHealth] = await Promise.all([
    requestJson('http://localhost:11434/api/tags'),
    probeOpenAICompatibleProvider({
      id: 'lmstudio',
      name: 'LM Studio',
      endpoints: ['http://localhost:1234']
    }),
    probeOpenAICompatibleProvider({
      id: 'jan',
      name: 'Jan',
      endpoints: ['http://127.0.0.1:6767']
    }),
    probeOpenAICompatibleProvider({
      id: 'jan',
      name: 'Jan',
      endpoints: ['http://127.0.0.1:1337']
    }),
    requestJson('http://127.0.0.1:18789/health')
  ]);

  const janCommand = getJanCommandPath();
  const janModelsOnDisk = findJanModelFiles();
  const janApi = janApi6767.status === 'ready' || janApi6767.status === 'running-empty' ? janApi6767 : janApi1337;
  const janStatus = janApi.status === 'ready'
    ? 'ready'
    : janModelsOnDisk.length > 0
      ? 'installed-stopped'
      : janCommand
        ? 'installed-empty'
        : 'not-installed';

  const ollamaModels = Array.isArray(ollamaTags.data?.models)
    ? ollamaTags.data.models.map(model => ({ id: model.name, name: model.name, size: model.size, modified: model.modified_at }))
    : [];

  return {
    generatedAt: Date.now(),
    providers: [
      {
        id: 'ollama',
        name: 'Ollama',
        status: ollamaTags.ok ? (ollamaModels.length > 0 ? 'ready' : 'running-empty') : 'offline',
        endpoint: 'http://localhost:11434',
        modelCount: ollamaModels.length,
        models: ollamaModels,
        latencyMs: ollamaTags.latencyMs,
        error: ollamaTags.ok ? '' : ollamaTags.error
      },
      lmStudio,
      {
        id: 'jan',
        name: 'Jan',
        status: janStatus,
        endpoint: janApi.endpoint || 'http://127.0.0.1:6767',
        modelCount: janApi.modelCount || janModelsOnDisk.length,
        models: janApi.models?.length ? janApi.models : janModelsOnDisk,
        latencyMs: janApi.latencyMs,
        installed: Boolean(janCommand || fsSync.existsSync('/Applications/Jan.app')),
        cliPath: janCommand,
        error: janStatus === 'installed-stopped' ? 'Jan models are installed, but the local API server is not running.' : janApi.error
      },
      {
        id: 'openclaw',
        name: 'OpenClaw',
        status: openClawHealth.ok ? 'ready' : 'offline',
        endpoint: 'http://127.0.0.1:18789',
        modelCount: 0,
        models: [],
        latencyMs: openClawHealth.latencyMs,
        error: openClawHealth.ok ? '' : openClawHealth.error
      }
    ]
  };
}

// Track the two conditions required before revealing the main window
const splashGate = { mainReady: false, splashDone: false };

// Upper bound on how long the splash may hold the main window back.
const SPLASH_REVEAL_TIMEOUT_MS = 15000;

function tryRevealMain() {
  if (!splashGate.mainReady || !splashGate.splashDone) return;

  // Snap main window to the exact position of the splash so they perfectly overlap
  if (mainWindow && !mainWindow.isDestroyed() && splashWindow && !splashWindow.isDestroyed()) {
    mainWindow.setBounds(splashWindow.getBounds());
  }

  // Show main window underneath the still-visible splash
  if (mainWindow && !mainWindow.isDestroyed()) {
    mainWindow.showInactive();
  }

  // Fade the splash out over ~350ms, then close it and focus main
  if (splashWindow && !splashWindow.isDestroyed()) {
    let opacity = 1.0;
    const fade = setInterval(() => {
      opacity -= 0.05; // 20 steps × ~17ms ≈ 340ms
      if (!splashWindow || splashWindow.isDestroyed()) {
        clearInterval(fade);
        return;
      }
      if (opacity <= 0) {
        clearInterval(fade);
        splashWindow.close();
        splashWindow = null;
        if (mainWindow && !mainWindow.isDestroyed()) mainWindow.focus();
      } else {
        splashWindow.setOpacity(opacity);
      }
    }, 17);
  }
}

function createSplashWindow() {
  splashWindow = new BrowserWindow({
    width: 1200,
    height: 800,
    frame: false,
    resizable: false,
    center: true,
    alwaysOnTop: true,
    backgroundColor: '#1c1c1c',
    webPreferences: {
      nodeIntegration: false,
      contextIsolation: true,
      preload: path.join(__dirname, 'splash-preload.cjs'),
    },
  });
  splashWindow.loadFile(path.join(__dirname, 'splash.html'));
  splashWindow.on('closed', () => { splashWindow = null; });

  // Failsafe. tryRevealMain() waits on BOTH gate conditions, so if either one
  // never arrives the app sits on the splash forever with no way out but a
  // force-quit. `splashDone` is now delivered over the preload bridge, which
  // is one more thing that can fail to load; `mainReady` is lost if the main
  // window never paints. Force both rather than only the splash side — a blank
  // window the user can close and inspect beats a frozen splash they cannot.
  // splash.html has its own 12s fallback, so this sits past it and the normal
  // path always wins.
  setTimeout(() => {
    if (splashGate.splashDone && splashGate.mainReady) return;
    appendRendererLog(
      `splash watchdog fired after ${SPLASH_REVEAL_TIMEOUT_MS}ms ` +
      `(mainReady=${splashGate.mainReady} splashDone=${splashGate.splashDone}) — forcing reveal`
    );
    splashGate.splashDone = true;
    splashGate.mainReady = true;
    tryRevealMain();
  }, SPLASH_REVEAL_TIMEOUT_MS);
}

function startTerminalServer() {
  const isPackaged = app.isPackaged;
  // Keep the terminal port independent from Electron's dev process. Older
  // dev sessions used 3002, which can leave an orphaned authenticated server
  // that rejects the current process token after a restart.
  const terminalPort = process.env.OPAL_TERMINAL_PORT || '3001';
  const serverPath = isPackaged 
    ? path.join(process.resourcesPath, 'app.asar', 'terminal-server.cjs')
    : path.join(__dirname, '..', 'terminal-server.cjs');

  console.log(`Starting Perci Terminal Server from: ${serverPath}`);

  // On macOS, spawn the background Helper executable instead of the main executable
  // to prevent an extra dock icon from showing.
  let execPath = process.execPath;
  if (process.platform === 'darwin') {
    const mainDir = path.dirname(process.execPath);
    const appName = path.basename(process.execPath);
    const helperName = appName === 'Electron' ? 'Electron Helper' : `${appName} Helper`;
    const helperAppPath = path.join(
      mainDir,
      '..',
      'Frameworks',
      `${helperName}.app`,
      'Contents',
      'MacOS',
      helperName
    );
    try {
      if (require('fs').existsSync(helperAppPath)) {
        execPath = helperAppPath;
      }
    } catch (e) {
      console.error('Error checking helper app path:', e);
    }
  }

  terminalServerProcess = spawn(execPath, [serverPath], {
    env: { 
      ...process.env, 
      ELECTRON_RUN_AS_NODE: '1',
      OPAL_STRIP_ANSI: 'false',
      OPAL_TERMINAL_HOST: '127.0.0.1',
      OPAL_TERMINAL_PORT: terminalPort,
      OPAL_TERMINAL_TOKEN: terminalServerToken
    },
    stdio: 'inherit'
  });

  terminalServerProcess.on('error', (err) => {
    console.error('Failed to start Perci Terminal Server:', err);
  });

  terminalServerProcess.on('close', (code) => {
    console.log(`Terminal server process exited with code ${code}`);
    if (code !== 0 && code !== null) {
      console.log('Restarting terminal server in 2 seconds...');
      setTimeout(startTerminalServer, 2000);
    }
  });
}

