function createWindow() {
  const win = new BrowserWindow({
    width: 1200,
    height: 800,
    show: false,
    titleBarStyle: 'hiddenInset',
    webPreferences: {
      preload: path.join(__dirname, 'preload.cjs'),
      nodeIntegration: false,
      contextIsolation: true,
      webSecurity: true,
      webviewTag: true,
      devTools: isDev,
    },
  });
  const workspaceGrantOwnerId = win.webContents.id;

  mainWindow = win;
  attachRendererDiagnostics(win);
  appendRendererLog(`createWindow: renderer log at ${getRendererLogPath()}`);

  win.webContents.on('will-attach-webview', (event, webPreferences, params) => {
    delete webPreferences.preload;
    delete webPreferences.preloadURL;
    delete params.preload;
    delete params.allowpopups;
    webPreferences.nodeIntegration = false;
    webPreferences.contextIsolation = true;
    webPreferences.sandbox = true;
    webPreferences.webSecurity = true;

    const decision = validateAttachment({
      src: params.src,
      partition: params.partition || webPreferences.partition || '',
      userAgent: params.useragent,
    });
    if (!decision.allowed) {
      event.preventDefault();
      appendRendererLog(`blocked-protected-webview id=${decision.policy?.id || 'unknown'} reason=${decision.reason}`);
    }
  });

  win.webContents.on('did-attach-webview', (_event, guest) => {
    if (guest.getUserAgent() === KEYSAFE_GUEST_USER_AGENT) {
      keySafeGuestIds.add(guest.id);
      guest.once('destroyed', () => keySafeGuestIds.delete(guest.id));
    }
  });

  // Grant clipboard access as before, but only let Perci's main renderer request
  // microphone audio. Webviews share this session and must not inherit media access.
  win.webContents.session.setPermissionCheckHandler((webContents, permission, _origin, details) => {
    if (permission === 'clipboard-read' || permission === 'clipboard-sanitized-write' || permission === 'deprecated-sync-clipboard-read') {
      return true;
    }
    return permission === 'media'
      && webContents === win.webContents
      && details?.isMainFrame === true
      && details?.mediaType === 'audio';
  });
  win.webContents.session.setPermissionRequestHandler((webContents, permission, callback, details) => {
    if (permission === 'clipboard-read' || permission === 'clipboard-write' || permission === 'clipboard-sanitized-write') {
      callback(true);
      return;
    }
    callback(permission === 'media'
      && webContents === win.webContents
      && Array.isArray(details?.mediaTypes)
      && details.mediaTypes.length === 1
      && details.mediaTypes[0] === 'audio');
  });
  win.webContents.setWindowOpenHandler(({ url }) => {
    if (isBundledAssetDocumentUrl(url)) {
      appendRendererLog(`blocked-bundled-asset-window url=${url}`);
      return { action: 'deny' };
    }

    try {
      const parsed = new URL(url);
      if (parsed.protocol === 'http:' || parsed.protocol === 'https:') {
        shell.openExternal(url);
      }
    } catch (err) {
      appendRendererLog('blocked-window-open reason=invalid-url');
    }
    appendRendererLog('blocked-window-open');
    return { action: 'deny' };
  });
  win.once('ready-to-show', () => {
    splashGate.mainReady = true;
    tryRevealMain();
  });
  win.on('closed', () => {
    workspaceGrants.revokeOwner(workspaceGrantOwnerId);
    selectedDatabasePaths.delete(workspaceGrantOwnerId);
    if (mainWindow === win) {
      mainWindow = null;
      stopOpenClawLogStream();
      stopHermesLogStream();
    }
  });

  if (isDev) {
    win.loadURL('http://localhost:5173');
  } else {
    win.loadFile(path.join(__dirname, '../dist/index.html'));
  }

  if (isDev) {
    win.webContents.openDevTools();
  }
}

// Apps loaded in the Localhost <webview> (e.g. the TCS dashboard) sign in with
// Google Identity Services, which opens a consent popup to accounts.google.com
// and returns the token via window.opener. Recognize those URLs so the
// window-open handler can let them open in-app instead of ejecting them to the
// system browser (which would sever the window.opener channel GIS needs).
function isGoogleOAuthUrl(rawUrl) {
  try {
    const { hostname, pathname } = new URL(rawUrl);
    if (hostname === 'accounts.google.com') return true;
    if (hostname.endsWith('.google.com') && pathname.startsWith('/o/oauth2')) return true;
    return false;
  } catch {
    return false;
  }
}

// Strip the Electron/app tokens from the default user-agent so Google accepts
// the embedded consent popup (otherwise it returns disallowed_useragent).
function cleanedDesktopUserAgent(rawUa) {
  const appToken = app.getName().replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  return rawUa
    .replace(new RegExp(`\\s${appToken}\\/\\S+`, 'i'), '')
    .replace(/\sElectron\/\S+/i, '')
    .replace(/\s{2,}/g, ' ')
    .trim();
}

const YOUTUBE_WEBVIEW_REFERRER = 'https://com.perci.ai/';


function configureMarkItDownWebviewSession() {
  const markitdownSession = session.fromPartition('persist:perci-markitdown');

  markitdownSession.webRequest.onHeadersReceived(
    { urls: ['http://127.0.0.1:8920/*', 'http://localhost:8920/*'] },
    (details, callback) => {
      const responseHeaders = { ...(details.responseHeaders || {}) };
      for (const key of Object.keys(responseHeaders)) {
        const lower = key.toLowerCase();
        if (lower === 'x-frame-options' || lower === 'content-security-policy') {
          delete responseHeaders[key];
        }
      }
      responseHeaders['Access-Control-Allow-Origin'] = ['*'];
      responseHeaders['Cross-Origin-Resource-Policy'] = ['cross-origin'];
      callback({ responseHeaders });
    }
  );

  markitdownSession.setPermissionRequestHandler((webContents, permission, callback) => {
    if (permission === 'clipboard-read' || permission === 'clipboard-write' || permission === 'clipboard-sanitized-write') {
      callback(true);
      return;
    }
    callback(false);
  });
}

function configureYouTubeWebviewSession() {
  const youtubeSession = session.fromPartition('persist:perci-youtube');
  youtubeSession.webRequest.onBeforeSendHeaders(
    {
      urls: [
        'https://www.youtube.com/embed/*',
        'https://www.youtube-nocookie.com/embed/*',
      ],
    },
    (details, callback) => {
      callback({
        requestHeaders: {
          ...(details.requestHeaders || {}),
          Referer: YOUTUBE_WEBVIEW_REFERRER,
        },
      });
    }
  );
}

// --- OpenCode Rig ------------------------------------------------------------
// opencode only enforces HTTP Basic auth when OPENCODE_SERVER_PASSWORD is set
// (packages/opencode/src/server/auth.ts). Perci mints a password per launch,
// starts the server with it, and injects the matching credentials into the
// webview session — so the embed authenticates without ever prompting. The
// password lives in memory only and is passed to the child through env rather
// than argv, keeping it out of the process table.
const OPENCODE_PORT = 4096;
const OPENCODE_URL = `http://127.0.0.1:${OPENCODE_PORT}`;
const OPENCODE_USERNAME = 'opencode';
const OPENCODE_PARTITION = 'persist:perci-opencode';
const opencodeServerPassword = randomUUID();
let opencodeServerProcess = null;

function opencodeAuthHeader() {
  const raw = `${OPENCODE_USERNAME}:${opencodeServerPassword}`;
  return `Basic ${Buffer.from(raw).toString('base64')}`;
}

function configureOpencodeWebviewSession() {
  const opencodeSession = session.fromPartition(OPENCODE_PARTITION);
  opencodeSession.webRequest.onBeforeSendHeaders(
    {
      urls: [
        `http://127.0.0.1:${OPENCODE_PORT}/*`,
        `http://localhost:${OPENCODE_PORT}/*`,
      ],
    },
    (details, callback) => {
      callback({
        requestHeaders: {
          ...(details.requestHeaders || {}),
          Authorization: opencodeAuthHeader(),
        },
      });
    }
  );
}

function configureProtectedGuestSessions() {
  for (const policy of GUEST_POLICIES) {
    const guestSession = session.fromPartition(policy.partition);
    protectedGuestSessions.set(policy.id, guestSession);
    guestSession.setPermissionCheckHandler(() => false);
    guestSession.setPermissionRequestHandler((_webContents, _permission, callback) => callback(false));
  }

  for (const guestSession of new Set(protectedGuestSessions.values())) {
    guestSession.on('will-download', (event, item, webContents) => {
      const currentPolicy = protectedPolicyForWebContents(webContents);
      const downloadPolicy = policyForOrigin(item.getURL());
      if (currentPolicy?.id === 'keysafe' && isAllowedKeySafeDownload({
        url: item.getURL(),
        filename: item.getFilename(),
        mimeType: item.getMimeType(),
      })) {
        item.once('done', (_downloadEvent, state) => {
          appendRendererLog(`keysafe-download-finished state=${state === 'completed' ? 'completed' : 'interrupted'}`);
        });
        return;
      }
      if (currentPolicy || downloadPolicy) {
        event.preventDefault();
        appendRendererLog(`blocked-protected-webview-download id=${currentPolicy?.id || downloadPolicy?.id || 'unknown'}`);
      }
    });
  }
}

function configureKeySafeSessionAuthentication() {
  const keysafeSession = session.fromPartition('persist:perci-localhost');
  keysafeSession.webRequest.onBeforeSendHeaders(
    { urls: [`${KEYSAFE_ORIGIN}/*`] },
    (details, callback) => {
      const guest = webContents.fromId(details.webContentsId);
      const currentOrigin = guest ? policyForOrigin(guest.getURL())?.origin : null;
      const initialMainFrame = details.resourceType === 'mainFrame' && guest?.getType() === 'webview' && !guest.getURL();
      if (guest?.getType() !== 'webview' || !keySafeGuestIds.has(guest.id) || (currentOrigin !== KEYSAFE_ORIGIN && !initialMainFrame)) {
        callback({ cancel: true });
        return;
      }
      callback({
        requestHeaders: {
          ...(details.requestHeaders || {}),
          Authorization: `Bearer ${keysafeServerToken}`,
        },
      });
    },
  );
}

function protectedPolicyForWebContents(contents) {
  if (!contents || contents.getType() !== 'webview') return null;
  const policy = policyForOrigin(contents.getURL());
  if (!policy) return null;
  return contents.session === protectedGuestSessions.get(policy.id) ? policy : null;
}

function blockProtectedGuestNavigation(contents, event, url, eventName) {
  const policy = protectedPolicyForWebContents(contents);
  if (!policy || isNavigationAllowed(policy, url)) return false;
  event.preventDefault();
  appendRendererLog(`blocked-protected-webview-${eventName} id=${policy.id}`);
  return true;
}

app.whenReady().then(() => {
  try {
    configureMarkItDownWebviewSession();
    configureYouTubeWebviewSession();
    configureOpencodeWebviewSession();
    configureProtectedGuestSessions();
    configureKeySafeSessionAuthentication();

    const localhostSession = session.fromPartition('persist:perci-localhost');
    const klipitSource = app.isPackaged ? 'bundled' : 'development';
    const klipitPath = getKlipitExtensionPath(process.resourcesPath, app.isPackaged);

    let klipitLoadError = null;
    const klipitLoadPromise = localhostSession.loadExtension(klipitPath, { allowFileAccess: true }).catch(err => {
      console.error('Failed to load Klipit extension:', err);
      klipitLoadError = err;
      return null;
    });

    ipcMain.handle('get-klipit-extension-id', async () => {
      await klipitLoadPromise;
      const exts = localhostSession.getAllExtensions();
      const klipit = exts.find(e => e.name === 'Klipit');
      return klipit ? klipit.id : null;
    });

    ipcMain.handle('get-klipit-health', async () => {
      await klipitLoadPromise;
      const exts = localhostSession.getAllExtensions();
      const klipit = exts.find(e => e.name === 'Klipit');
      return normalizeKlipitHealth(klipit, klipitSource, klipitLoadError);
    });
  } catch (err) {
    console.error('Error setting up localhost session:', err);
  }

  // Seed the active-ports snapshot for coding agents shortly after startup,
  // off the critical path so it doesn't delay window creation.
  setTimeout(() => writePortsSnapshot(), 2500);

  if (!isDev) {
    autoUpdater.autoDownload = false;

    // electron-updater is silent by default: with no logger and no 'error'
    // listener every failure disappears, which is how v0.43.0–v0.45.8 shipped
    // with a broken updater for weeks without a single visible symptom.
    // Route it into the same log file the rest of the main process uses.
    autoUpdater.logger = {
      info: () => appendRendererLog('[updater] event=info'),
      warn: () => appendRendererLog('[updater] event=warning'),
      error: () => appendRendererLog('[updater] event=error'),
      debug: () => appendRendererLog('[updater] event=debug'),
    };

    // Helper to send state to renderer once mainWindow is ready
    function sendUpdaterState(state) {
      if (mainWindow && !mainWindow.isDestroyed()) {
        mainWindow.webContents.send('updater:state', state);
      }
    }

    // An EventEmitter with no 'error' listener rethrows, so this handler is
    // what keeps a failed update check from taking down the main process.
    autoUpdater.on('error', () => {
      appendRendererLog('[updater] event=error');
      sendUpdaterState('error');
    });

    autoUpdater.on('update-not-available', (info) => {
      appendRendererLog(`[updater] up to date (v${info && info.version})`);
    });

    autoUpdater.on('update-available', (info) => {
      sendUpdaterState('available');
      dialog.showMessageBox({
        type: 'info',
        title: 'Update Available',
        message: `A new version of Perci is available (v${info.version}). Do you want to download it now?`,
        buttons: ['Yes', 'Later']
      }).then((result) => {
        if (result.response === 0) {
          sendUpdaterState('downloading');
          autoUpdater.downloadUpdate();
        }
      });
    });

    autoUpdater.on('update-downloaded', () => {
      sendUpdaterState('downloaded');
      dialog.showMessageBox({
        type: 'info',
        title: 'Update Ready',
        message: 'The update has been downloaded. Restart the application to apply the updates.',
        buttons: ['Restart', 'Later']
      }).then((result) => {
        if (result.response === 0) {
          autoUpdater.quitAndInstall();
        }
      });
    });

    ipcMain.handle('updater:action', (event, action) => {
      if (action === 'download') {
        sendUpdaterState('downloading');
        autoUpdater.downloadUpdate();
      } else if (action === 'install') {
        autoUpdater.quitAndInstall();
      }
    });

    if (!process.env.PERCI_TEST_USER_DATA_DIR) autoUpdater.checkForUpdates();
  }

  app.on('web-contents-created', (_event, contents) => {
    // Intercept reload and force reload shortcuts globally (including in webviews).
    // These are Perci shortcuts, so they must always reload the shell rather than
    // whichever embedded surface currently owns keyboard focus.
    contents.on('before-input-event', (event, input) => {
      if (input.type !== 'keyDown') return;

      const isCmdOrCtrl = process.platform === 'darwin' ? input.meta : input.control;
      if (isCmdOrCtrl && input.key.toLowerCase() === 'r') {
        event.preventDefault();
        reloadPerciWindow(input.shift);
      }
    });

    // Google's GIS popup (allowed below) is created with the default UA, which
    // Google rejects. Reload it with a clean Chrome UA so consent can proceed.
    if (contents.getType() === 'webview') {
      contents.on('did-create-window', (child, details) => {
        const cleanUA = cleanedDesktopUserAgent(contents.session.getUserAgent());
        void child.webContents.loadURL(details.url, { userAgent: cleanUA });
      });
      // Webview guest crashes weren't logged anywhere — attachRendererDiagnostics
      // only covers the main window. A silent guest crash/recovery while a
      // native dialog (e.g. MarkItDownUI's file picker) is open would look
      // exactly like a visual "flash" without the dialog itself closing.
      contents.on('render-process-gone', (_e, details) => {
        appendRendererLog(`webview-render-process-gone reason=${details.reason} exitCode=${details.exitCode}`);
      });
      contents.on('did-fail-load', (_e, errorCode) => {
        if (errorCode === -3) return; // aborted, usually benign (e.g. navigated away)
        appendRendererLog(`webview-did-fail-load code=${errorCode}`);
      });
    }

    contents.setWindowOpenHandler(({ url }) => {
      const protectedPolicy = protectedPolicyForWebContents(contents);
      if (protectedPolicy) {
        appendRendererLog(`blocked-protected-webview-popup id=${protectedPolicy.id}`);
        return { action: 'deny' };
      }

      if (isBundledAssetDocumentUrl(url)) {
        appendRendererLog('blocked-global-bundled-asset-window');
        return { action: 'deny' };
      }

      // Let Google sign-in popups from embedded webviews open in-app so the
      // token can post back to the opener; everything else is still ejected.
      if (contents.getType() === 'webview' && isGoogleOAuthUrl(url)) {
        appendRendererLog('allow-webview-google-oauth-window');
        return { action: 'allow' };
      }

      // target="_blank"/window.open popups from a webview land here. Route
      // the URL to the renderer via IPC (LocalhostMode's onWebviewOpenInTab
      // -> handleNewTab) so a new Perci tab is created instead of opening
      // the system browser. Plain <a> links are handled by the will-navigate
      // branch below, since they navigate in place rather than opening a window.
      if (contents.getType() === 'webview') {
        try {
          const parsed = new URL(url);
          const isLocalhost = parsed.hostname === 'localhost' || parsed.hostname === '127.0.0.1' || parsed.hostname === '::1';
          if (isLocalhost) {
            appendRendererLog('webview-new-window-routed-to-tab');
            if (mainWindow && !mainWindow.isDestroyed()) {
              mainWindow.webContents.send('webview:open-in-tab', url);
            }
            return { action: 'deny' };
          }
          if (parsed.protocol === 'http:' || parsed.protocol === 'https:') {
            appendRendererLog('webview-new-window-open-external');
            shell.openExternal(url);
            return { action: 'deny' };
          }
        } catch (err) {
          appendRendererLog('blocked-webview-window-open reason=invalid-url');
        }
        return { action: 'deny' };
      }

      try {
        const parsed = new URL(url);
        if (parsed.protocol === 'http:' || parsed.protocol === 'https:') {
          shell.openExternal(url);
        }
      } catch (err) {
        appendRendererLog('blocked-global-window-open reason=invalid-url');
      }
      appendRendererLog('blocked-global-window-open');
      return { action: 'deny' };
    });

    contents.on('will-navigate', (event, url) => {
      if (blockProtectedGuestNavigation(contents, event, url, 'navigation')) return;
      if (policyForOrigin(url)?.id === 'keysafe' && policyForOrigin(contents.getURL())?.id !== 'keysafe') {
        event.preventDefault();
        appendRendererLog('blocked-keysafe-navigation-from-generic-guest');
        return;
      }
      if (!isDev && isBundledAssetDocumentUrl(url)) {
        event.preventDefault();
        appendRendererLog('blocked-global-bundled-asset-navigation');
        return;
      }

      // Plain <a href> clicks navigate the webview in place like a normal
      // browser. Users who want a new tab can right-click → "Open in new tab"
      // or the app can use target="_blank"/window.open (handled by
      // setWindowOpenHandler above). Google OAuth redirects are also allowed
      // to proceed in place to keep the callback tied to this frame.
      if (contents.getType() === 'webview' && !isGoogleOAuthUrl(url)) {
        appendRendererLog('webview-navigation-in-place');
      }
    });

    contents.on('will-redirect', (event, url) => {
      if (blockProtectedGuestNavigation(contents, event, url, 'redirect')) return;
      if (policyForOrigin(url)?.id === 'keysafe' && policyForOrigin(contents.getURL())?.id !== 'keysafe') {
        event.preventDefault();
        appendRendererLog('blocked-keysafe-redirect-from-generic-guest');
      }
    });
  });

  if (!process.env.PERCI_TEST_USER_DATA_DIR) startTerminalServer();
  createMenu();
  createSplashWindow();
  createWindow();

  app.on('activate', () => {
    if (BrowserWindow.getAllWindows().length === 0) {
      createWindow();
    }
  });
});

