async function saveBarsApiKeys(incoming = {}) {
  const patch = {};
  for (const provider of BARS_CLOUD_PROVIDERS) {
    const value = typeof incoming[provider.id] === 'string' ? incoming[provider.id].trim() : '';
    if (value) patch[provider.keyName] = value;
  }
