// OpenRouter and DeepInfra both publish their catalog publicly in the OpenAI
// {data:[{id}]} shape, so neither needs a key to list models.
const BARS_PUBLIC_CATALOG_PROVIDERS = new Set(['openrouter', 'deepinfra']);
// DeepInfra returns image, video, speech, embedding and reranker models
// alongside chat ones; only the tags distinguish them (ids do not).
const DEEPINFRA_NON_CHAT_TAGS = new Set(['image-gen', 'embed', 'tts', 'video-gen', 'stt']);

async function fetchBarsCloudModels(provider, key) {
  if (BARS_PUBLIC_CATALOG_PROVIDERS.has(provider.id)) {
    const result = await requestJson(provider.modelsPath, 12000, { Accept: 'application/json' });
    if (result.ok) {
      const entries = Array.isArray(result.data?.data) ? result.data.data : [];
      const ids = entries
        .filter(model => provider.id !== 'deepinfra'
          || !(model?.metadata?.tags || []).some(tag => DEEPINFRA_NON_CHAT_TAGS.has(tag)))
        .map(model => model.id)
        .filter(Boolean);
      return Array.from(new Set([provider.defaultModel, ...ids].filter(Boolean)));
    }
    return provider.models;
  }
  if (provider.id === 'groq' && key) {
    const result = await requestJson(provider.modelsPath, 8000, { Authorization: 'Bearer ' + key });
    if (result.ok) {
      const ids = Array.isArray(result.data?.data) ? result.data.data.map(model => model.id).filter(Boolean) : [];
      if (ids.length) return ids;
    }
  }
  return provider.models;
}

async function detectBarsProviders() {
  const keys = await getBarsApiKeys();
  const [localProviders, cloudProviders] = await Promise.all([
    Promise.all(BARS_LOCAL_PROVIDERS.map(detectBarsLocalProvider)),
    Promise.all(BARS_CLOUD_PROVIDERS.map(async provider => ({
      ...provider,
      available: Boolean(keys[provider.id]),
      configured: Boolean(keys[provider.id]),
      models: await fetchBarsCloudModels(provider, keys[provider.id])
    })))
  ]);
  const providers = [...localProviders, ...cloudProviders];
  return {
    generatedAt: Date.now(),
    providers,
    selectedId: providers.find(provider => provider.available)?.id || providers[0]?.id || null,
    keyStatus: await getBarsApiKeyStatus()
  };
}

function compactBarsIdeas(ideas) {
  return (Array.isArray(ideas) ? ideas : []).slice(0, 100).map((idea, index) => {
    const tags = Array.isArray(idea.tags) && idea.tags.length ? ' tags: ' + idea.tags.join(', ') : '';
    const next = idea.next ? ' next: ' + idea.next : '';
    return [
      (index + 1) + '. ' + (idea.title || 'Untitled'),
      'status: ' + (idea.status || 'New') + '; category: ' + (idea.category || idea.kind || 'Uncategorized') + '; impact: ' + (idea.impact || '3') + '; effort: ' + (idea.effort || '3') + ';' + tags + next,
      idea.notes ? 'notes: ' + idea.notes : ''
    ].filter(Boolean).join('\n');
  }).join('\n\n');
}

function buildBarsMessages(question, ideas) {
  const context = compactBarsIdeas(ideas);
  return [
    {
      role: 'system',
      content: 'You are a concise assistant for BARS, a personal idea notebook inside Perci. Answer only from the supplied bars unless the user asks for general planning advice. If the notes do not contain enough evidence, say what is missing. Keep next steps concrete.'
    },
    {
      role: 'user',
      content: 'Question:\n' + question + '\n\nBars:\n' + (context || 'No bars saved yet.')
    }
  ];
}

function getBarsProvider(providerId) {
  return [...BARS_LOCAL_PROVIDERS, ...BARS_CLOUD_PROVIDERS].find(provider => provider.id === providerId);
}

async function askBarsOpenAiCompatible(provider, key, model, messages, endpointOverride = '') {
  const chatUrl = provider.kind === 'local'
    ? (endpointOverride || provider.endpoint).replace(/\/$/, '') + provider.chatPath
    : provider.chatPath;
  const payload = await fetchJsonStrict(chatUrl, {
    method: 'POST',
    timeoutMs: 90000,
    headers: {
      'Content-Type': 'application/json',
      ...(key ? { Authorization: 'Bearer ' + key } : {}),
      ...(provider.extraHeaders || {})
    },
    body: JSON.stringify({ model, messages, temperature: 0.2, stream: false })
  });
  return payload?.choices?.[0]?.message?.content?.trim() || 'No response text returned.';
}

async function askBarsAnthropic(provider, key, model, messages) {
  const payload = await fetchJsonStrict(provider.chatPath, {
    method: 'POST',
    timeoutMs: 90000,
    headers: {
      'Content-Type': 'application/json',
      'x-api-key': key,
      'anthropic-version': '2023-06-01'
    },
    body: JSON.stringify({
      model,
      max_tokens: 1200,
      system: messages[0].content,
      messages: [{ role: 'user', content: messages[1].content }]
    })
  });
  return Array.isArray(payload?.content)
    ? payload.content.map(part => part?.text || '').join('').trim() || 'No response text returned.'
    : 'No response text returned.';
}

async function askBarsGoogle(provider, key, model, messages) {
  const payload = await fetchJsonStrict(provider.chatPath + '/' + encodeURIComponent(model) + ':generateContent', {
    method: 'POST',
    timeoutMs: 90000,
    headers: { 'Content-Type': 'application/json', 'x-goog-api-key': key },
    body: JSON.stringify({
      system_instruction: { parts: [{ text: messages[0].content }] },
      contents: [{ role: 'user', parts: [{ text: messages[1].content }] }],
      generationConfig: { maxOutputTokens: 1200 }
    })
  });
  const parts = payload?.candidates?.[0]?.content?.parts;
  return Array.isArray(parts)
    ? parts.map(part => part?.text || '').join('').trim() || 'No response text returned.'
    : 'No response text returned.';
}

async function askBarsOllama(provider, model, messages) {
  const payload = await fetchJsonStrict(provider.endpoint + provider.chatPath, {
    method: 'POST',
    timeoutMs: 90000,
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ model, messages, stream: false })
  });
  return payload?.message?.content?.trim() || 'No response text returned.';
}

async function askBars(payload = {}) {
  const provider = getBarsProvider(payload.providerId);
  if (!provider) throw new Error('Unknown Bars AI provider.');
  const messages = buildBarsMessages(payload.question || '', payload.ideas || []);
  const model = String(payload.model || provider.defaultModel || 'local-model').trim();
  if (!model) throw new Error('Choose a model first.');

  if (provider.kind === 'local') {
    if (provider.api === 'ollama') {
      return { providerId: provider.id, model, answer: await askBarsOllama(provider, model, messages) };
    }
    const detected = await detectBarsLocalProvider(provider);
    if (!detected.available) throw new Error(provider.name + ' is not reachable.');
    return { providerId: provider.id, model, answer: await askBarsOpenAiCompatible(detected, '', model, messages, detected.endpoint) };
  }

  const keys = await getBarsApiKeys();
  const key = keys[provider.id];
  if (!key) throw new Error('Add a ' + provider.name + ' API key in Bars settings first.');

  const answer = provider.api === 'anthropic'
    ? await askBarsAnthropic(provider, key, model, messages)
    : provider.api === 'google'
      ? await askBarsGoogle(provider, key, model, messages)
      : await askBarsOpenAiCompatible(provider, key, model, messages);

  return { providerId: provider.id, model, answer };
}

async function transcribeVoice(payload = {}) {
  const keys = await getBarsApiKeys();
  const { buffer, extension, mimeType, providers } = prepareVoiceTranscription(payload, keys);
  let lastError = null;

  for (const { endpoint, key, model, providerId } of providers) {
    const formData = new FormData();
    formData.append('model', model);
    const blob = new Blob([buffer], { type: mimeType });
    formData.append('file', blob, `recording.${extension}`);

    try {
      const response = await fetchJsonStrict(endpoint, {
        method: 'POST',
        timeoutMs: 60000,
        maxResponseBytes: MAX_VOICE_RESPONSE_BYTES,
        headers: { Authorization: `Bearer ${key}` },
        body: formData,
      });
      const text = typeof response?.text === 'string' ? response.text.trim() : '';
      if (!text) throw new Error('The transcription service returned no text.');
      return { providerId, text };
    } catch (error) {
      lastError = error;
    }
  }

  throw lastError || new Error('Voice transcription failed.');
}

const MARKITDOWN_VISION_MODEL = 'openai/gpt-4o-mini';
const MARKITDOWN_VISION_MAX_DATA_URL_BYTES = 22 * 1024 * 1024;
const MARKITDOWN_IMAGE_DATA_URL_RE = /^data:image\/(png|jpe?g|webp|gif);base64,/i;
const MARKITDOWN_UI_PORT = 8920;
const MARKITDOWN_UI_URL = `http://127.0.0.1:${MARKITDOWN_UI_PORT}`;
const MARKITDOWN_UI_WEBUI_DIR = process.env.MARKITDOWN_UI_WEBUI_DIR
  || path.join(app.getPath('home'), 'markitdown-ui', 'webui');
const MARKITDOWN_UI_RUNNER = path.join(MARKITDOWN_UI_WEBUI_DIR, 'run.sh');
const MARKITDOWN_EXIFTOOL_CANDIDATES = ['/opt/homebrew/bin/exiftool', '/usr/local/bin/exiftool', '/usr/bin/exiftool'];
const MARKITDOWN_BREW_CANDIDATES = ['/opt/homebrew/bin/brew', '/usr/local/bin/brew'];
let markitdownServerProcess = null;

function findExistingExecutable(candidates) {
  for (const candidate of candidates) {
    try {
      if (fsSync.existsSync(candidate)) return candidate;
    } catch {
      /* ignore unreadable candidates */
    }
  }
  return null;
}

function findExecutableOnPath(command) {
  const result = spawnSync('which', [command], {
    encoding: 'utf8',
    env: process.env,
    shell: false
  });
  return result.status === 0 ? result.stdout.trim() : '';
}

function findExifToolExecutable() {
  return findExistingExecutable(MARKITDOWN_EXIFTOOL_CANDIDATES) || findExecutableOnPath('exiftool');
}

function findBrewExecutable() {
  return findExistingExecutable(MARKITDOWN_BREW_CANDIDATES) || findExecutableOnPath('brew');
}

function normalizeMarkdownImageName(filename) {
  const name = typeof filename === 'string' && filename.trim() ? filename.trim() : 'image';
  return name.replace(/`/g, "'");
}

async function describeMarkItDownImage(payload = {}) {
  const dataUrl = typeof payload.dataUrl === 'string' ? payload.dataUrl : '';
  if (!MARKITDOWN_IMAGE_DATA_URL_RE.test(dataUrl)) {
    throw new Error('MarkItDownUI can only analyze PNG, JPEG, WebP, or GIF image uploads.');
  }
  if (Buffer.byteLength(dataUrl, 'utf8') > MARKITDOWN_VISION_MAX_DATA_URL_BYTES) {
    throw new Error('Image is too large for Perci OpenRouter vision extraction.');
  }

  const data = await readAppData();
  const key = typeof data.openrouter_key === 'string' ? data.openrouter_key : '';
  if (!key) {
    throw new Error('Add an OpenRouter API key in Perci Settings first.');
  }

  const filename = normalizeMarkdownImageName(payload.filename);
  const response = await fetchJsonStrict('https://openrouter.ai/api/v1/chat/completions', {
    method: 'POST',
    timeoutMs: 120000,
    headers: {
      'Content-Type': 'application/json',
      Authorization: 'Bearer ' + key,
      'HTTP-Referer': 'https://perci.local',
      'X-Title': 'Perci MarkItDownUI'
    },
    body: JSON.stringify({
      model: MARKITDOWN_VISION_MODEL,
      temperature: 0.1,
      max_tokens: 1800,
      stream: false,
      messages: [
        {
          role: 'system',
          content: 'You convert images into useful Markdown. Extract visible text faithfully. Preserve tables, lists, labels, forms, and UI structure when possible. If the image is mostly visual, give a concise factual description. Do not invent hidden details.'
        },
        {
          role: 'user',
          content: [
            {
              type: 'text',
              text: 'Convert this image upload into useful Markdown for MarkItDownUI. Filename: `' + filename + '`.'
            },
            {
              type: 'image_url',
              image_url: { url: dataUrl }
            }
          ]
        }
      ]
    })
  });

  const markdown = response?.choices?.[0]?.message?.content?.trim();
  if (!markdown) throw new Error('OpenRouter returned no vision text.');
  return {
    model: MARKITDOWN_VISION_MODEL,
    markdown: markdown.startsWith('#')
      ? markdown
      : '# ' + filename + '\n\n' + markdown + '\n\n---\n\nVision model: `' + MARKITDOWN_VISION_MODEL + '`'
  };
}

async function getMarkItDownServerStatus() {
  const health = await requestJson(`${MARKITDOWN_UI_URL}/api/health`, 1200);
  return {
    ok: health.ok,
    url: MARKITDOWN_UI_URL,
    port: MARKITDOWN_UI_PORT,
    pid: markitdownServerProcess && !markitdownServerProcess.killed ? markitdownServerProcess.pid : null,
    error: health.ok ? '' : health.error || `HTTP ${health.status || 'unreachable'}`
  };
}

async function waitForMarkItDownServer(timeoutMs = 20000) {
  const startedAt = Date.now();
  let lastStatus = await getMarkItDownServerStatus();
  while (!lastStatus.ok && Date.now() - startedAt < timeoutMs) {
    await new Promise(resolve => setTimeout(resolve, 500));
    lastStatus = await getMarkItDownServerStatus();
  }
  return lastStatus;
}

async function startMarkItDownServer() {
  const current = await getMarkItDownServerStatus();
  if (current.ok) {
    return { ...current, started: false, message: 'MarkItDownUI is already running.' };
  }

  // Clear the cache for the markitdown partition so local asset fixes apply correctly
  try {
    const markitdownSession = session.fromPartition('persist:perci-markitdown');
    await markitdownSession.clearCache();
  } catch (err) {
    console.error('Failed to clear MarkItDownUI cache:', err);
  }

  if (markitdownServerProcess && !markitdownServerProcess.killed && markitdownServerProcess.exitCode == null) {
    const status = await waitForMarkItDownServer();
    return { ...status, started: false, message: status.ok ? 'MarkItDownUI is starting.' : status.error };
  }

  if (!fsSync.existsSync(MARKITDOWN_UI_RUNNER)) {
    throw new Error(`MarkItDownUI launcher not found at ${MARKITDOWN_UI_RUNNER}`);
  }

  markitdownServerProcess = spawn(MARKITDOWN_UI_RUNNER, [], {
    cwd: MARKITDOWN_UI_WEBUI_DIR,
    env: { ...process.env, MARKITDOWN_UI_PORT: String(MARKITDOWN_UI_PORT) },
    stdio: ['ignore', 'pipe', 'pipe'],
    shell: false
  });

  markitdownServerProcess.stdout?.on('data', chunk => {
    appendRendererLog(`[markitdown] event=stdout bytes=${Buffer.byteLength(chunk)}`);
  });
  markitdownServerProcess.stderr?.on('data', chunk => {
    appendRendererLog(`[markitdown] event=stderr bytes=${Buffer.byteLength(chunk)}`);
  });
  markitdownServerProcess.on('exit', (code, signal) => {
    appendRendererLog(`[markitdown] exited code=${code ?? ''} signal=${signal ?? ''}`);
  });
  markitdownServerProcess.on('error', () => {
    appendRendererLog('[markitdown] event=process-error');
  });

  const status = await waitForMarkItDownServer();
  if (!status.ok) {
    return { ...status, started: true, message: status.error || 'MarkItDownUI did not become ready yet.' };
  }
  return { ...status, started: true, message: 'MarkItDownUI started.' };
}

async function installMarkItDownExifTool() {
  const existing = findExifToolExecutable();
  if (existing) {
    return { ok: true, installed: false, path: existing, message: 'ExifTool is already installed.' };
  }

  const brew = findBrewExecutable();
  if (!brew) {
    throw new Error('Homebrew is not installed or not available on PATH.');
  }

  return new Promise((resolve, reject) => {
    const child = spawn(brew, ['install', 'exiftool'], {
      env: process.env,
      stdio: ['ignore', 'pipe', 'pipe'],
      shell: false
    });
    let output = '';
    const append = (chunk) => {
      output = (output + String(chunk)).slice(-12000);
      appendRendererLog(`[markitdown:exiftool] event=output bytes=${Buffer.byteLength(chunk)}`);
    };
    child.stdout?.on('data', append);
    child.stderr?.on('data', append);
    child.on('error', err => reject(err));
    child.on('exit', (code) => {
      const installedPath = findExifToolExecutable();
      if (code === 0 && installedPath) {
        resolve({ ok: true, installed: true, path: installedPath, message: 'ExifTool installed.' });
        return;
      }
      if (installedPath) {
        resolve({ ok: true, installed: true, path: installedPath, message: 'ExifTool installed, but Homebrew returned a warning.' });
        return;
      }
      reject(new Error(output.trim() || `Homebrew exited with code ${code}.`));
    });
  });
}


