  }
  try {
    const result = await codexAccountClient.startChatGptLogin();
    const authUrl = trustedCodexAuthUrl(result.authUrl);
    if (!authUrl) return { ok: false, error: 'Codex returned an untrusted sign-in URL.' };
    await shell.openExternal(authUrl);
    return { ok: true, loginId: result.loginId };
  } catch (error) {
    return { ok: false, error: error?.message || 'Could not start Codex sign-in.' };
  }
});

ipcMain.handle('agent-jobs:list', async (event, options = {}) => {
  const limit = Number(options.limit) || 24;
  const source = options.source || null;

  const allJobs = [];
  for (const [, jobRecord] of agentJobs) {
    if (source && jobRecord.job.source !== source) continue;
    allJobs.push(serializeJob(jobRecord.job));
  }

  // Sort by created_at descending, then slice
  allJobs.sort((a, b) => new Date(b.created_at).getTime() - new Date(a.created_at).getTime());
  return allJobs.slice(0, limit);
});

// Slim status lookup for a single job — lets panels track a launched run
// without pulling every job (and its full output) on each poll.
ipcMain.handle('agent-jobs:get', async (event, jobId) => {
  const entry = agentJobs.get(jobId);
  if (!entry) return null;
  const { id, agent, status, created_at, started_at, completed_at, exit_code } = entry.job;
  return { id, agent, status, created_at, started_at, completed_at, exit_code };
});

