// Lightweight endpoint for Mission Control's pulse visualization. Returns
// counts and recent run summaries mapped to Mission Control lane types.
ipcMain.handle('agent-jobs:activity', async () => {
  const AGENT_TO_LANE = {
    aider: 'terminal',
    antigravity_cli: 'terminal',
    claude_code: 'code',
    codex: 'code',
    command_code: 'code',
    copilot: 'code',
    cursor_cli: 'code',
    hermes: 'general',
    jan: 'general',
    openclaw: 'gateway',
    openhands: 'code',
    opencode: 'code',
    perci_code: 'code',
    qwen_code: 'code',
    jules: 'general',
  };

  const counts = { terminal: 0, cowork: 0, code: 0, build: 0, gateway: 0, general: 0 };
  const recent = [];
  const debug = [];

  for (const [, jobRecord] of agentJobs) {
    const job = jobRecord.job;
    const isActive = ['pending', 'claimed', 'running', 'retry_queued'].includes(job.status);
    const completedAt = job.completed_at ? new Date(job.completed_at).getTime() : null;
    const isRecent = completedAt && (Date.now() - completedAt) < 120000;
    if (!isActive && !isRecent) continue;

    debug.push({ id: job.id.slice(0,8), agent: job.agent, status: job.status, isActive, isRecent });

    const lane = AGENT_TO_LANE[job.agent] || 'general';
    counts[lane] += 1;

    recent.push({
      id: job.id,
      agent: job.agent,
      lane,
      status: job.status,
      title: (job.prompt || '').slice(0, 60),
      created_at: job.created_at,
    });
  }

  recent.sort((a, b) => new Date(b.created_at).getTime() - new Date(a.created_at).getTime());

  const result = {
    counts,
    recent: recent.slice(0, 20),
    total: Object.values(counts).reduce((sum, n) => sum + n, 0),
  };

  console.log('[agent-activity]', JSON.stringify({ total: result.total, debug, totalJobs: agentJobs.size }));
  return result;
});

ipcMain.handle('agent-jobs:queue', async (event, { agent, prompt, working_directory, model, reasoning_effort } = {}) => {
  if (!agent || !prompt) {
    return { ok: false, error: 'Missing agent or prompt.' };
  }
  const requestedModel = typeof model === 'string' ? model.trim() : '';
  if (requestedModel && !SAFE_MODEL_PATTERN.test(requestedModel)) {
    return { ok: false, error: 'Model name contains unsupported characters.' };
  }
  const requestedReasoningEffort = typeof reasoning_effort === 'string' ? reasoning_effort.trim() : '';
  if (requestedReasoningEffort && (agent !== 'codex' || !SAFE_CODEX_REASONING_EFFORTS.has(requestedReasoningEffort))) {
    return { ok: false, error: 'Unsupported Codex reasoning effort.' };
  }

  // Refresh the active-ports snapshot so the agent we're about to spawn can read
  // current port state from ~/.config/agent-rules/ instead of running `lsof`.
  writePortsSnapshot();

  const config = AGENT_SPAWN_CONFIG[agent];
  if (!config) {
    return { ok: false, error: `Unknown agent: ${agent}. No CLI command is configured.` };
  }
  const { command, candidates } = await resolveAgentCommand(config);
  if (!command) {
    return { ok: false, error: `No CLI command found for ${agent}. Tried: ${candidates.join(', ') || 'none'}.` };
  }

  let spawnEnv = { ...process.env };
  if (typeof config.prepareEnv === 'function') {
    spawnEnv = config.prepareEnv(spawnEnv);
  }
  let codexStatus = null;
  if (config.needsAuth) {
    const authResult = typeof config.authCheck === 'function'
      ? await config.authCheck({ command, env: spawnEnv })
      : { ok: false, error: `${agent} requires authentication before it can run.` };
    if (!authResult.ok) return authResult;
    codexStatus = authResult.codexStatus || null;
  }

  let effectiveModel = requestedModel;
  let replacedModel = null;
  if (agent === 'codex' && requestedModel && codexStatus?.subscription) {
    try {
      const selection = selectCodexSubscriptionModel(
        requestedModel,
        await codexAccountClient.listModels(),
      );
      effectiveModel = selection.model;
      replacedModel = selection.requestedModel;
    } catch {
      effectiveModel = '';
      replacedModel = requestedModel;
    }
  }

  const jobId = generateJobId();
  const now = new Date().toISOString();

  const jobRecord = {
    id: jobId,
    agent,
    type: agent, // alias for compatibility
    status: 'pending',
    prompt,
    prompt_text: prompt,
    prompt_preview: prompt?.slice(0, 120) || null,
    working_directory: config.usesWorkingDirectory === false ? null : working_directory || null,
    model: effectiveModel || null,
    ...(replacedModel ? { requested_model: replacedModel } : {}),
    reasoning_effort: requestedReasoningEffort || null,
    source: 'agents_page',
    created_at: now,
    started_at: null,
    completed_at: null,
    exit_code: null,
    output: '',
    output_kind: null,
    ...(config.outputMode === 'openclaw-json' ? { session_id: null } : {}),
    childProcess: null,
  };

  jobRecord.status = 'running';
  jobRecord.started_at = new Date().toISOString();

  const cwd = config.usesWorkingDirectory === false
    ? process.env.HOME || '/tmp'
    : normalizeWorkingDirectory(working_directory, app.getPath('home'));
  const spawnArgs = buildAgentSpawnArgs(config, prompt, effectiveModel, requestedReasoningEffort);

  let child = null;
  try {
    child = config.pty
      ? attachAgentPty(jobRecord, config, command, spawnArgs, cwd, spawnEnv, prompt)
      : attachAgentChildProcess(jobRecord, config, command, spawnArgs, cwd, spawnEnv, prompt);
    jobRecord.childProcess = child;
  } catch (err) {
    jobRecord.completed_at = new Date().toISOString();
    jobRecord.status = 'failed';
    jobRecord.exit_code = null;
    jobRecord.output_kind = 'error';
    jobRecord.output += (jobRecord.output ? '\n' : '') + `Process error: ${err.message}`;
  }

  agentJobs.set(jobId, { childProcess: child, job: jobRecord });

  return { ok: true, job: serializeJob(jobRecord) };
});

ipcMain.handle('agent-jobs:cancel', async (event, jobId) => {
  const entry = agentJobs.get(jobId);
  if (!entry) {
    return { ok: false, error: 'Job not found.' };
  }

  const { childProcess: child, job: jobRecord } = entry;

  if (jobRecord.status === 'completed' || jobRecord.status === 'failed' || jobRecord.status === 'cancelled') {
    return { ok: true, status: jobRecord.status, message: 'Job already finished.' };
  }

  // Cloud agents (Jules) have no childProcess — just mark the job as cancelled
  if (!child) {
    jobRecord.status = 'cancelled';
    jobRecord.completed_at = new Date().toISOString();
    jobRecord.output_kind = 'status';
    if (!jobRecord.output.endsWith('\n')) jobRecord.output += '\n';
    jobRecord.output += '[Cancelled by user]';
    return { ok: true, status: 'cancelled' };
  }

  // Kill the process
  try {
    if (process.platform === 'win32') {
      child.kill('SIGTERM');
    } else {
      // Negative PID kills the process group (since detached:false, this is the child)
      child.kill('SIGTERM');
    }
  } catch (err) {
    return { ok: false, error: `Failed to kill process: ${err.message}` };
  }

  jobRecord.status = 'cancelled';
  jobRecord.completed_at = new Date().toISOString();
  jobRecord.output_kind = 'status';
  if (!jobRecord.output.endsWith('\n')) jobRecord.output += '\n';
  jobRecord.output += '[Cancelled by user]';

  return { ok: true, status: 'cancelled' };
});

// ─── Jules Cloud Agent ──────────────────────────────────────────────────────
// Jules is a remote coding agent from Google Labs. Instead of spawning a
// local CLI, we POST to the Jules API and track the session asynchronously.
// The job record uses a polling mechanism (via the renderer) to check status.

const JULES_API_URL = 'https://jules.googleapis.com/v1alpha/sessions';

ipcMain.handle('jules:queue', async (event, { prompt, source = 'agents_page', repo: explicitRepo, branch: explicitBranch } = {}) => {
  if (!prompt || typeof prompt !== 'string' || !prompt.trim()) {
    return { ok: false, error: 'Missing prompt for Jules task.' };
  }

  // Read the API key from app-data (encrypted via safeStorage)
  let apiKey = '';
  try {
    const appData = await readAppData();
    apiKey = appData?.jules_api_key || '';
  } catch (_) {}

  if (!apiKey) {
    return { ok: false, error: 'Jules API key not configured. Add it in Settings → Jules.' };
  }

  // Determine the GitHub repo context.
  // Use explicit repo/branch if provided (user picked from dropdown),
  // otherwise auto-detect from the local git working directory.
  let repoFullName = explicitRepo || null;
  let startingBranch = explicitBranch || null;

  if (!repoFullName || !startingBranch) {
    try {
      const { execSync } = require('child_process');
      const gitDir = execSync('git rev-parse --git-dir 2>/dev/null', {
        encoding: 'utf8',
        timeout: 5000,
      }).trim();

      if (gitDir) {
        const remoteUrl = execSync('git remote get-url origin 2>/dev/null', {
          encoding: 'utf8',
          timeout: 5000,
        }).trim();

        // Extract "owner/repo" from HTTPS or SSH remote URL
        const httpsMatch = remoteUrl.match(/github\.com\/([^/]+\/[^/]+?)(?:\.git)?$/);
        const sshMatch = remoteUrl.match(/github\.com:([^/]+\/[^/]+?)(?:\.git)?$/);
        const match = httpsMatch || sshMatch;
        if (match && !repoFullName) {
          repoFullName = match[1];
        }

        // Get current branch
        const branch = execSync('git branch --show-current 2>/dev/null', {
          encoding: 'utf8',
          timeout: 5000,
        }).trim();
        if (branch && !startingBranch) startingBranch = branch;
      }
    } catch (_) {
      // Git info is optional — Jules can work without it but with reduced context
    }
  }

  if (!repoFullName) {
    return { ok: false, error: 'Jules requires a GitHub repo. Select one from the dropdown or run `git remote add origin git@github.com:owner/repo.git` first.' };
  }
  if (!startingBranch) startingBranch = 'main';

  const jobId = generateJobId();
  const now = new Date().toISOString();

  const jobRecord = {
    id: jobId,
    agent: 'jules',
    type: 'jules',
    status: 'pending',
    prompt,
    prompt_text: prompt,
    prompt_preview: prompt?.slice(0, 120) || null,
    working_directory: null,
    model: null,
    source,
    created_at: now,
    started_at: null,
    completed_at: null,
    exit_code: null,
    output: '',
    output_kind: null,
    childProcess: null,
    session_id: null,
    pr_url: null,
    repo: repoFullName,
    branch: startingBranch,
  };

  // Build the Jules payload matching the action.yaml format
  const julesPayload = {
    prompt,
    sourceContext: {
      source: `sources/github/${repoFullName}`,
      githubRepoContext: {
        startingBranch,
      },
    },
    requirePlanApproval: false,
    automationMode: 'AUTO_CREATE_PR',
  };

  // Fire the API call (don't block the IPC handler response)
  try {
    const https = require('https');
    const http = require('http');

    const body = JSON.stringify(julesPayload);
    const url = new URL(JULES_API_URL);

    const reqOptions = {
      hostname: url.hostname,
      port: url.port || 443,
      path: url.pathname,
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(body),
        'X-Goog-Api-Key': apiKey,
      },
      timeout: 30000,
    };

    const req = https.request(reqOptions, (res) => {
      let data = '';
      res.on('data', (chunk) => { data += chunk.toString(); });
      res.on('end', () => {
        const statusCode = res.statusCode;
        if (statusCode >= 200 && statusCode < 300) {
          try {
            const parsed = JSON.parse(data);
            jobRecord.session_id = parsed.id || parsed.sessionId || null;
            jobRecord.status = 'running';
            jobRecord.started_at = new Date().toISOString();
            jobRecord.output = `Jules session started${jobRecord.session_id ? ` (id: ${jobRecord.session_id})` : ''}. Waiting for completion...`;
            jobRecord.output_kind = 'status';
          } catch (_) {
            jobRecord.status = 'running';
            jobRecord.started_at = new Date().toISOString();
            jobRecord.output = 'Jules session accepted. Waiting for completion...';
            jobRecord.output_kind = 'status';
          }
        } else {
          jobRecord.status = 'failed';
          jobRecord.completed_at = new Date().toISOString();
          jobRecord.exit_code = statusCode;
          jobRecord.output_kind = 'error';
          try {
            const errParsed = JSON.parse(data);
            jobRecord.output = `Jules API error (${statusCode}): ${errParsed.error?.message || errParsed.message || data.slice(0, 200)}`;
          } catch (_) {
            jobRecord.output = `Jules API error (${statusCode}): ${data.slice(0, 200)}`;
          }
        }
      });
    });

    req.on('error', (err) => {
      jobRecord.status = 'failed';
      jobRecord.completed_at = new Date().toISOString();
      jobRecord.exit_code = null;
      jobRecord.output_kind = 'error';
      jobRecord.output = `Network error: ${err.message}`;
    });

    req.on('timeout', () => {
      req.destroy();
      // Don't mark as failed — the session may still be running
      jobRecord.output += '\nRequest timed out (session may still be running).';
      jobRecord.output_kind = 'status';
    });

    req.write(body);
    req.end();
  } catch (err) {
    jobRecord.status = 'failed';
    jobRecord.completed_at = new Date().toISOString();
    jobRecord.output_kind = 'error';
    jobRecord.output = `Failed to invoke Jules API: ${err.message}`;
  }

  agentJobs.set(jobId, { childProcess: null, job: jobRecord });
  return { ok: true, job: serializeJob(jobRecord) };
});

// ─── GitHub Repo Listing ───────────────────────────────────────────────────
// Used by the Jules integration to let the user pick which repo to target.
// Requires `gh` CLI to be installed and authenticated.
ipcMain.handle('github:list-repos', async () => {
  try {
    const { execSync } = require('child_process');
    // Get repos from the authenticated gh user (both owner and collaborator repos)
    const raw = execSync(
      'gh repo list --limit 100 --json nameWithOwner,url,description,defaultBranchRef --jq \'.[] | {name: .nameWithOwner, url: .url, description: .description, branch: .defaultBranchRef.name}\'',
      { encoding: 'utf8', timeout: 15000, stdio: ['ignore', 'pipe', 'pipe'] }
    ).trim();

    if (!raw) return [];

    // Parse JSON lines output
    const repos = raw.split('\n').map(line => {
      try { return JSON.parse(line); } catch { return null; }
    }).filter(Boolean);

    return repos;
  } catch (err) {
    // gh not installed or not authenticated
    return { error: err.message.includes('gh') ? 'gh CLI not found or not authenticated. Run `gh auth login`.' : err.message };
  }
});

// ─── Git Local Repo Detection ───────────────────────────────────────────────
// Returns the detected GitHub repo name and branch from the current working directory.
ipcMain.handle('git:detect-local-repo', async () => {
  try {
    const { execSync } = require('child_process');
    const remoteUrl = execSync('git remote get-url origin 2>/dev/null', {
      encoding: 'utf8',
      timeout: 5000,
    }).trim();

    const httpsMatch = remoteUrl.match(/github\.com\/([^/]+\/[^/]+?)(?:\.git)?$/);
    const sshMatch = remoteUrl.match(/github\.com:([^/]+\/[^/]+?)(?:\.git)?$/);
    const match = httpsMatch || sshMatch;
    if (!match) return null;

    const branch = execSync('git branch --show-current 2>/dev/null', {
      encoding: 'utf8',
      timeout: 5000,
    }).trim();

    return { repo: match[1], branch: branch || 'main' };
  } catch (_) {
    return null;
  }
});

// Recursive file listing
async function getFiles(dir, baseDir = dir) {
  const dirents = await fs.readdir(dir, { withFileTypes: true });
  const files = await Promise.all(dirents.map((dirent) => {
    const res = path.resolve(dir, dirent.name);

    const ignoreList = [
      'node_modules', '.git', '.vite', 'dist', 'dist_electron', 
      '.DS_Store', 'package-lock.json', 'yarn.lock', '.next', '.output'
    ];

    if (ignoreList.includes(dirent.name)) {
      return [];
    }

    return dirent.isDirectory() ? getFiles(res, baseDir) : res.replace(baseDir + path.sep, '');
  }));
  return Array.prototype.concat(...files);
}

// ─── Run Terminal Command ────────────────────────────────────────────────────
// Opens an interactive command in the system terminal (macOS Terminal.app).
// Used for auth flows like `gh auth login` that need a TTY + user interaction.
ipcMain.handle('run-terminal-command', async (event, command) => {
  assertTrustedMainFrame(event);
  if (!command || typeof command !== 'string') {
    return { ok: false, error: 'No command provided.' };
  }

  // Safety: only allow specific whitelisted commands
  const allowedCommands = new Set(['gh auth login']);
  const trimmed = command.trim();
  if (!allowedCommands.has(trimmed)) {
    return { ok: false, error: `Command not allowed: ${trimmed.split(' ')[0]}` };
  }

  try {
    if (process.platform === 'darwin') {
      // macOS: open in Terminal.app via osascript
      const script = `tell application "Terminal" to do script ${JSON.stringify(trimmed)}`;
      const result = spawnSync('osascript', ['-e', script], {
        encoding: 'utf8',
        timeout: 5000,
        stdio: ['ignore', 'pipe', 'pipe'],
      });
      if (result.error) throw result.error;
      if (result.status !== 0) throw new Error(result.stderr || 'osascript failed');
      return { ok: true, message: `Opened in Terminal: ${trimmed}` };
    } else if (process.platform === 'win32') {
      // Windows: open in a new Command Prompt window
      const child = spawn('cmd.exe', ['/c', 'start', '"Perci Terminal"', 'cmd.exe', '/k', trimmed], {
        detached: true,
        stdio: 'ignore',
      });
      child.unref();
      return { ok: true, message: `Opened in Command Prompt: ${trimmed}` };
    } else {
      // Linux: try common terminal emulators
      const termCmd = process.env.TERMINAL || 'x-terminal-emulator';
      const child = spawn(termCmd, ['-e', trimmed], {
        detached: true,
        stdio: 'ignore',
        shell: false,
      });
      child.unref();
      return { ok: true, message: `Opened in terminal: ${trimmed}` };
    }
  } catch (err) {
    return { ok: false, error: `Failed to open terminal: ${err.message}` };
  }
});

ipcMain.handle('run-local-command', async (event, { command, args = [], cwd, grantId } = {}) => {
  assertTrustedMainFrame(event);
  const executable = typeof command === 'string' ? command.trim() : '';
  if (!/^[A-Za-z0-9._+-]+$/.test(executable)) {
    return { error: 'Command must be an executable name without shell syntax.' };
  }
  if (!Array.isArray(args) || args.length > 100 || args.some(arg => typeof arg !== 'string' || arg.length > 10000)) {
    return { error: 'Command arguments must be a JSON array of strings.' };
  }
  let authorizedCwd;
  try {
    authorizedCwd = await workspaceGrants.authorize({
      grantId,
      ownerId: event.sender.id,
      capability: 'execute',
      targetPath: cwd,
    });
  } catch (error) {
    return { error: error.message };
  }

  return new Promise(resolve => {
    const child = spawn(executable, args, {
      cwd: authorizedCwd,
      env: process.env,
      stdio: ['ignore', 'pipe', 'pipe'],
      shell: false
    });
    let stdout = '';
    let stderr = '';
    let settled = false;
    const appendBounded = (current, chunk) => (current + chunk.toString()).slice(-1024 * 1024);
    const finish = result => {
      if (settled) return;
      settled = true;
      resolve(result);
    };

    child.stdout.on('data', chunk => { stdout = appendBounded(stdout, chunk); });
    child.stderr.on('data', chunk => { stderr = appendBounded(stderr, chunk); });
    child.on('error', err => finish({ error: err.message, output: stdout, stderr, exitCode: null }));
    child.on('close', exitCode => finish({ output: stdout, stderr, exitCode }));
  });
});

// ── Localhost Manager: launchctl / registry wrappers ────────────────────

// Autostart plists are always ~/Library/LaunchAgents/local.perci.<id>.plist,
// where <id> is a slug. The path arrives from the renderer, so re-derive and
// confine it here before it reaches writeFile/unlink or launchctl — otherwise
// it is an arbitrary file write and delete. Restricting the basename as well as
// the directory keeps a compromised renderer from touching login items that
// belong to other apps. Returns the resolved path, or null if it does not fit.
const LAUNCH_AGENT_BASENAME = /^local\.perci\.[a-z0-9-]+\.plist$/;

function resolveLaunchAgentPath(candidate) {
  if (!candidate || typeof candidate !== 'string') return null;
  const root = path.join(require('os').homedir(), 'Library', 'LaunchAgents');
  const resolved = path.resolve(candidate);
  const relative = path.relative(root, resolved);
  if (!relative || relative.startsWith('..') || relative.includes(path.sep)) return null;
  if (!LAUNCH_AGENT_BASENAME.test(path.basename(resolved))) return null;
  return resolved;
}

ipcMain.handle('localhost:enable-autostart', async (event, { label, plistContent, plistPath, command, cwd } = {}) => {
  try {
    if (process.platform === 'darwin') {
      const target = resolveLaunchAgentPath(plistPath);
      if (!target) return { ok: false, error: 'Autostart path must be a .plist directly inside ~/Library/LaunchAgents.' };
      await fs.writeFile(target, plistContent, 'utf-8');
      const { execFileSync } = require('child_process');
      execFileSync('launchctl', ['load', '-w', target], { stdio: 'pipe', timeout: 10000 });
    } else if (process.platform === 'win32') {
      // Windows: write to HKCU Run registry key for autostart
      const { execSync } = require('child_process');
      const safeLabel = (label || 'perci_app').replace(/[^a-zA-Z0-9_]/g, '_');
      const exePath = process.execPath;
      const regCmd = `reg add "HKCU\\\\Software\\\\Microsoft\\\\Windows\\\\CurrentVersion\\\\Run" /v "${safeLabel}" /t REG_SZ /d "\\\\"${exePath}\\\\"" /f`;
      execSync(regCmd, { stdio: 'pipe', timeout: 10000 });
    } else if (process.platform === 'linux') {
      // Linux: create a .desktop file in ~/.config/autostart/
      const { execSync } = require('child_process');
      const safeLabel = (label || 'perci_app').replace(/[^a-zA-Z0-9_-]/g, '_');
      const autostartDir = path.join(require('os').homedir(), '.config', 'autostart');
      const desktopPath = path.join(autostartDir, `${safeLabel}.desktop`);
      const desktopContent = [
        '[Desktop Entry]',
        'Type=Application',
        `Name=${label || 'Perci'}`,
        `Exec=${process.execPath}`,
        'X-GNOME-Autostart-enabled=true',
        'Terminal=false',
        'NoDisplay=true',
      ].join('\\n');
      await fs.mkdir(autostartDir, { recursive: true });
      await fs.writeFile(desktopPath, desktopContent, 'utf-8');
    }
    return { ok: true };
  } catch (err) {
    return { ok: false, error: err.stderr?.toString() || err.message };
  }
});

ipcMain.handle('localhost:disable-autostart', async (event, { plistPath, label } = {}) => {
  try {
    if (process.platform === 'darwin') {
      const target = resolveLaunchAgentPath(plistPath);
      if (!target) return { ok: false, error: 'Autostart path must be a .plist directly inside ~/Library/LaunchAgents.' };
      const { execFileSync } = require('child_process');
      execFileSync('launchctl', ['unload', '-w', target], { stdio: 'pipe', timeout: 10000 });
      try { await fs.unlink(target); } catch (_) { /* already gone */ }
    } else if (process.platform === 'win32') {
      // Windows: remove from HKCU Run registry key
      const { execSync } = require('child_process');
      const safeLabel = (label || 'perci_app').replace(/[^a-zA-Z0-9_]/g, '_');
      execSync(`reg delete "HKCU\\\\Software\\\\Microsoft\\\\Windows\\\\CurrentVersion\\\\Run" /v "${safeLabel}" /f`, { stdio: 'pipe', timeout: 10000 });
    } else if (process.platform === 'linux') {
      // Linux: remove the .desktop file from ~/.config/autostart/
      const safeLabel = (label || 'perci_app').replace(/[^a-zA-Z0-9_-]/g, '_');
      const desktopPath = path.join(require('os').homedir(), '.config', 'autostart', `${safeLabel}.desktop`);
      try { await fs.unlink(desktopPath); } catch (_) { /* already gone */ }
    }
    return { ok: true };
  } catch (err) {
    return { ok: false, error: err.stderr?.toString() || err.message };
  }
});

