// Follows the MARKITDOWN_UI_WEBUI_DIR convention: env override, else a sibling
// checkout in the home directory. PERCI_OPENCODE_BIN overrides only the binary,
// so the source dir needs its own knob — otherwise a fork checked out elsewhere
// resolves the right binary but silently loses staleness detection and rebuild.
const OPENCODE_RIG_DIR = process.env.PERCI_OPENCODE_DIR
  || path.join(require('os').homedir(), 'opencode');
// The binary embeds a build of these trees, so anything newer than the binary
// means the window would serve an interface that no longer matches the source.
const OPENCODE_RIG_UI_SOURCES = ['packages/app/src', 'packages/ui/src'];
const OPENCODE_SCAN_SKIP = new Set(['node_modules', 'dist', '.git', '.turbo']);
let opencodeRebuildProcess = null;

function newestSourceMtime(root) {
  let newest = 0;
  const walk = (dir) => {
    let entries;
    try {
      entries = fsSync.readdirSync(dir, { withFileTypes: true });
    } catch (_) {
      return;
    }
    for (const entry of entries) {
      if (OPENCODE_SCAN_SKIP.has(entry.name)) continue;
      const full = path.join(dir, entry.name);
      if (entry.isDirectory()) {
        walk(full);
        continue;
      }
      try {
        const { mtimeMs } = fsSync.statSync(full);
        if (mtimeMs > newest) newest = mtimeMs;
      } catch (_) {
        // A file that vanished mid-scan (editor swap file) tells us nothing.
      }
    }
  };
  walk(root);
  return newest;
}

// The OpenCode Rig fork's own build, which embeds its web UI in the binary.
// This matters for more than branding: a build without the embedded UI proxies
// every UI request to https://app.opencode.ai (see the fork's
// packages/opencode/src/server/shared/ui.ts), so the stock CLI would serve
// upstream OpenCode rather than the Rig interface. Override with
// PERCI_OPENCODE_BIN; otherwise fall back to whatever `opencode` is on PATH.
function opencodeRigBinary() {
  const override = process.env.PERCI_OPENCODE_BIN;
  if (override) return fsSync.existsSync(override) ? override : null;

  const target = `opencode-${process.platform === 'win32' ? 'windows' : process.platform}-${process.arch}`;
  const built = path.join(
    OPENCODE_RIG_DIR, 'packages', 'opencode', 'dist', target, 'bin',
    process.platform === 'win32' ? 'opencode.exe' : 'opencode'
  );
  return fsSync.existsSync(built) ? built : null;
}

// Falls back to a login shell so it picks up nvm/homebrew paths the packaged
// app doesn't inherit.
function resolveOpencodeBinary() {
  const rig = opencodeRigBinary();
  if (rig) return rig;

  const { execFileSync } = require('child_process');
  const executable = process.platform === 'win32' ? 'cmd.exe' : '/bin/sh';
  const args = process.platform === 'win32' ? ['/c', 'where opencode'] : ['-lc', 'command -v opencode'];
  try {
    const cmdPath = execFileSync(executable, args, { encoding: 'utf8' }).trim().split('\n')[0].trim();
    return cmdPath || null;
  } catch (_) {
    return null;
  }
}

// Asset names published by the Rig's release workflow. No Windows CLI is built,
// so that case gets told the truth rather than a download that doesn't exist.
const OPENCODE_RIG_RELEASES = 'https://github.com/toshon-jennings/opencode-rig/releases/latest';
function opencodeRigAsset() {
  const arch = process.arch === 'arm64' ? 'arm64' : 'x64';
  if (process.platform === 'darwin') return `opencode-darwin-${arch}.zip`;
  if (process.platform === 'linux') return `opencode-linux-${arch}.tar.gz`;
  return null;
}

ipcMain.handle('opencode:install-info', async () => ({
  asset: opencodeRigAsset(),
  releasesUrl: OPENCODE_RIG_RELEASES,
  rigDir: OPENCODE_RIG_DIR,
  platform: process.platform,
}));

ipcMain.handle('opencode:check-install', async () => {
  const { execFileSync } = require('child_process');
  const cmdPath = resolveOpencodeBinary();
  if (!cmdPath) return { installed: false };
  let version;
  try {
    version = execFileSync(cmdPath, ['--version'], { encoding: 'utf8' }).trim();
  } catch (_) {
    // Version is cosmetic — an old build without --version still counts as installed.
  }
  // isRig distinguishes the fork build (embedded Rig UI) from a stock CLI that
  // would proxy upstream OpenCode's interface instead.
  return { installed: true, path: cmdPath, version, isRig: cmdPath === opencodeRigBinary() };
});

// The embedded UI is baked in at compile time, so edits to the fork's UI sources
// don't reach the window until the binary is rebuilt.
ipcMain.handle('opencode:build-info', async () => {
  const binary = opencodeRigBinary();
  const hasSource = fsSync.existsSync(path.join(OPENCODE_RIG_DIR, 'packages', 'opencode', 'script', 'build.ts'));
  if (!binary) return { isRig: false, stale: false, canRebuild: hasSource };

  let builtAt = 0;
  try {
    builtAt = fsSync.statSync(binary).mtimeMs;
  } catch (_) {
    return { isRig: true, binaryPath: binary, stale: false, canRebuild: hasSource };
  }

  let newestSourceAt = 0;
  for (const rel of OPENCODE_RIG_UI_SOURCES) {
    const found = newestSourceMtime(path.join(OPENCODE_RIG_DIR, rel));
    if (found > newestSourceAt) newestSourceAt = found;
  }

  return {
    isRig: true,
    binaryPath: binary,
    builtAt,
    newestSourceAt,
    stale: newestSourceAt > 0 && newestSourceAt > builtAt,
    canRebuild: hasSource,
    building: Boolean(opencodeRebuildProcess),
  };
});

ipcMain.handle('opencode:rebuild', async (event) => {
  if (opencodeRebuildProcess) return { ok: false, error: 'A rebuild is already running.' };
  const cwd = path.join(OPENCODE_RIG_DIR, 'packages', 'opencode');
  if (!fsSync.existsSync(path.join(cwd, 'script', 'build.ts'))) {
    return { ok: false, error: `OpenCode Rig source not found at ${OPENCODE_RIG_DIR}.` };
  }

  const command = 'bun run script/build.ts --single --skip-install';
  const executable = process.platform === 'win32' ? 'cmd.exe' : '/bin/sh';
  // Login shell so bun resolves the same way it does in a terminal.
  const args = process.platform === 'win32' ? ['/c', command] : ['-lc', command];

  return new Promise((resolve) => {
    // Deliberately no OPENCODE_CHANNEL here. The fork derives it from the
    // current git branch, so a `dev` checkout builds the preview channel: the
    // app shows a DEV badge and stamps 0.0.0-dev-<timestamp>. Forcing `latest`
    // removes the badge but also compiles out everything gated on
    // `channel !== "prod"` — most importantly the worktree/branch picker on the
    // New Session screen. The badge is cosmetic; the picker is not. Keep the
    // branch-derived channel.
    const child = spawn(executable, args, { cwd, stdio: ['ignore', 'pipe', 'pipe'] });
    opencodeRebuildProcess = child;

    const tail = [];
    let lastLine = '';
    const onChunk = (buf) => {
      const text = buf.toString();
      tail.push(text);
      if (tail.length > 60) tail.shift();
      const line = text.split('\n').map((s) => s.trim()).filter(Boolean).pop();
      if (!line) return;
      lastLine = line;
      if (!event.sender.isDestroyed()) event.sender.send('opencode:rebuild-progress', line);
    };
    child.stdout.on('data', onChunk);
    child.stderr.on('data', onChunk);

    child.on('error', (err) => {
      opencodeRebuildProcess = null;
      resolve({ ok: false, error: err.message });
    });

    child.on('exit', (code) => {
      opencodeRebuildProcess = null;
      if (code !== 0) {
        // Carry the last build output into the message — "exit 1" alone leaves
        // the user with nothing to act on, and the cause is usually right here
        // (a missing dependency, a broken symlink, a type error).
        resolve({
          ok: false,
          error: lastLine ? `Build failed (exit ${code}): ${lastLine}` : `Build failed (exit ${code}).`,
          log: tail.join('').slice(-2000),
        });
        return;
      }
      // The live server is still the old binary. Stop ours so the next start
      // picks up the rebuild — never a server Perci didn't spawn.
      if (opencodeServerProcess) {
        try {
          opencodeServerProcess.kill('SIGTERM');
        } catch (_) {
          // Already gone — the restart below is what matters.
        }
        opencodeServerProcess = null;
      }
      resolve({ ok: true });
    });
  });
});

// The fork brands its own favicons with a cache-busting stamp (see the Rig's
// "brand the favicon for this fork" commit), which upstream's UI does not carry.
// Matched without the trailing counter so a re-bust doesn't break detection.
const OPENCODE_RIG_UI_MARKER = '?v=workbench';

function fetchOpencodeRoot() {
  return new Promise((resolve) => {
    const req = http.get(
      {
        host: '127.0.0.1',
        port: OPENCODE_PORT,
        path: '/',
        headers: { Authorization: opencodeAuthHeader() },
        timeout: 4000,
      },
      (res) => {
        let body = '';
        res.setEncoding('utf8');
        res.on('data', (chunk) => {
          // The shell document is a couple of KB; never buffer a stream.
          if (body.length < 64 * 1024) body += chunk;
        });
        res.on('end', () => resolve({ status: res.statusCode, body }));
      }
    );
    req.on('timeout', () => req.destroy(new Error('timeout')));
    req.on('error', () => resolve({ status: null, body: '' }));
  });
}

// Distinguishes what is actually being served, not merely which file was
// launched. A build without an embedded UI proxies upstream's interface from
// app.opencode.ai, so a path check alone would happily front stock OpenCode.
ipcMain.handle('opencode:probe', async () => {
  const result = await probeLocalHttp(OPENCODE_URL, 2000, { Authorization: opencodeAuthHeader() });
  if (!result.reachable) return { state: 'offline' };
  if (result.status === 401) return { state: 'foreign' };

  const page = await fetchOpencodeRoot();
  if (!page.body) return { state: 'ready' }; // reachable but unreadable — don't block on a flake
  return page.body.includes(OPENCODE_RIG_UI_MARKER)
    ? { state: 'ready' }
    : { state: 'stock' };
});

ipcMain.handle('opencode:start', async () => {
  if (opencodeServerProcess) return { ok: true };

  const probe = await probeLocalHttp(OPENCODE_URL, 2000, { Authorization: opencodeAuthHeader() });
  if (probe.reachable) {
    // Something already owns the port. Never start over it, never kill it.
    return probe.status === 401
      ? { ok: false, error: `A server Perci didn't start is already running on port ${OPENCODE_PORT}.` }
      : { ok: true };
  }

  const binary = resolveOpencodeBinary();
  if (!binary) return { ok: false, error: 'The opencode CLI is not installed.' };

  const child = spawn(binary, ['serve', '--port', String(OPENCODE_PORT)], {
    cwd: app.getPath('home'),
    env: {
      ...process.env,
      OPENCODE_SERVER_USERNAME: OPENCODE_USERNAME,
      OPENCODE_SERVER_PASSWORD: opencodeServerPassword,
    },
    // Nothing reads these pipes, and an unread pipe stalls the child once its
    // buffer fills — the server logs per request, so it would eventually hang.
    stdio: 'ignore',
  });
  opencodeServerProcess = child;

  child.on('error', (err) => {
    console.error('[opencode] server process error:', err);
    if (opencodeServerProcess === child) opencodeServerProcess = null;
  });
  child.on('exit', (code) => {
    console.log(`[opencode] server exited with code ${code}`);
    if (opencodeServerProcess === child) opencodeServerProcess = null;
  });

  return { ok: true };
});

ipcMain.handle('localhost:stop-now', async (event, { port, id } = {}) => {
  if (id === 'eidos') {
    if (eidosDashboardProcess) {
      try { eidosDashboardProcess.kill('SIGTERM'); } catch (_) {}
      eidosDashboardProcess = null;
    }
    const dockerPath = eidosDockerPath();
    if (dockerPath) {
      try { await eidosStopCompose(dockerPath); } catch (_) {}
    }
  }

  const portNum = Number(port);
  if (!portNum || isNaN(portNum) || portNum <= 0 || portNum > 65535) {
    return { ok: true };
  }

  try {
    const { listeners } = scanSockets();
    const matchingPids = [...new Set(listeners.filter(l => l.port === portNum && l.pid && l.pid !== process.pid).map(l => l.pid))];

    if (matchingPids.length === 0 && process.platform !== 'win32') {
      const out = execCmd(`lsof -t -iTCP:${portNum} -sTCP:LISTEN`);
      const pids = out.split('\n').map(s => parseInt(s.trim(), 10)).filter(p => !isNaN(p) && p > 0 && p !== process.pid);
      matchingPids.push(...pids);
    }

    const killed = [];
    for (const pid of new Set(matchingPids)) {
      try {
        process.kill(pid, 'SIGTERM');
        killed.push(pid);
      } catch (_) {
        try {
          process.kill(pid, 'SIGKILL');
          killed.push(pid);
        } catch (_) {}
      }
    }
    return { ok: true, killedPids: killed };
  } catch (err) {
    return { ok: false, error: err.message };
  }
});

