ipcMain.handle('rename-file', async (event, { old, next } = {}) => {
  assertTrustedMainFrame(event);
  const oldPath = await workspaceGrants.authorize({
    grantId: old?.grantId,
    ownerId: event.sender.id,
    capability: 'rename',
    targetPath: old?.targetPath,
  });
  const newPath = await workspaceGrants.authorize({
    grantId: next?.grantId,
    ownerId: event.sender.id,
    capability: 'rename',
    targetPath: next?.targetPath,
    allowMissing: true,
  });
  try {
    await fs.rename(oldPath, newPath);
    return true;
  } catch (err) {
    console.error('Error renaming file:', err);
    throw err;
  }
});

// ── Lighthouse IPC handlers ──────────────────────────────────────────────

function execCmd(cmd, timeout = 10000) {
  try {
    if (process.platform === 'win32') {
      return spawnSync('cmd.exe', ['/c', cmd], {
        timeout,
        encoding: 'utf8',
        stdio: ['pipe', 'pipe', 'pipe'],
      }).stdout || '';
    }
    return spawnSync('/bin/sh', ['-c', cmd], {
      timeout,
      encoding: 'utf8',
      stdio: ['pipe', 'pipe', 'pipe'],
    }).stdout || '';
  } catch {
    return '';
  }
}

// Parse one IPv4/IPv6 host:port token from lsof's `n` field.
function parseHostPort(n) {
  let host, portStr;
  if (n[0] === '[') { const i = n.indexOf(']'); host = n.slice(1, i); portStr = n.slice(i + 2); }
  else { const cp = n.lastIndexOf(':'); host = n.slice(0, cp); portStr = n.slice(cp + 1); }
  return { host, port: parseInt(portStr, 10) };
}

function normalizeBind(host, family) {
  if (host === '*' || host === '') return family === 'IPv6' ? '::' : '0.0.0.0';
  return host;
}

// Windows: parse netstat -ano output into the same shape as lsof parser.
function scanSocketsWin32() {
  const output = execCmd('netstat -ano | findstr LISTENING', 15000);
  const all = [];
  const lineRe = /^\s*(TCP|UDP)\s+(\S+):(\d+)\s+\S+\s+LISTENING\s+(\d+)/;
  for (const line of output.split('\n')) {
    const m = lineRe.exec(line);
    if (!m) continue;
    const proto = m[1], bindAddr = m[2], port = parseInt(m[3], 10), pid = parseInt(m[4], 10);
    if (isNaN(port) || port <= 0 || port > 65535) continue;
    // Resolve process name from PID (best-effort)
    let processName = '';
    try {
      const tasklist = require('child_process').execSync(`tasklist /FI "PID eq ${pid}" /FO CSV /NH`, { encoding: 'utf8', timeout: 5000, stdio: ['ignore', 'pipe', 'ignore'] });
      const nameMatch = /^"([^"]+)"/.exec(tasklist);
      if (nameMatch) processName = nameMatch[1].replace(/\.exe$/i, '');
    } catch { /* pid may have exited */ }
    all.push({
      pid: pid || null, process_name: processName,
      protocol: proto, family: bindAddr.includes(':') ? 'IPv6' : 'IPv4',
      bind_address: bindAddr, port,
      state: 'LISTEN', conn: false,
    });
  }
  const listeners = all; // netstat already filters to LISTENING
  const seen = new Set();
  const deduped = listeners.filter(s => {
    const k = `${s.port}-${s.protocol}-${s.bind_address}-${s.pid}`;
    if (seen.has(k)) return false; seen.add(k); return true;
  });
  deduped.sort((a, b) => a.port - b.port || String(a.bind_address).localeCompare(String(b.bind_address)));
  return { listeners: deduped, all };
}

// Scan listening sockets (lsof on macOS/Linux, netstat on Windows).
// Returns { listeners, all }.
function scanSockets() {
  if (process.platform === 'win32') return scanSocketsWin32();
  const output = execCmd('lsof -nP -iTCP -iUDP -F pcftPnT');
  const all = [];
  let pid = null, cmd = '';
  let fam = null, proto = null, name = null, state = null;
  const flushFile = () => {
    if (name != null) {
      const isConn = name.indexOf('->') >= 0;
      const local = isConn ? name.split('->')[0] : name;
      const { host, port } = parseHostPort(local);
      if (!isNaN(port) && port > 0 && port <= 65535) {
        all.push({
          pid, process_name: cmd,
          protocol: proto || 'TCP', family: fam || 'IPv4',
          bind_address: normalizeBind(host, fam), port,
          state: state || (proto === 'UDP' ? 'UDP' : null),
          conn: isConn,
        });
      }
    }
    fam = proto = name = state = null;
  };
  for (const line of output.split('\n')) {
    if (!line) continue;
    const tag = line[0], val = line.slice(1);
    if (tag === 'p') { flushFile(); pid = parseInt(val, 10) || null; cmd = ''; }
    else if (tag === 'c') { cmd = val; }
    else if (tag === 'f') { flushFile(); }
    else if (tag === 't') { fam = val; }
    else if (tag === 'P') { proto = val; }
    else if (tag === 'n') { name = val; }
    else if (tag === 'T') { if (val.startsWith('ST=')) state = val.slice(3); }
  }
  flushFile();
  const listeners = all.filter(s => !s.conn && (s.protocol === 'UDP' || s.state === 'LISTEN'));
  const seen = new Set();
  const deduped = listeners.filter(s => {
    const k = `${s.port}-${s.protocol}-${s.bind_address}-${s.pid}`;
    if (seen.has(k)) return false; seen.add(k); return true;
  });
  deduped.sort((a, b) => a.port - b.port || String(a.bind_address).localeCompare(String(b.bind_address)));
  return { listeners: deduped, all };
}

function suggestFree(start, end, liveUsed, declaredUsed) {
  for (let c = start; c <= end; c++) if (!liveUsed.has(c) && !declaredUsed.has(c)) return c;
  for (let c = start; c <= end; c++) if (!liveUsed.has(c)) return c;
  return null;
}

const PROCESS_NAME_MAP = {
  'com.docke': 'Docker Desktop', 'Docker': 'Docker Desktop', 'docker': 'Docker',
  'ControlCe': 'AirPlay Receiver', 'rapportd': 'AirPlay / Handoff', 'LM Studio': 'LM Studio',
  'node': 'Node.js', 'node.exe': 'Node.js', 'next-server': 'Next.js', 'next-dev': 'Next.js (dev)',
  'vite': 'Vite', 'python3': 'Python', 'python': 'Python', 'ollama': 'Ollama', 'Ollama': 'Ollama',
  'keybase': 'Keybase', 'kbfs': 'Keybase FS', 'Raycast': 'Raycast', 'Electron': 'Perci',
  'Antigravi': 'Antigravity', 'app_inkwe': 'Inkweasel', 'language_': 'Language Server',
  'lmlink-co': 'LM Link', 'sshd': 'SSH', 'postgres': 'PostgreSQL', 'redis-server': 'Redis', 'nginx': 'nginx',
};

function friendlyProcessName(raw) {
  if (!raw) return '—';
  if (PROCESS_NAME_MAP[raw]) return PROCESS_NAME_MAP[raw];
  const base = raw.replace(/\d+(\.\d+)*$/, '').toLowerCase();
  if (base === 'python') return 'Python';
  if (base === 'node') return 'Node.js';
  if (raw.length > 9 && PROCESS_NAME_MAP[raw.slice(0, 9)]) return PROCESS_NAME_MAP[raw.slice(0, 9)];
  return raw.replace(/_/g, ' ').replace(/\b\w/g, c => c.toUpperCase());
}

// Reconcile live listeners against PORTMASTER declarations.
function detectConflicts(listeners, entries) {
  const conflicts = [];
  const liveUsed = new Set(listeners.map(l => l.port));
  const declaredUsed = new Set(entries.map(e => e.port));
  const norm = (s) => String(s || '').toLowerCase().replace(/[^a-z0-9]/g, '');
  const STOP = new Set(['app', 'com', 'the', 'backend', 'desktop', 'server', 'agent', 'service', 'daemon', 'run', 'serve', 'dev', 'api', 'node', 'python', 'main']);
  const tokens = (s) => String(s || '').toLowerCase().split(/[^a-z0-9]+/).filter(t => t.length >= 3 && !STOP.has(t));
  const related = (a, b) => {
    const na = norm(a), nb = norm(b);
    if (na && nb && (na.includes(nb) || nb.includes(na))) return true;
    const tb = new Set(tokens(b));
    return tokens(a).some(t => tb.has(t));
  };

  const byPort = {};
  for (const e of entries) (byPort[e.port] = byPort[e.port] || []).push(e);
  for (const portKey of Object.keys(byPort)) {
    const group = byPort[portKey];
    const owners = [...new Set(group.map(e => norm(e.managed_by) || norm(e.service)).filter(Boolean))];
    if (owners.length > 1) {
      const a = group[0];
      const b = group.find(e => (norm(e.managed_by) || norm(e.service)) !== (norm(a.managed_by) || norm(a.service))) || group[1];
      const liveDup = listeners.find(l => l.port === Number(portKey) && l.pid);
      conflicts.push({
        port: Number(portKey), kind: 'duplicate_declaration',
        process_a: a.managed_by || a.service, pid_a: null,
        process_b: b.managed_by || b.service, pid_b: null,
        suggestion: suggestFree(3000, 3999, liveUsed, declaredUsed),
        explanation: `Port ${portKey} is declared to two different owners ("${a.managed_by || a.service}" and "${b.managed_by || b.service}") across PORTMASTER.md files${liveDup ? `, and is currently held by "${friendlyProcessName(liveDup.process_name)}" (PID ${liveDup.pid})` : ''}.`,
      });
    }
  }
  for (const l of listeners) {
    const decl = entries.find(e => e.port === l.port);
    if (!decl) continue;
    const declaredOwner = decl.managed_by || decl.service;
    if (declaredOwner && !related(declaredOwner, l.process_name) && !related(declaredOwner, friendlyProcessName(l.process_name))) {
      conflicts.push({
        port: l.port, kind: 'owner_mismatch',
        process_a: l.process_name, pid_a: l.pid,
        process_b: declaredOwner, pid_b: null,
        suggestion: suggestFree(3000, 3999, liveUsed, declaredUsed),
        explanation: `Port ${l.port} is declared for "${declaredOwner}" but is actually held by "${friendlyProcessName(l.process_name)}" (PID ${l.pid}).`,
      });
    }
  }
  // Attach every distinct live process bound to each conflicting port, so the
  // resolve UI can let the user choose which to kill (not a pre-picked one).
  const procsByPort = {};
  for (const l of listeners) {
    if (!l.pid) continue;
    const arr = (procsByPort[l.port] = procsByPort[l.port] || []);
    if (!arr.some(p => p.pid === l.pid)) arr.push({ pid: l.pid, name: l.process_name, port: l.port });
  }
  const allLiveProcs = [];
  for (const l of listeners) {
    if (!l.pid) continue;
    if (!allLiveProcs.some(p => p.pid === l.pid)) allLiveProcs.push({ pid: l.pid, name: l.process_name, port: l.port });
  }
  for (const c of conflicts) {
    const procs = [...(procsByPort[c.port] || [])];
    // Find process_a and process_b (conflicting parties) anywhere in the listener list by name.
    const addSecondary = (ownerName) => {
      if (!ownerName) return;
      for (const lp of allLiveProcs) {
        if (!procs.some(p => p.pid === lp.pid) && related(ownerName, lp.name)) {
          procs.push({ pid: lp.pid, name: lp.name, port: lp.port, secondary: true });
        }
      }
    };
    addSecondary(c.process_a);
    addSecondary(c.process_b);
    c.processes = procs;
  }

  const seen = new Set();
  return conflicts.filter(c => { const k = `${c.port}-${c.kind}`; if (seen.has(k)) return false; seen.add(k); return true; });
}

// Find config-file references to a port across the user's repos (read-only).
function findPortReferences(oldPort, newPort) {
  const home = app.getPath('home');
  const refs = [];
  const NAME_RE = /(^package\.json$|^\.env|^vite\.config\.|\.config\.(js|ts|cjs|mjs)$|^docker-compose.*\.ya?ml$|\.toml$|^PORTMASTER\.md$)/;
  const detectRe = new RegExp(`(?<![0-9])${oldPort}(?![0-9])`);
  const replaceRe = new RegExp(`(?<![0-9])${oldPort}(?![0-9])`, 'g'); // all occurrences on the line
  // Deployment-platform markers — NOT limited to Vercel/Supabase. Memoized per dir.
  const PLATFORM_MARKERS = {
    '.vercel/project.json': 'Vercel', 'vercel.json': 'Vercel',
    'netlify.toml': 'Netlify', '.netlify/state.json': 'Netlify',
    'fly.toml': 'Fly.io', 'railway.json': 'Railway', 'railway.toml': 'Railway',
    'render.yaml': 'Render', 'render.yml': 'Render',
    'wrangler.toml': 'Cloudflare', 'firebase.json': 'Firebase',
    'Procfile': 'Heroku', 'app.json': 'Heroku', 'app.yaml': 'App Engine',
    'serverless.yml': 'Serverless', 'serverless.yaml': 'Serverless',
    'supabase/config.toml': 'Supabase', 'amplify': 'Amplify',
  };
  const platformCache = {};
  const projectPlatforms = (fileDir) => {
    if (platformCache[fileDir] !== undefined) return platformCache[fileDir];
    const found = new Set();
    let dir = fileDir;
    for (let i = 0; i < 6 && dir && dir !== '/'; i++) {
      for (const marker in PLATFORM_MARKERS) {
        if (fsSync.existsSync(path.join(dir, marker))) found.add(PLATFORM_MARKERS[marker]);
      }
      if (dir === home) break;
      dir = path.dirname(dir);
    }
    return (platformCache[fileDir] = [...found]);
  };
  const REMOTE_VALUE_RE = /https?:\/\/(?!localhost|127\.0\.0\.1|0\.0\.0\.0)|[a-z0-9-]+\.[a-z]{2,}(:\d+)?\/|(_URL|_URI|_KEY|_TOKEN|_SECRET|_DSN|PASSWORD|CONNECTION_?STRING)\s*[=:]/i;
  const scanFile = (full) => {
    try {
      const envFile = /^\.env/.test(path.basename(full));
      const platforms = projectPlatforms(path.dirname(full));
      const lines = fsSync.readFileSync(full, 'utf8').split('\n');
      for (let i = 0; i < lines.length; i++) {
        if (!detectRe.test(lines[i])) continue;
        let risk = 'low', reason = '';
        if (envFile) {
          risk = 'high';
          reason = platforms.length
            ? `Env file in a ${platforms.join('/')}-linked project — the remote may hold this value too`
            : 'Env file — values here are commonly synced to a deployment platform';
        } else if (REMOTE_VALUE_RE.test(lines[i])) {
          risk = 'high'; reason = 'Line carries a remote URL / credential — may be synced externally';
        } else if (platforms.length) {
          risk = 'medium'; reason = `In a ${platforms.join('/')}-linked project`;
        }
        refs.push({
          file_path: full, line_number: i + 1,
          old_line: lines[i], new_line: lines[i].replace(replaceRe, String(newPort)),
          old_port: oldPort, new_port: newPort,
          env_file: envFile, platforms, risk, reason,
        });
      }
    } catch { /* skip */ }
  };
  const SKIP = new Set(['node_modules', '.git', 'dist', 'build', 'release', '.next', '.cache',
    'Library', 'Applications', 'Downloads', 'Music', 'Movies', 'Pictures', 'Public']);
  const walk = (dir, depth) => {
    if (depth <= 0 || !fsSync.existsSync(dir)) return;
    let items; try { items = fsSync.readdirSync(dir, { withFileTypes: true }); } catch { return; }
    for (const it of items) {
      if (it.isDirectory()) { if (!SKIP.has(it.name) && !it.name.startsWith('.')) walk(path.join(dir, it.name), depth - 1); }
      else if (NAME_RE.test(it.name)) scanFile(path.join(dir, it.name));
    }
  };
  scanFile(path.join(home, '.config/agent-rules/PORTMASTER.md'));
  walk(home, 4);
  const seen = new Set();
  const rank = { high: 0, medium: 1, low: 2 };
  return refs
    .filter(r => { const k = `${r.file_path}:${r.line_number}`; if (seen.has(k)) return false; seen.add(k); return true; })
    .sort((a, b) => (rank[a.risk] - rank[b.risk]) || a.file_path.localeCompare(b.file_path))
    .slice(0, 50);
}

function loadPortmasters() {
  const os = require('os');
  const home = app.getPath('home');
  const files = [];
  const check = (p) => {
    try {
      if (fsSync.existsSync(p)) files.push(p);
    } catch { /* skip */ }
  };
  check(path.join(home, '.config', 'agent-rules', 'PORTMASTER.md'));
  const walk = (dir, maxDepth) => {
    if (maxDepth <= 0) return;
    let entries = [];
    try {
      entries = fsSync.readdirSync(dir, { withFileTypes: true });
    } catch { return; }
    for (const entry of entries) {
      const full = path.join(dir, entry.name);
      if (entry.isDirectory()) walk(full, maxDepth - 1);
      else if (entry.name === 'PORTMASTER.md') files.push(full);
    }
  };
  for (const d of ['projects', 'code', 'dev', 'workspace', 'src']) {
    walk(path.join(home, d), 4);
  }
  const entries = [];
  for (const f of [...new Set(files)]) {
    try {
      const content = fsSync.readFileSync(f, 'utf8');
      const tableRe = /\|\s*(\d+)\s*\|\s*([^|]+?)\s*\|\s*([^|]+?)\s*\|\s*([^|]+?)\s*\|\s*([^|]+?)\s*\|\s*([^|]+?)\s*\|/;
      for (const line of content.split('\n')) {
        const m = tableRe.exec(line);
        if (m) {
          entries.push({
            port: parseInt(m[1], 10),
            service: m[2].trim(),
            protocol: m[3].trim(),
            bind: m[4].trim(),
            managed_by: m[5].trim(),
            notes: m[6].trim(),
            source_file: f,
          });
        }
      }
    } catch { /* skip */ }
  }
  return { files: [...new Set(files)], entries };
}

function runLighthouseScan() {
  const { listeners } = scanSockets();
  const { files, entries } = loadPortmasters();
  const declared = new Set(entries.map(e => e.port));
  for (const p of listeners) {
    const pm = entries.find(e => e.port === p.port);
    if (pm) {
      p.service_name = pm.service;
      p.managed_by = pm.managed_by;
    }
    p.exposed = (p.bind_address === '0.0.0.0' || p.bind_address === '::');
    p.undeclared = !declared.has(p.port);
    p.source = 'Live';
  }
  const conflicts = detectConflicts(listeners, entries);
  const now = new Date();
  const last_scan = `${String(now.getHours()).padStart(2, '0')}:${String(now.getMinutes()).padStart(2, '0')}:${String(now.getSeconds()).padStart(2, '0')}`;
  return { ports: listeners, conflicts, portmaster_files: files, portmaster_entries: entries, last_scan, status: conflicts.length > 0 ? 'warning' : 'ok' };
}

// Render a compact, token-cheap snapshot of live ports for coding agents to
// read instead of running `lsof` themselves.
function renderPortsMarkdown(result) {
  const ports = result.ports || [];
  const conflicts = result.conflicts || [];
  const lines = [];
  lines.push('# Active Ports (generated)');
  lines.push('');
  lines.push(`_Auto-generated by Perci Lighthouse at ${new Date().toISOString()}. Do not edit — overwritten on each scan._`);
  lines.push('');
  lines.push('Live snapshot of listening ports on this machine. Read this instead of running');
  lines.push('`lsof`/`netstat` to learn what is already bound. JSON sibling: `active-ports.json`.');
  lines.push('');
  if (conflicts.length) {
    lines.push(`## ⚠ Conflicts (${conflicts.length})`);
    lines.push('');
    for (const c of conflicts) {
      lines.push(`- Port ${c.port}: ${friendlyProcessName(c.process_a)} vs ${friendlyProcessName(c.process_b)}${c.suggestion ? ` → suggested free port ${c.suggestion}` : ''}`);
    }
    lines.push('');
  }
  lines.push('## Listening ports');
  lines.push('');
  if (!ports.length) {
    lines.push('_No listening ports detected._');
  } else {
    lines.push('| Port | Bind | Service | Process | PID | Managed by |');
    lines.push('| ---- | ---- | ------- | ------- | --- | ---------- |');
    const sorted = [...ports].sort((a, b) => Number(a.port || 0) - Number(b.port || 0));
    for (const p of sorted) {
      const svc = p.service_name || p.project || (p.undeclared ? 'undeclared' : '—');
      lines.push(`| ${p.port} | ${p.bind_address || '—'} | ${svc} | ${friendlyProcessName(p.process_name)} | ${p.pid || '—'} | ${p.managed_by || '—'} |`);
    }
  }
  lines.push('');
  return lines.join('\n');
}

// Persist the scan to ~/.config/agent-rules/ (markdown + JSON) so agents on the
// Cowork/Code/Agents surfaces can read ports cheaply. Guarded — never throws.
function writePortsSnapshot(result) {
  try {
    const r = result || runLighthouseScan();
    const dir = path.join(app.getPath('home'), '.config', 'agent-rules');
    fsSync.mkdirSync(dir, { recursive: true });
    fsSync.writeFileSync(path.join(dir, 'ACTIVE_PORTS.md'), renderPortsMarkdown(r));
    fsSync.writeFileSync(path.join(dir, 'active-ports.json'), JSON.stringify({
      generated_at: new Date().toISOString(),
      generator: 'perci-lighthouse',
      last_scan: r.last_scan,
      status: r.status,
      ports: r.ports,
      conflicts: r.conflicts,
    }, null, 2));
  } catch (err) {
    console.error('Failed to write active-ports snapshot:', err);
  }
}

ipcMain.handle('lighthouse:scan', async () => {
  const result = runLighthouseScan();
  writePortsSnapshot(result);
  return result;
});

ipcMain.handle('lighthouse:check-port', async (event, { port } = {}) => {
  const { listeners, all } = scanSockets();
  const entry = listeners.find(p => p.port === port);
  const liveUsed = new Set(listeners.map(p => p.port));
  const declared = new Set(loadPortmasters().entries.map(e => e.port));
  const suggestion = entry ? suggestFree(port + 1, 65535, liveUsed, declared) : null;
  const transient = !entry ? all.find(s => s.port === port && s.protocol === 'TCP' && s.state && s.state !== 'LISTEN') : null;
  return {
    port, in_use: !!entry,
    process: entry ? entry.process_name : (transient ? transient.process_name : null),
    pid: entry ? entry.pid : (transient ? transient.pid : null),
    bind: entry ? entry.bind_address : null,
    protocol: entry ? entry.protocol : null,
    transient_state: transient ? transient.state : null,
    suggestion,
  };
});

ipcMain.handle('lighthouse:suggest-port', async (event, { rangeStart, rangeEnd } = {}) => {
  const { listeners } = scanSockets();
  const liveUsed = new Set(listeners.map(p => p.port));
  const declared = new Set(loadPortmasters().entries.map(e => e.port));
  return suggestFree(rangeStart || 3000, rangeEnd || 3999, liveUsed, declared) || (rangeStart || 3000);
});

ipcMain.handle('lighthouse:find-references', async (event, { oldPort, newPort } = {}) => {
  return findPortReferences(oldPort, newPort);
});

ipcMain.handle('lighthouse:apply-fix', async (event, { grantId, filePath, lineNumber, newLine, oldLine } = {}) => {
  assertTrustedMainFrame(event);
  let authorizedPath;
  try {
    authorizedPath = await workspaceGrants.authorize({
      grantId,
      ownerId: event.sender.id,
      capability: 'write',
      targetPath: filePath,
    });
  } catch (error) {
    return { ok: false, error: error.message };
  }
  try {
    const lines = fsSync.readFileSync(authorizedPath, 'utf8').split('\n');
    const idx = lineNumber - 1;
    if (idx < 0 || idx >= lines.length) return { ok: false, error: 'Line out of range' };
    if (oldLine != null && lines[idx] !== oldLine) return { ok: false, error: 'File changed since preview; skipped for safety' };
    lines[idx] = newLine;
    fsSync.writeFileSync(authorizedPath, lines.join('\n'));
    return { ok: true };
  } catch (e) {
    return { ok: false, error: e.message };
  }
});

ipcMain.handle('lighthouse:process-details', async (event, { pid } = {}) => {
  const safePid = Number.parseInt(pid, 10);
  if (!Number.isInteger(safePid) || safePid <= 0) {
    return { error: 'Invalid process id' };
  }

  const ppid = execCmd(`ps -o ppid= -p ${safePid}`).trim();
  const parent_pid = ppid ? parseInt(ppid, 10) : null;
  const parent_name = parent_pid ? execCmd(`ps -o comm= -p ${parent_pid}`).trim() : '';
  const parent_command = parent_pid ? execCmd(`ps -o command= -p ${parent_pid}`).trim() : '';
  let working_dir = '';
  for (const line of execCmd(`lsof -a -d cwd -p ${safePid} -Fn`).split('\n')) {
    if (line[0] === 'n') { working_dir = line.slice(1); break; }
  }
  return {
    pid: safePid,
    parent_pid,
    parent_name,
    parent_command,
    start_time: execCmd(`ps -o lstart= -p ${safePid}`).trim(),
    working_dir,
    command: execCmd(`ps -o command= -p ${safePid}`).trim(),
  };
});

ipcMain.handle('lighthouse:kill-process', async (event, { pid } = {}) => {
  assertTrustedMainFrame(event);
  if (!Number.isSafeInteger(pid) || pid <= 0 || pid === process.pid) {
    return { ok: false, error: 'Invalid process id' };
  }
  try {
    process.kill(pid, 'SIGKILL');
    return { ok: true, message: `Killed ${pid}` };
  } catch (e) {
    return { ok: false, error: e.message };
  }
});

// ── Eidos — persistent memory service ──────────────────────────────
// Manages the Docker/OrbStack lifecycle for the Eidos stack (memU,
// Postgres, Temporal, Ollama) and the Next.js dashboard dev server.

const EIDOS_DIR = path.join(app.getPath('home'), 'eidos');
const EIDOS_DASHBOARD_PORT = 3000;
const EIDOS_API_PORT = 8001;
const EIDOS_DASHBOARD_URL = `http://localhost:${EIDOS_DASHBOARD_PORT}`;
const EIDOS_API_URL = `http://localhost:${EIDOS_API_PORT}`;
const EIDOS_GIT_STALE_MS = 14 * 24 * 60 * 60 * 1000;
const EIDOS_GIT_MAX_REPOS = 24;

let eidosDashboardProcess = null;
let eidosProductionBuildFailed = false; // don't re-run a failing `next build` every launch

function eidosGitPath() {
  return commandExists('git', [
    '/opt/homebrew/bin',
    '/usr/local/bin',
  ]);
}

function eidosRunGit(args, { timeout = 6000 } = {}) {
  const git = eidosGitPath();
  if (!git) {
    return { ok: false, status: null, stdout: '', stderr: 'Git CLI not found' };
  }

  const envPath = [path.dirname(git), process.env.PATH || ''].filter(Boolean).join(path.delimiter);
  const result = spawnSync(git, args, {
    encoding: 'utf8',
    timeout,
    env: {
      ...process.env,
      PATH: envPath,
    },
  });
  if (result.error) {
    return { ok: false, status: null, stdout: result.stdout || '', stderr: result.error.message };
  }
  return {
    ok: result.status === 0,
    status: result.status,
    stdout: result.stdout || '',
    stderr: result.stderr || '',
  };
}

function eidosParseStoredGitShellProjects(raw) {
  if (typeof raw !== 'string' || !raw.trim()) return [];
  try {
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed) ? parsed : [];
  } catch {
    return [];
  }
}

function eidosCollectCandidateRepoPaths(appData) {
  const home = app.getPath('home');
  const candidates = new Set();
  const gitShellProjects = eidosParseStoredGitShellProjects(appData?.gitshells_projects);

  const addCandidate = (value) => {
    if (typeof value !== 'string') return;
    const trimmed = value.trim();
    if (!trimmed || trimmed === '/' || trimmed === home) return;
    candidates.add(trimmed);
  };

  for (const project of gitShellProjects) {
    addCandidate(project?.path);
  }
  addCandidate(appData?.working_directory);
  addCandidate(EIDOS_DIR);
  addCandidate(app.getAppPath());
  for (const workspacePath of workspaceGrants.roots()) {
    addCandidate(workspacePath);
  }

  return {
    paths: [...candidates],
    gitShellProjectCount: gitShellProjects.length,
  };
}

function eidosResolveRepoRoot(candidatePath) {
  if (typeof candidatePath !== 'string' || !candidatePath.trim()) return '';
  const resolved = path.resolve(candidatePath.trim());

  try {
    if (!fsSync.statSync(resolved).isDirectory()) return '';
  } catch {
    return '';
  }

  const rootResult = eidosRunGit(['-C', resolved, 'rev-parse', '--show-toplevel'], { timeout: 3000 });
  if (!rootResult.ok) return '';

  const repoRoot = rootResult.stdout.trim();
  if (!repoRoot) return '';

  try {
    if (!fsSync.statSync(repoRoot).isDirectory()) return '';
  } catch {
    return '';
  }
  return path.resolve(repoRoot);
}

function eidosCollectRepoSnapshot(repoRoot, nowMs) {
  const statusResult = eidosRunGit(['-C', repoRoot, 'status', '--porcelain'], { timeout: 6000 });
  if (!statusResult.ok) return null;

  let stagedFiles = 0;
  let unstagedFiles = 0;
  let untrackedFiles = 0;
  const changedPaths = new Set();

  for (const line of statusResult.stdout.split('\n')) {
    if (!line) continue;
    const xy = line.slice(0, 2);
    if (xy === '??') {
      untrackedFiles += 1;
    } else {
      if (xy[0] !== ' ' && xy[0] !== '?') stagedFiles += 1;
      if (xy[1] !== ' ' && xy[1] !== '?') unstagedFiles += 1;
    }

    const rawPath = line.slice(3).trim();
    if (!rawPath) continue;
    const normalizedPath = rawPath.includes(' -> ')
      ? rawPath.split(' -> ').pop()
      : rawPath;
    if (normalizedPath) changedPaths.add(normalizedPath.replace(/^"|"$/g, ''));
  }

  let branch = 'detached';
  const branchResult = eidosRunGit(['-C', repoRoot, 'rev-parse', '--abbrev-ref', 'HEAD'], { timeout: 3000 });
  if (branchResult.ok && branchResult.stdout.trim()) {
    const nextBranch = branchResult.stdout.trim();
    branch = nextBranch === 'HEAD' ? 'detached' : nextBranch;
  }

  let upstream = '';
  const upstreamResult = eidosRunGit(['-C', repoRoot, 'rev-parse', '--abbrev-ref', '--symbolic-full-name', '@{upstream}'], { timeout: 3000 });
  if (upstreamResult.ok) {
    upstream = upstreamResult.stdout.trim();
  }

  let aheadCommits = 0;
  let behindCommits = 0;
  if (upstream) {
    const aheadBehindResult = eidosRunGit(['-C', repoRoot, 'rev-list', '--left-right', '--count', `HEAD...${upstream}`], { timeout: 3000 });
    if (aheadBehindResult.ok) {
      const match = aheadBehindResult.stdout.trim().match(/^(\d+)\s+(\d+)$/);
      if (match) {
        aheadCommits = Number.parseInt(match[1], 10) || 0;
        behindCommits = Number.parseInt(match[2], 10) || 0;
      }
    }
  }

  let lastCommitAt = null;
  let lastCommitMessage = '';
  const lastCommitResult = eidosRunGit(['-C', repoRoot, 'log', '-1', '--format=%ct%x09%s'], { timeout: 3000 });
  if (lastCommitResult.ok && lastCommitResult.stdout.trim()) {
    const [rawTimestamp, ...messageParts] = lastCommitResult.stdout.trim().split('\t');
    const timestamp = Number.parseInt(rawTimestamp, 10);
    if (Number.isFinite(timestamp) && timestamp > 0) {
      lastCommitAt = timestamp * 1000;
    }
    lastCommitMessage = messageParts.join('\t').trim();
  }

  const changedFiles = changedPaths.size;
  const openCommits = aheadCommits;
  const hasOpenWork = changedFiles > 0 || openCommits > 0 || behindCommits > 0;
  const stale = lastCommitAt != null ? (nowMs - lastCommitAt) > EIDOS_GIT_STALE_MS : false;
  const attentionScore = (changedFiles * 2) + (openCommits * 5) + (behindCommits * 3) + (stale ? 1 : 0);

  return {
    id: createHash('sha1').update(repoRoot).digest('hex').slice(0, 12),
    name: path.basename(repoRoot),
    path: repoRoot,
    branch,
    upstream,
    openCommits,
    aheadCommits,
    behindCommits,
    stagedFiles,
    unstagedFiles,
    untrackedFiles,
    changedFiles,
    hasOpenWork,
    stale,
    attentionScore,
    lastCommitAt,
    lastCommitMessage,
  };
}

async function eidosBuildInsightsPayload() {
  const nowMs = Date.now();
  const appData = await readAppData();
  const { paths: candidatePaths, gitShellProjectCount } = eidosCollectCandidateRepoPaths(appData);

  const repoRoots = new Set();
  const repos = [];

  for (const candidatePath of candidatePaths) {
    if (repos.length >= EIDOS_GIT_MAX_REPOS) break;
    const repoRoot = eidosResolveRepoRoot(candidatePath);
    if (!repoRoot || repoRoots.has(repoRoot)) continue;
    repoRoots.add(repoRoot);
    const snapshot = eidosCollectRepoSnapshot(repoRoot, nowMs);
    if (snapshot) repos.push(snapshot);
  }

  repos.sort((a, b) => (
    b.attentionScore - a.attentionScore
    || (b.lastCommitAt || 0) - (a.lastCommitAt || 0)
    || a.name.localeCompare(b.name)
  ));

  const openRepoCount = repos.filter(repo => repo.hasOpenWork).length;
  const reposWithOpenCommits = repos.filter(repo => repo.openCommits > 0).length;
  const reposNeedingPull = repos.filter(repo => repo.behindCommits > 0).length;
  const cleanRepoCount = repos.length - openRepoCount;
  const staleRepoCount = repos.filter(repo => repo.stale).length;
  const totalOpenCommits = repos.reduce((sum, repo) => sum + repo.openCommits, 0);
  const totalChangedFiles = repos.reduce((sum, repo) => sum + repo.changedFiles, 0);
  const totalUntrackedFiles = repos.reduce((sum, repo) => sum + repo.untrackedFiles, 0);
  const branchCount = new Set(repos.map(repo => repo.branch).filter(Boolean)).size;
  const attentionRepos = repos.filter(repo => repo.hasOpenWork).slice(0, 8);

  let dockerCheck = { ok: false, runtime: 'unknown' };
  try {
    dockerCheck = await eidosCheckDocker();
  } catch {}

  let apiHealthy = false;
  let dashboardHealthy = false;
  try {
    [apiHealthy, dashboardHealthy] = await Promise.all([
      eidosCheckApiHealth(),
      eidosCheckDashboardHealth(),
    ]);
  } catch {}

  return {
    ok: true,
    generatedAt: new Date(nowMs).toISOString(),
    summary: {
      repoCount: repos.length,
      openRepoCount,
      cleanRepoCount,
      reposWithOpenCommits,
      reposNeedingPull,
      staleRepoCount,
      branchCount,
      totalOpenCommits,
      totalChangedFiles,
      totalUntrackedFiles,
    },
    services: {
      runtime: dockerCheck?.runtime || 'unknown',
      apiHealthy,
      dashboardHealthy,
    },
    repos,
    attentionRepos,
    sources: {
      candidateCount: candidatePaths.length,
      gitShellProjectCount,
      hasWorkingDirectory: typeof appData?.working_directory === 'string' && appData.working_directory.trim().length > 0,
    },
  };
}

function eidosOrbStackPath() {
  const home = app.getPath('home');
  // OrbStack installs its CLI via Homebrew at /opt/homebrew/bin/orb or /usr/local/bin/orb
  const orb = commandExists('orb', [
    '/opt/homebrew/bin',
    '/usr/local/bin',
    path.join(home, '.local', 'bin'),
  ]);
  return orb;
}

function eidosDockerPath() {
  return commandExists('docker', [
    '/opt/homebrew/bin',
    '/usr/local/bin',
    '/Applications/OrbStack.app/Contents/MacOS',
  ]);
}

async function eidosCheckDocker() {
  const docker = eidosDockerPath();
  if (!docker) {
    // OrbStack might be installed but docker CLI not on PATH — try orbctl
    const orb = eidosOrbStackPath();
    if (orb) {
      return { ok: true, runtime: 'orbstack', orbPath: orb };
    }
    return { ok: false, error: 'Neither Docker nor OrbStack CLI found. Install OrbStack from https://orbstack.dev' };
  }

  // Check if docker daemon is responsive
  const result = spawnSync(docker, ['info', '-f', '{{.ServerVersion}}'], {
    encoding: 'utf8',
    timeout: 5000,
  });
  if (result.status === 0 && result.stdout.trim()) {
    return { ok: true, runtime: 'docker', dockerPath: docker, version: result.stdout.trim() };
  }

  // Docker CLI exists but daemon not running — try starting OrbStack
  const orb = eidosOrbStackPath();
  if (orb) {
    return { ok: false, runtime: 'orbstack-stopped', orbPath: orb, error: 'Docker daemon not running. OrbStack is installed but not started.' };
  }

  return { ok: false, error: 'Docker daemon is not running. Start Docker Desktop or OrbStack.' };
}

async function eidosCheckApiHealth() {
  // memU doesn't have a /health endpoint; root returns 200 when ready
  const result = await requestText(EIDOS_API_URL + '/', 3000);
  return result.ok;
}

async function eidosCheckDashboardHealth() {
  const result = await requestText(EIDOS_DASHBOARD_URL, 3000);
  return result.ok;
}

async function eidosStartOrbStack(orbPath) {
  // OrbStack CLI: `orb start` launches the VM
  const result = spawnSync(orbPath, ['start'], {
    encoding: 'utf8',
    timeout: 30000,
  });
  if (result.status !== 0) {
    throw new Error(`OrbStack start failed: ${result.stderr || result.stdout || 'unknown error'}`);
  }
  // Wait for docker daemon to be ready
  const docker = eidosDockerPath();
  if (!docker) throw new Error('Docker CLI not found after starting OrbStack');
  const deadline = Date.now() + 60000;
  while (Date.now() < deadline) {
    const check = spawnSync(docker, ['info'], { encoding: 'utf8', timeout: 5000 });
    if (check.status === 0) return docker;
    await new Promise(r => setTimeout(r, 2000));
  }
  throw new Error('Timed out waiting for Docker daemon after starting OrbStack');
}

async function eidosEnsureDirectoryExists() {
  try {
    await fs.access(EIDOS_DIR);
  } catch (err) {
    if (err.code === 'ENOENT') {
      console.log(`[eidos] Directory ${EIDOS_DIR} not found. Cloning from GitHub...`);
      let result = spawnSync('git', ['clone', 'https://github.com/toshon-jennings/eidos.git', EIDOS_DIR], {
        encoding: 'utf8',
        timeout: 120000,
      });
      if (result.status !== 0) {
        console.log(`[eidos] HTTPS clone failed. Trying SSH fallback...`);
        result = spawnSync('git', ['clone', 'git@github.com:toshon-jennings/eidos.git', EIDOS_DIR], {
          encoding: 'utf8',
          timeout: 120000,
        });
      }
      if (result.status !== 0) {
        throw new Error(`Failed to clone Eidos repository (tried HTTPS and SSH): ${result.stderr || result.stdout || 'unknown error'}`);
      }
      console.log(`[eidos] Cloned successfully to ${EIDOS_DIR}`);

      console.log(`[eidos] Running npm install in ${EIDOS_DIR}...`);
      const npmCmd = process.platform === 'win32' ? 'npm.cmd' : 'npm';
      const installRes = spawnSync(npmCmd, ['install'], {
        cwd: EIDOS_DIR,
        encoding: 'utf8',
        timeout: 180000,
      });
      if (installRes.status !== 0) {
        throw new Error(`Failed to run npm install in Eidos directory: ${installRes.stderr || installRes.stdout || 'unknown error'}`);
      }
      console.log('[eidos] npm install completed.');
    } else {
      throw err;
    }
  }
}

async function eidosStartCompose(dockerPath) {
  // Use docker compose up -d in the eidos directory
  const result = spawnSync(dockerPath, ['compose', 'up', '-d', '--wait'], {
    cwd: EIDOS_DIR,
    encoding: 'utf8',
    timeout: 300000, // 5 min for pulls
    env: {
      ...process.env,
      PATH: [path.dirname(dockerPath), process.env.PATH || ''].filter(Boolean).join(path.delimiter),
    },
  });
  if (result.status !== 0) {
    throw new Error(`docker compose up failed: ${result.stderr || result.stdout || 'unknown error'}`);
  }
}

function eidosStopDashboardProcess() {
  if (eidosDashboardProcess) {
    try {
      if (eidosDashboardProcess.pid) {
        try { process.kill(-eidosDashboardProcess.pid, 'SIGKILL'); } catch (_) {}
        try { eidosDashboardProcess.kill('SIGKILL'); } catch (_) {}
      }
    } catch (_) {}
    eidosDashboardProcess = null;
  }
  try {
    const { listeners } = scanSockets();
    const pids = [...new Set(listeners.filter(l => l.port === EIDOS_DASHBOARD_PORT && l.pid && l.pid !== process.pid).map(l => l.pid))];
    if (pids.length === 0 && process.platform !== 'win32') {
      const out = execCmd(`lsof -t -iTCP:${EIDOS_DASHBOARD_PORT} -sTCP:LISTEN`);
      const p = out.split('\n').map(s => parseInt(s.trim(), 10)).filter(id => !isNaN(id) && id > 0 && id !== process.pid);
      pids.push(...p);
    }
    for (const pid of new Set(pids)) {
      try { process.kill(pid, 'SIGKILL'); } catch (_) {}
    }
  } catch (err) {
    console.warn('[eidos] Error stopping dashboard process:', err.message);
  }
}

// A production build (`next start`) serves precompiled output, so the dashboard
// paints almost immediately. `next dev` compiles each route on first request,
// which is the main reason the embedded Eidos window is slow to first load.
// `.next/BUILD_ID` is written only by `next build`, never by `next dev`.
function eidosHasProductionBuild() {
  try {
    return fsSync.existsSync(path.join(EIDOS_DIR, '.next', 'BUILD_ID'));
  } catch {
    return false;
  }
}

// An unread OS pipe stalls the writing child once its buffer fills (~64KB on
// macOS). Both Eidos children are chatty — `next build` streams progress, and
// `next dev`/`next start` log per request — so their pipes have to be drained
// or they hang instead of crashing, which is far harder to diagnose. Keeps a
// bounded tail so a failure can be reported with the output that explains it.
function drainEidosOutput(proc) {
  let tail = '';
  const append = (chunk) => { tail = (tail + chunk.toString()).slice(-16000); };
  proc.stdout?.on('data', append);
  proc.stderr?.on('data', append);
  return () => tail.trim();
}

// One-time production build. Uses async spawn (not spawnSync) so the Electron
// main process event loop stays free while the build runs concurrently with the
// container stack. Returns false on failure so the caller can fall back to dev.
function eidosBuildDashboard() {
  return new Promise((resolve) => {
    const npmCmd = process.platform === 'win32' ? 'npm.cmd' : 'npm';
    console.log('[eidos] Building dashboard for production (one-time)…');
    const proc = spawn(npmCmd, ['run', 'build'], {
      cwd: EIDOS_DIR,
      env: { ...process.env },
      stdio: 'pipe',
    });
    const readOutput = drainEidosOutput(proc);
    proc.on('error', (err) => {
      console.warn('[eidos] Production build error; falling back to dev server:', err.message);
      resolve(false);
    });
    proc.on('exit', (code) => {
      if (code === 0) {
        console.log('[eidos] Dashboard production build complete.');
        resolve(true);
      } else {
        console.warn(`[eidos] Production build exited ${code}; falling back to dev server.`);
        const output = readOutput();
        if (output) console.warn(`[eidos] Build output tail:\n${output}`);
        resolve(false);
      }
    });
  });
}

async function eidosStartDashboard() {
  if (eidosDashboardProcess) {
    // Already running — verify it's healthy
    const healthy = await eidosCheckDashboardHealth();
    if (healthy) return;
    // Not healthy — kill and restart
    eidosStopDashboardProcess();
  }

  // Check if something is already on port 3000
  const portCheck = await requestText(EIDOS_DASHBOARD_URL, 2000);
  if (portCheck.ok) return; // Something healthy is already serving

  // Clear any dead/unhealthy process on port 3000
  eidosStopDashboardProcess();

  // Prefer serving a production build for fast first paint. Build once if needed;
  // if the build fails (Eidos repo may lag), fall back to `next dev` so the
  // window still works.
  let built = eidosHasProductionBuild();
  if (!built && !eidosProductionBuildFailed) {
    built = await eidosBuildDashboard();
    if (!built) eidosProductionBuildFailed = true;
  }
  if (!built) {
    // If no valid production build exists, clear any partial/corrupted .next build directory
    // so `next dev` doesn't throw ENOENT on missing routes-manifest.json and return 500 errors.
    try {
      fsSync.rmSync(path.join(EIDOS_DIR, '.next'), { recursive: true, force: true });
    } catch (_) {}
  }
  const script = built ? 'start' : 'dev';

  const npmCmd = process.platform === 'win32' ? 'npm.cmd' : 'npm';
  eidosDashboardProcess = spawn(npmCmd, ['run', script, '--', '-p', String(EIDOS_DASHBOARD_PORT)], {
    cwd: EIDOS_DIR,
    env: {
      ...process.env,
      PORT: String(EIDOS_DASHBOARD_PORT),
    },
    stdio: 'pipe',
  });

  const readDashboardOutput = drainEidosOutput(eidosDashboardProcess);

  eidosDashboardProcess.on('error', (err) => {
    console.error('[eidos] Dashboard process error:', err);
    eidosDashboardProcess = null;
  });

  eidosDashboardProcess.on('exit', (code) => {
    console.log(`[eidos] Dashboard process exited with code ${code}`);
    const output = readDashboardOutput();
    if (code !== 0 && output) console.warn(`[eidos] Dashboard output tail:\n${output}`);
    eidosDashboardProcess = null;
  });

  // Wait for the dev server to be ready
  const deadline = Date.now() + 60000;
  while (Date.now() < deadline) {
    const check = await eidosCheckDashboardHealth();
    if (check) return;
    await new Promise(r => setTimeout(r, 1500));
  }
  const output = readDashboardOutput();
  throw new Error(
    `Timed out waiting for Eidos dashboard to start${output ? `:\n${output}` : ''}`
  );
}

async function eidosStopCompose(dockerPath) {
  const result = spawnSync(dockerPath, ['compose', 'down'], {
    cwd: EIDOS_DIR,
    encoding: 'utf8',
    timeout: 60000,
    env: {
      ...process.env,
      PATH: [path.dirname(dockerPath), process.env.PATH || ''].filter(Boolean).join(path.delimiter),
    },
  });
  if (result.status !== 0) {
    console.error('[eidos] docker compose down failed:', result.stderr || result.stdout);
  }
}

ipcMain.handle('eidos:status', async () => {
  try {
    const dockerCheck = await eidosCheckDocker();
    if (!dockerCheck.ok) {
      return { state: 'no-docker', ...dockerCheck };
    }

    const dockerPath = dockerCheck.dockerPath || eidosDockerPath();
    const apiHealthy = await eidosCheckApiHealth();
    const dashboardHealthy = await eidosCheckDashboardHealth();

    if (apiHealthy && dashboardHealthy) {
      return { state: 'running', runtime: dockerCheck.runtime, api: EIDOS_API_URL, dashboard: EIDOS_DASHBOARD_URL };
    }

    // Docker is running but stack isn't fully up
    return { state: 'docker-ready', runtime: dockerCheck.runtime, apiHealthy, dashboardHealthy };
  } catch (err) {
    return { state: 'error', error: err.message };
  }
});

const startEidosServices = singleFlight(async () => {
  try {
    // Step 1: Ensure Docker/OrbStack is available and running
    let dockerCheck = await eidosCheckDocker();
    if (!dockerCheck.ok) {
      if (dockerCheck.runtime === 'orbstack-stopped' && dockerCheck.orbPath) {
        await eidosStartOrbStack(dockerCheck.orbPath);
        dockerCheck = await eidosCheckDocker();
      }
      if (!dockerCheck.ok) {
        return { error: dockerCheck.error || 'Docker/OrbStack not available' };
      }
    }

    const dockerPath = dockerCheck.dockerPath || eidosDockerPath();

    // Ensure Eidos directory exists (clone and install dependencies if missing)
    await eidosEnsureDirectoryExists();

    // Step 2: Start the dashboard server concurrently with the container stack.
    // It only depends on its own port — never on the API or containers — so its
    // (build +) startup overlaps the slow `docker compose up` instead of running
    // after it. The .catch keeps an early failure from becoming an unhandled
    // rejection while we await compose/API below; it's surfaced afterward.
    const dashboardPromise = eidosStartDashboard().catch((err) => ({ __dashboardError: err }));

    // Step 3: Start the Docker Compose stack (idempotent — safe if already running)
    await eidosStartCompose(dockerPath);

    // Step 4: Wait for the memU API to be healthy
    const apiDeadline = Date.now() + 120000;
    let apiReady = false;
    while (Date.now() < apiDeadline) {
      apiReady = await eidosCheckApiHealth();
      if (apiReady) break;
      await new Promise(r => setTimeout(r, 3000));
    }
    if (!apiReady) {
      return { error: 'Docker containers started but memU API did not become healthy within 2 minutes' };
    }

    // Step 5: Ensure the dashboard (started in step 2) finished coming up
    const dashboardResult = await dashboardPromise;
    if (dashboardResult && dashboardResult.__dashboardError) {
      throw dashboardResult.__dashboardError;
    }

    return { ok: true, state: 'running', api: EIDOS_API_URL, dashboard: EIDOS_DASHBOARD_URL };
  } catch (err) {
    return { error: err.message };
  }
});

ipcMain.handle('eidos:start', async (event) => {
  assertTrustedMainFrame(event);
  return startEidosServices();
});

// Progress polling — renderer calls this to get current step during startup
ipcMain.handle('eidos:progress', async () => {
  try {
    const dockerCheck = await eidosCheckDocker();
    if (!dockerCheck.ok) {
      return { step: 0, label: 'Checking OrbStack / Docker', error: dockerCheck.error || null };
    }

    const apiHealthy = await eidosCheckApiHealth();
    if (!apiHealthy) {
      return { step: 2, label: 'Pulling & starting containers', error: null };
    }

    const dashboardHealthy = await eidosCheckDashboardHealth();
    if (!dashboardHealthy) {
      return { step: 3, label: 'Waiting for Eidos dashboard', error: null };
    }

    return { step: 4, label: 'Ready', done: true };
  } catch (err) {
    return { step: 0, label: 'Error', error: err.message };
  }
});

