// — Cleanmac — developer cache cleanup runner —————————————————————————————
function parseDockerVolumeNames(stdout) {
  return stdout
    .split(/\r?\n/)
    .map(line => line.trim())
    .filter(Boolean);
}

function parseDockerInfo(stdout) {
  try {
    return JSON.parse(stdout);
  } catch {
    return {};
  }
}

function normalizeDockerVolume(record) {
  const labels = record?.Labels && typeof record.Labels === 'object' ? record.Labels : {};
  const composeProject = labels['com.docker.compose.project'] || '';
  const composeVolume = labels['com.docker.compose.volume'] || '';
  const labelEntries = Object.entries(labels)
    .filter(([key, value]) => key && value)
    .slice(0, 8)
    .map(([key, value]) => `${key}=${value}`);

  return {
    name: record?.Name || '',
    driver: record?.Driver || '',
    createdAt: record?.CreatedAt || '',
    mountpoint: record?.Mountpoint || '',
    scope: record?.Scope || '',
    composeProject,
    composeVolume,
    labels: labelEntries,
  };
}

async function inspectCleanmacDockerCandidates() {
  const checkedAt = new Date().toISOString();
  const dockerPath = eidosDockerPath();
  if (!dockerPath) {
    return {
      ok: true,
      available: false,
      checkedAt,
      candidateCount: 0,
      volumes: [],
      error: 'Docker CLI not found. The Docker cleanup block will be skipped unless Docker is installed before running.',
    };
  }

  const infoResult = await runCli(dockerPath, ['info', '--format', '{{json .}}'], 8000);
  if (!infoResult.ok) {
    return {
      ok: true,
      available: false,
      checkedAt,
      dockerPath,
      candidateCount: 0,
      volumes: [],
      error: (infoResult.stderr || infoResult.error || 'Docker daemon is not reachable.').trim(),
    };
  }

  const contextResult = await runCli(dockerPath, ['context', 'show'], 5000);
  const info = parseDockerInfo(infoResult.stdout);
  const listResult = await runCli(dockerPath, ['volume', 'ls', '--filter', 'dangling=true', '--quiet'], 10000);
  if (!listResult.ok) {
    return {
      ok: false,
      available: true,
      checkedAt,
      dockerPath,
      context: contextResult.ok ? contextResult.stdout.trim() : '',
      candidateCount: 0,
      volumes: [],
      error: (listResult.stderr || listResult.error || 'Could not list unused Docker volumes.').trim(),
    };
  }

  const volumeNames = parseDockerVolumeNames(listResult.stdout);
  const selectedNames = volumeNames.slice(0, 80);
  let volumes = selectedNames.map(name => ({ name }));

  if (selectedNames.length > 0) {
    const inspectResult = await runCli(dockerPath, ['volume', 'inspect', ...selectedNames], 15000);
    if (inspectResult.ok) {
      try {
        const inspected = JSON.parse(inspectResult.stdout);
        if (Array.isArray(inspected)) {
          volumes = inspected.map(normalizeDockerVolume).filter(volume => volume.name);
        }
      } catch {
        // Keep the name-only list from `docker volume ls` if inspect JSON parsing fails.
      }
    }
  }

  return {
    ok: true,
    available: true,
    checkedAt,
    dockerPath,
    context: contextResult.ok ? contextResult.stdout.trim() : '',
    serverVersion: info.ServerVersion || '',
    operatingSystem: info.OperatingSystem || '',
    storageDriver: info.Driver || '',
    candidateCount: volumeNames.length,
    truncated: volumeNames.length > selectedNames.length,
    volumes,
  };
}

ipcMain.handle('cleanmac:inspect-docker', async () => inspectCleanmacDockerCandidates());

// Generic Docker/OrbStack status check — reusable by any window that needs
// a Docker-dependent localhost service (Open Notebook, etc). Returns a
// state string the renderer can branch on:
//   'running'          — Docker daemon is up
//   'orbstack'         — OrbStack is running (same as 'running' but identifies runtime)
//   'orbstack-stopped' — OrbStack installed but not started
//   'not-installed'    — Neither Docker nor OrbStack found
//   'error'            — Unexpected failure
ipcMain.handle('docker:status', async () => {
  try {
    const dockerCheck = await eidosCheckDocker();
    if (dockerCheck.ok) {
      return { state: 'running', runtime: dockerCheck.runtime };
    }
    if (dockerCheck.runtime === 'orbstack-stopped') {
      return { state: 'orbstack-stopped', orbPath: dockerCheck.orbPath, error: dockerCheck.error };
    }
    if (!dockerCheck.orbPath && !dockerCheck.dockerPath) {
      return { state: 'not-installed', error: dockerCheck.error };
    }
    return { state: 'error', error: dockerCheck.error };
  } catch (err) {
    return { state: 'error', error: err.message };
  }
});

// Start OrbStack when it's installed but stopped. Returns updated status.
ipcMain.handle('docker:start-orbstack', async () => {
  try {
    const dockerCheck = await eidosCheckDocker();
    if (dockerCheck.ok) {
      return { state: 'running', runtime: dockerCheck.runtime, alreadyRunning: true };
    }
    if (dockerCheck.runtime !== 'orbstack-stopped' || !dockerCheck.orbPath) {
      return { state: 'error', error: 'OrbStack is not installed or already starting' };
    }
    await eidosStartOrbStack(dockerCheck.orbPath);
    const recheck = await eidosCheckDocker();
    return { state: recheck.ok ? 'running' : 'error', runtime: recheck.runtime, error: recheck.error };
  } catch (err) {
    return { state: 'error', error: err.message };
  }
});

