// Backs up a named volume to a tar.gz under userData before any destructive
// action touches it — mirrors Cleanmac's "review before prune" gate but as an
// affirmative export instead of a checkbox, since a volume can be restored
// from the tarball even after `docker volume rm`.
ipcMain.handle('docker:backup-volume', async (event, { name } = {}) => {
  const dockerPath = eidosDockerPath();
  if (!dockerPath || !name) return { ok: false, error: 'Docker CLI or volume name missing.' };

  const backupDir = path.join(app.getPath('userData'), 'docker-backups');
  await fs.mkdir(backupDir, { recursive: true });
  const safeName = name.replace(/[^a-zA-Z0-9._-]/g, '_');
  const fileName = `${safeName}-${Date.now()}.tar.gz`;
  const result = await runCli(dockerPath, [
    'run', '--rm',
    '-v', `${name}:/backup-source:ro`,
    '-v', `${backupDir}:/backup-dest`,
    'alpine',
    'tar', 'czf', `/backup-dest/${fileName}`, '-C', '/backup-source', '.',
  ], 60000);

  if (!result.ok) {
    return { ok: false, error: (result.stderr || result.error || 'Backup failed.').trim() };
  }
  return { ok: true, path: path.join(backupDir, fileName) };
});

// type: 'container' | 'image' | 'volume'. Requires explicit confirm:true from
// the renderer, sent only after the user has seen the item and (for volumes)
// been offered the backup step above — same two-step spirit as Cleanmac's
// confirmedDockerReview checkbox, applied to any live destroy, not just prune.
ipcMain.handle('docker:remove', async (event, { type, id, confirm } = {}) => {
  const dockerPath = eidosDockerPath();
  if (!dockerPath || !id || !type) return { ok: false, error: 'Docker CLI, id, or type missing.' };
  if (!confirm) return { ok: false, error: 'Removal was not confirmed.' };

  const command = { container: ['rm', '-f'], image: ['rmi'], volume: ['volume', 'rm'] }[type];
  if (!command) return { ok: false, error: `Unknown resource type: ${type}` };

  const result = await runCli(dockerPath, [...command, id], 15000);
  return { ok: result.ok, error: result.ok ? null : (result.stderr || result.error || 'Remove failed.').trim() };
});

// — DB Inspector — read-only SQLite browsing via the system sqlite3 CLI —————
function sqlite3Path() {
  return commandExists('sqlite3', ['/opt/homebrew/bin', '/usr/local/bin']);
}

// Blocks multi-statement chaining and value-setting PRAGMAs; the `-readonly`
// flag passed to sqlite3 below is the real backstop (opens the DB connection
// itself read-only), this is just a cheap first filter.
function isReadOnlySql(query) {
  const trimmed = (query || '').trim().replace(/;\s*$/, '');
  if (!trimmed || trimmed.includes(';')) return false;
  if (/^pragma\b/i.test(trimmed) && trimmed.includes('=')) return false;
  return /^(select|with|explain|pragma)\b/i.test(trimmed);
}

// Scans the home directory for SQLite files so the user never has to hunt
// through Finder's hidden dotfolders (~/.hermes, ~/.autoforge, etc. — where
// almost every local db actually lives) to find one manually.
ipcMain.handle('db:discover', async () => {
  const home = app.getPath('home');
  const result = await runCli('find', [
    home, '-maxdepth', '4',
    '(', '-name', '*.db', '-o', '-name', '*.sqlite', '-o', '-name', '*.sqlite3', '-o', '-name', '*.db3', ')',
    '-not', '-path', '*/node_modules/*',
    '-not', '-path', '*/Library/*',
    '-not', '-path', '*/.git/*',
    '-not', '-path', '*/venv/*',
    '-not', '-path', '*/.venv/*',
  ], 8000);

  // `find` exits non-zero whenever it hits even one permission-denied
  // directory while walking the whole home folder — expected on a full scan
  // and not a real failure, so only treat this as an error if stdout is
  // actually empty too.
  const allPaths = result.stdout.split(/\r?\n/).map(l => l.trim()).filter(Boolean);
  if (allPaths.length === 0 && !result.ok) {
    return { ok: false, error: (result.stderr || result.error || 'Scan failed.').trim(), paths: [] };
  }

  // Named project folders (~/opal, ~/osiris, ...) rank above dotfolder tool
  // state (~/.cache, ~/.codex, ...) — there are usually far more of the
  // latter, and they'd otherwise bury the databases the user actually asked
  // about under an alphabetical cap.
  const isDotTopLevel = (p) => p.slice(home.length + 1).startsWith('.');
  allPaths.sort((a, b) => {
    const dotA = isDotTopLevel(a);
    const dotB = isDotTopLevel(b);
    if (dotA !== dotB) return dotA ? 1 : -1;
    return a.localeCompare(b);
  });
  const paths = allPaths.slice(0, 80);
  return { ok: true, paths };
});

ipcMain.handle('db:pick-file', async (event) => {
  assertTrustedMainFrame(event);
  const parentWindow = BrowserWindow.fromWebContents(event.sender)
    || (mainWindow && !mainWindow.isDestroyed() ? mainWindow : null)
    || BrowserWindow.getFocusedWindow();

  const dialogOptions = {
    title: 'Select SQLite Database',
    properties: ['openFile'],
    filters: [
      { name: 'SQLite Database', extensions: ['db', 'sqlite', 'sqlite3', 'db3'] },
      { name: 'All Files', extensions: ['*'] },
    ],
  };
  const result = parentWindow && !parentWindow.isDestroyed()
    ? await dialog.showOpenDialog(parentWindow, dialogOptions)
    : await dialog.showOpenDialog(dialogOptions);

  if (result.canceled || !result.filePaths[0]) return null;
  const chosenPath = await fsSync.promises.realpath(result.filePaths[0]);
  if (!(await fsSync.promises.lstat(chosenPath)).isFile()) return null;
  if (!selectedDatabasePaths.has(event.sender.id)) selectedDatabasePaths.set(event.sender.id, new Set());
  selectedDatabasePaths.get(event.sender.id).add(chosenPath);
  return chosenPath;
});

ipcMain.handle('db:schema', async (event, { dbPath } = {}) => {
  if (!(await isSelectedDatabase(event, dbPath))) return { ok: false, error: 'Access Denied: pick the file again to grant access.' };
  const sqlitePath = sqlite3Path();
  if (!sqlitePath) return { ok: false, error: 'sqlite3 CLI not found on this Mac.' };

  const result = await runCli(sqlitePath, ['-readonly', '-json', dbPath, "SELECT name, sql FROM sqlite_master WHERE type='table' ORDER BY name"], 10000);
  if (!result.ok) return { ok: false, error: (result.stderr || result.error || 'Could not read schema.').trim() };
  try {
    return { ok: true, tables: result.stdout.trim() ? JSON.parse(result.stdout) : [] };
  } catch {
    return { ok: false, error: 'Could not parse schema output.' };
  }
});

ipcMain.handle('db:query', async (event, { dbPath, sql } = {}) => {
  if (!(await isSelectedDatabase(event, dbPath))) return { ok: false, error: 'Access Denied: pick the file again to grant access.' };
  if (!isReadOnlySql(sql)) return { ok: false, error: 'Only single SELECT / WITH / EXPLAIN / read-only PRAGMA statements are allowed.' };
  const sqlitePath = sqlite3Path();
  if (!sqlitePath) return { ok: false, error: 'sqlite3 CLI not found on this Mac.' };

  const result = await runCli(sqlitePath, ['-readonly', '-json', dbPath, sql], 15000);
  if (!result.ok) return { ok: false, error: (result.stderr || result.error || 'Query failed.').trim() };
  try {
    const rows = result.stdout.trim() ? JSON.parse(result.stdout) : [];
    return { ok: true, rows, columns: rows[0] ? Object.keys(rows[0]) : [] };
  } catch {
    return { ok: false, error: 'Could not parse query output.' };
  }
});

ipcMain.handle('cleanmac:run', async (event, opts = {}) => {
  const { BrowserWindow } = require('electron');
  const win = BrowserWindow.fromWebContents(event.sender);
  const scriptPath = path.join(app.getPath('home'), 'cleanmac', 'cleanmac');
  const args = opts.aggressive ? ['--aggressive'] : [];

  return new Promise((resolve) => {
    const child = spawn('/bin/bash', [scriptPath, ...args], {
      env: { ...process.env, HOME: app.getPath('home') },
      stdio: ['ignore', 'pipe', 'pipe'],
      shell: false,
    });

    const send = (type, data) => {
      if (win && !win.isDestroyed()) {
        win.webContents.send('cleanmac:output', { type, data });
      }
    };

    child.stdout.on('data', chunk => send('stdout', chunk.toString()));
    child.stderr.on('data', chunk => send('stderr', chunk.toString()));
    child.on('error', err => {
      send('error', err.message);
      resolve({ ok: false, error: err.message });
    });
    child.on('close', exitCode => {
      send('done', exitCode);
      resolve({ ok: exitCode === 0, exitCode });
    });
  });
});

// ── Packages Dashboard IPC Handlers ────────────────────────────────────────
const packagesPath = path.join(app.getPath('home'), 'opal', 'electron', 'data', 'packages.json');

// Memory cache for packages scan results
let packagesScanCache = null;
let packagesScanCacheTime = 0;
const packageHistory = {}; // maps packageId -> { githubVersion, githubPublishDate, registryVersion, registryPublishDate }

function compareVersions(v1, v2) {
  const parts1 = (v1 || '').split('.').map(x => parseInt(x, 10) || 0);
  const parts2 = (v2 || '').split('.').map(x => parseInt(x, 10) || 0);
  const maxLength = Math.max(parts1.length, parts2.length);
  for (let i = 0; i < maxLength; i++) {
    const p1 = parts1[i] || 0;
    const p2 = parts2[i] || 0;
    if (p1 > p2) return 1;
    if (p1 < p2) return -1;
  }
  return 0;
}

function fetchUrl(url, headers = {}, timeoutMs = 3000) {
  return new Promise((resolve, reject) => {
    const https = require('https');
    const parsedUrl = new URL(url);
    const options = {
      hostname: parsedUrl.hostname,
      path: parsedUrl.pathname + parsedUrl.search,
      method: 'GET',
      headers: {
        'User-Agent': 'PerciPackageDashboard/1.0',
        ...headers,
      },
      timeout: timeoutMs,
    };

    const req = https.request(options, (res) => {
      if (res.statusCode < 200 || res.statusCode >= 300) {
        const error = new Error(`HTTP ${res.statusCode}`);
        error.statusCode = res.statusCode;
        return reject(error);
      }

      let data = '';
      res.on('data', (chunk) => { data += chunk; });
      res.on('end', () => { resolve({ data, headers: res.headers }); });
    });

    req.on('error', (err) => reject(err));
    req.on('timeout', () => {
      req.destroy();
      reject(new Error('Timeout'));
    });
    req.end();
  });
}

async function scanPackage(pkg) {
  const result = {
    ...pkg,
    githubVersion: null,
    githubPublishDate: null,
    registryVersion: null,
    registryPublishDate: null,
    syncStatus: 'unknown',
    stale: false,
    error: null,
  };

  const cacheKey = `${pkg.name}-${pkg.registry}`;
  const history = packageHistory[cacheKey] || {};

  // 1. Fetch GitHub latest release
  if (pkg.githubRepo) {
    try {
      const ghUrl = `https://api.github.com/repos/${pkg.githubRepo}/releases/latest`;
      const res = await fetchUrl(ghUrl, { 'Accept': 'application/vnd.github.v3+json' });
      const data = JSON.parse(res.data);
      result.githubVersion = data.tag_name || null;
      result.githubPublishDate = data.published_at || null;

      // Update history
      history.githubVersion = result.githubVersion;
      history.githubPublishDate = result.githubPublishDate;
    } catch (err) {
      // Fallback: try fetching tags if releases/latest is not found (404) or failed
      try {
        const tagsUrl = `https://api.github.com/repos/${pkg.githubRepo}/tags`;
        const res = await fetchUrl(tagsUrl, { 'Accept': 'application/vnd.github.v3+json' });
        const tags = JSON.parse(res.data);
        if (Array.isArray(tags) && tags.length > 0) {
          result.githubVersion = tags[0].name || null;
          result.githubPublishDate = null;

          history.githubVersion = result.githubVersion;
          history.githubPublishDate = result.githubPublishDate;
        } else {
          throw err;
        }
      } catch (tagErr) {
        result.stale = true;
        result.githubVersion = history.githubVersion || null;
        result.githubPublishDate = history.githubPublishDate || null;
        result.error = `GitHub error: ${err.message}`;
      }
    }
  }

  // 2. Fetch registry data
  const regName = pkg.registryName || pkg.name;
  if (pkg.registry === 'npm') {
    try {
      const npmUrl = `https://registry.npmjs.org/${regName}`;
      const res = await fetchUrl(npmUrl);
      const data = JSON.parse(res.data);
      const version = data['dist-tags']?.latest;
      result.registryVersion = version || null;
      result.registryPublishDate = data.time?.[version] || data.time?.modified || null;

      // Update history
      history.registryVersion = result.registryVersion;
      history.registryPublishDate = result.registryPublishDate;
    } catch (err) {
      result.stale = true;
      result.registryVersion = history.registryVersion || null;
      result.registryPublishDate = history.registryPublishDate || null;
      result.error = (result.error ? `${result.error}; ` : '') + `npm error: ${err.message}`;
    }
  } else if (pkg.registry === 'pypi') {
    try {
      const pypiUrl = `https://pypi.org/pypi/${regName}/json`;
      const res = await fetchUrl(pypiUrl);
      const data = JSON.parse(res.data);
      const version = data.info?.version;
      result.registryVersion = version || null;
      result.registryPublishDate = data.releases?.[version]?.[0]?.upload_time_iso_8601 || data.releases?.[version]?.[0]?.upload_time || null;

      // Update history
      history.registryVersion = result.registryVersion;
      history.registryPublishDate = result.registryPublishDate;
    } catch (err) {
      result.stale = true;
      result.registryVersion = history.registryVersion || null;
      result.registryPublishDate = history.registryPublishDate || null;
      result.error = (result.error ? `${result.error}; ` : '') + `PyPI error: ${err.message}`;
    }
  } else if (pkg.registry === 'homebrew') {
    try {
      const hbUrl = `https://api.github.com/repos/toshon-jennings/homebrew-tap/contents/Formula/${regName}.rb`;
      const res = await fetchUrl(hbUrl, { 'Accept': 'application/vnd.github.v3+json' });
      const data = JSON.parse(res.data);
      const rubyContent = Buffer.from(data.content, 'base64').toString('utf8');

      let version = null;
      const versionMatch = rubyContent.match(/version\s+["']([^"']+)["']/);
      if (versionMatch) {
        version = versionMatch[1];
      } else {
        const urlMatch = rubyContent.match(/url\s+["'].*?\/v?(\d+\.\d+(?:\.\d+)?.*?)\.tar\.gz["']/);
        if (urlMatch) {
          version = urlMatch[1];
        }
      }
      result.registryVersion = version || null;
      result.registryPublishDate = null;

      // Update history
      history.registryVersion = result.registryVersion;
      history.registryPublishDate = result.registryPublishDate;
    } catch (err) {
      result.stale = true;
      result.registryVersion = history.registryVersion || null;
      result.registryPublishDate = history.registryPublishDate || null;
      result.error = (result.error ? `${result.error}; ` : '') + `Homebrew error: ${err.message}`;
    }
  } else if (pkg.registry === 'github') {
    result.registryVersion = result.githubVersion;
    result.registryPublishDate = result.githubPublishDate;
  }

  packageHistory[cacheKey] = history;

  // Determine sync status
  const normGithub = (result.githubVersion || '').replace(/^v/, '').trim();
  const normRegistry = (result.registryVersion || '').replace(/^v/, '').trim();

  if (normGithub && normRegistry) {
    if (normGithub === normRegistry) {
      result.syncStatus = 'match';
    } else {
      const cmp = compareVersions(normGithub, normRegistry);
      if (cmp > 0) {
        result.syncStatus = 'github-ahead';
      } else if (cmp < 0) {
        result.syncStatus = 'registry-ahead';
      } else {
        result.syncStatus = 'match';
      }
    }
  } else {
    result.syncStatus = 'unknown';
  }

  return result;
}

ipcMain.handle('packages:scan', async (event, { force } = {}) => {
  const fs = require('fs');
  const now = Date.now();

  if (!force && packagesScanCache && (now - packagesScanCacheTime < 60000)) {
    return packagesScanCache;
  }

  try {
    if (!fs.existsSync(packagesPath)) {
      return [];
    }
    const raw = fs.readFileSync(packagesPath, 'utf8');
    const packages = JSON.parse(raw);

    const scanned = await Promise.all(packages.map(pkg => scanPackage(pkg)));

    packagesScanCache = scanned;
    packagesScanCacheTime = now;
    return scanned;
  } catch (err) {
    console.error('Error scanning packages:', err);
    return [];
  }
});

ipcMain.handle('packages:get-config', async () => {
  const fs = require('fs');
  try {
    if (!fs.existsSync(packagesPath)) {
      return [];
    }
    const raw = fs.readFileSync(packagesPath, 'utf8');
    return JSON.parse(raw);
  } catch (err) {
    console.error('Error reading packages config:', err);
    return [];
  }
});

ipcMain.handle('packages:set-config', async (event, config) => {
  const fs = require('fs');
  try {
    fs.mkdirSync(path.dirname(packagesPath), { recursive: true });
    fs.writeFileSync(packagesPath, JSON.stringify(config, null, 2), 'utf8');

    packagesScanCache = null;
    packagesScanCacheTime = 0;
    return { ok: true };
  } catch (err) {
    console.error('Error writing packages config:', err);
    return { ok: false, error: err.message };
  }
});

