function retryableLazy(load, selectModule = module => module) {
    let loadFailed = false;
    let failure;
    let retries = 0;
    const createComponent = () => lazy(() => {
        const retryUrl = lazyModuleRetryUrl(failure, import.meta.url, retries);
        return (retryUrl ? import(/* @vite-ignore */ retryUrl) : load())
            .then(selectModule)
            .catch(error => { loadFailed = true; if (!failure) failure = error; throw error; });
    });
    let Component = createComponent();
    return function LazyMode(props) {
        const [attempt, setAttempt] = useState(0);
        return <WindowErrorBoundary key={attempt} onRetry={() => { if (loadFailed) { loadFailed = false; retries = Math.min(3, retries + 1); Component = createComponent(); } setAttempt(value => value + 1); }}>
            <Suspense fallback={<div role="status" className="p-6 text-[var(--text-secondary)]">Loading…</div>}>
                <Component {...props} />
            </Suspense>
        </WindowErrorBoundary>;
    };
}

class ModeErrorBoundary extends Component {
    constructor(props) {
        super(props);
        this.state = { hasError: false, error: null };
    }
    static getDerivedStateFromError(error) {
        return { hasError: true, error };
    }
    componentDidCatch(error, info) {
        console.error('[ModeErrorBoundary] Mode render error:', error, info);
    }
    render() {
        if (this.state.hasError) {
            return (
                <div className="flex h-full flex-col items-center justify-center gap-4 p-8 text-center">
                    <div className="rounded-xl border border-red-500/30 bg-red-500/10 p-6 max-w-lg w-full">
                        <p className="text-sm font-semibold text-red-400 mb-2">Page failed to render</p>
                        <p className="font-mono text-xs text-red-300/80 break-all leading-5">
                            {this.state.error?.message || 'An unexpected error occurred.'}
                        </p>
                        {this.state.error?.stack && (
                            <pre className="mt-3 text-left text-[10px] text-red-300/60 overflow-auto max-h-48 leading-4">
                                {this.state.error.stack}
                            </pre>
                        )}
                        <button
                            onClick={() => this.setState({ hasError: false, error: null })}
                            className="mt-4 rounded-lg border border-red-500/40 px-4 py-1.5 text-xs text-red-300 hover:bg-red-500/10 transition-colors"
                        >
                            Retry
                        </button>
                    </div>
                </div>
            );
        }
        return this.props.children;
    }
}

