    const [bridgeState, setBridgeState] = useState('checking'); // checking | running | stopped | not-installed | error
    const [bridgeError, setBridgeError] = useState('');
    const [data, setData] = useState({ containers: [], images: [], volumes: [] });
    const [loading, setLoading] = useState(false);
    const [listError, setListError] = useState('');
    const [activeTab, setActiveTab] = useState('containers');
    const [pendingRemoveKey, setPendingRemoveKey] = useState(null); // `${type}:${id}`
    const [busyKey, setBusyKey] = useState(null);
    const [backups, setBackups] = useState({}); // name -> { busy, ok, path, error }
    const [startingOrb, setStartingOrb] = useState(false);

    const canUseBridge = Boolean(window.electron?.dockerList);

    const refreshStatus = useCallback(async () => {
        if (!window.electron?.dockerStatus) {
            setBridgeState('error');
            setBridgeError('Perci needs the desktop Docker bridge. Restart Perci after this update.');
            return null;
        }
        const status = await window.electron.dockerStatus();
        const state = status.state === 'orbstack' ? 'running' : status.state === 'orbstack-stopped' ? 'stopped' : status.state;
        setBridgeState(state);
        setBridgeError(status.error || '');
        return state;
    }, []);

    const refreshList = useCallback(async (isCurrent = () => true) => {
        if (!canUseBridge) return;
        setLoading(true);
        try {
            const result = await window.electron.dockerList();
            if (!isCurrent()) return;
            if (result?.ok) {
                setData({ containers: result.containers || [], images: result.images || [], volumes: result.volumes || [] });
                setListError('');
            } else {
                setListError(result?.error || 'Could not load Docker state.');
            }
        } catch (err) {
            if (!isCurrent()) return;
            setListError(err.message || 'Could not load Docker state.');
        } finally {
            if (isCurrent()) setLoading(false);
        }
    }, [canUseBridge]);

    useEffect(() => {
        let cancelled = false;
        (async () => {
            await refreshStatus();
            if (cancelled) return;
        })();
        return () => { cancelled = true; };
    }, [refreshStatus, refreshList]);

    useVisiblePolling(refreshList, POLL_MS, shouldUpdate && bridgeState === 'running');

    const startOrbStack = useCallback(async () => {
        if (!window.electron?.dockerStartOrbStack) return;
        setStartingOrb(true);
        try {
            await window.electron.dockerStartOrbStack();
            const state = await refreshStatus();
            if (state === 'running') await refreshList();
        } finally {
            setStartingOrb(false);
        }
    }, [refreshStatus, refreshList]);

    const stopContainer = useCallback(async (id) => {
        setBusyKey(`container:${id}`);
        try {
            await window.electron.dockerStop(id);
            await refreshList();
        } finally {
            setBusyKey(null);
        }
    }, [refreshList]);

    const backupVolume = useCallback(async (name) => {
        setBackups(prev => ({ ...prev, [name]: { busy: true } }));
        try {
            const result = await window.electron.dockerBackupVolume(name);
            setBackups(prev => ({ ...prev, [name]: result?.ok ? { ok: true, path: result.path } : { error: result?.error || 'Backup failed.' } }));
        } catch (err) {
            setBackups(prev => ({ ...prev, [name]: { error: err.message || 'Backup failed.' } }));
        }
    }, []);

    const removeItem = useCallback(async (type, id) => {
        const key = `${type}:${id}`;
        setBusyKey(key);
        try {
            await window.electron.dockerRemove(type, id, true);
            setPendingRemoveKey(null);
            await refreshList();
        } finally {
            setBusyKey(null);
        }
    }, [refreshList]);

    const counts = useMemo(() => ({
        containers: data.containers.length,
        images: data.images.length,
        volumes: data.volumes.length,
    }), [data]);

    const renderRows = () => {
        if (activeTab === 'containers') {
            if (data.containers.length === 0) return <EmptyState label="No containers" />;
            return data.containers.map(c => {
                const key = `container:${c.id}`;
                const running = isRunningContainer(c.status);
                return (
                    <Row key={c.id}>
                        <RowMain title={c.name} subtitle={c.image} tag={c.status} tagOk={running} />
                        <RowActions>
                            {running && (
                                <ActionButton icon={Square} label="Stop" busy={busyKey === key} onClick={() => stopContainer(c.id)} />
                            )}
                            <ActionButton icon={Trash2} label="Remove" danger busy={busyKey === key} onClick={() => setPendingRemoveKey(pendingRemoveKey === key ? null : key)} />
                        </RowActions>
                        {pendingRemoveKey === key && (
                            <RemoveConfirm
                                type="container"
                                item={{ label: c.name || c.id }}
                                onCancel={() => setPendingRemoveKey(null)}
                                onConfirm={() => removeItem('container', c.id)}
                            />
                        )}
                    </Row>
                );
            });
        }

        if (activeTab === 'images') {
            if (data.images.length === 0) return <EmptyState label="No images" />;
            return data.images.map(i => {
                const key = `image:${i.id}`;
                const label = `${i.repository}:${i.tag}`;
                return (
                    <Row key={i.id}>
                        <RowMain title={label} subtitle={i.id} tag={i.size} />
                        <RowActions>
                            <ActionButton icon={Trash2} label="Remove" danger busy={busyKey === key} onClick={() => setPendingRemoveKey(pendingRemoveKey === key ? null : key)} />
                        </RowActions>
                        {pendingRemoveKey === key && (
                            <RemoveConfirm
                                type="image"
                                item={{ label }}
                                onCancel={() => setPendingRemoveKey(null)}
                                onConfirm={() => removeItem('image', i.id)}
                            />
                        )}
                    </Row>
                );
            });
        }

        if (data.volumes.length === 0) return <EmptyState label="No volumes" />;
        return data.volumes.map(v => {
            const key = `volume:${v.name}`;
            return (
                <Row key={v.name}>
                    <RowMain title={v.name} subtitle={v.driver} />
                    <RowActions>
                        <ActionButton icon={Trash2} label="Remove" danger busy={busyKey === key} onClick={() => setPendingRemoveKey(pendingRemoveKey === key ? null : key)} />
                    </RowActions>
                    {pendingRemoveKey === key && (
                        <RemoveConfirm
                            type="volume"
                            item={{ label: v.name }}
                            backupState={backups[v.name]}
                            onBackup={() => backupVolume(v.name)}
                            onCancel={() => setPendingRemoveKey(null)}
                            onConfirm={() => removeItem('volume', v.name)}
                        />
                    )}
                </Row>
            );
        });
    };

    return (
        <div className="flex h-full min-h-0 flex-col overflow-hidden bg-[var(--bg-primary)] text-[var(--text-primary)]">
            <header className="flex shrink-0 items-center justify-between gap-4 border-b border-[var(--border)] bg-[var(--bg-secondary)] px-4 py-3">
                <div className="flex min-w-0 items-center gap-3">
                    <span className="grid h-10 w-10 shrink-0 place-items-center rounded-lg border border-blue-500/25 bg-blue-500/10 text-blue-400">
                        <ContainerIcon size={19} />
                    </span>
                    <div className="min-w-0">
                        <div className="flex items-center gap-2">
                            <h1 className="m-0 truncate text-base font-semibold leading-5">Docker</h1>
                            <StatusBadge state={bridgeState} />
                        </div>
                        <p className="m-0 truncate text-[11px] text-[var(--text-tertiary)]">
                            {counts.containers} containers · {counts.images} images · {counts.volumes} volumes
                        </p>
                    </div>
                </div>
                <button
                    type="button"
                    onClick={() => void refreshList()}
                    disabled={bridgeState !== 'running' || loading}
                    className="inline-flex h-9 items-center gap-2 rounded-lg border border-[var(--border)] bg-[var(--bg-primary)] px-3 text-xs font-semibold text-[var(--text-primary)] transition-colors hover:bg-[var(--bg-tertiary)] disabled:cursor-not-allowed disabled:opacity-50"
                >
                    {loading ? <Loader2 size={13} className="animate-spin" /> : <RefreshCw size={13} />}
                    Refresh
                </button>
            </header>

            {bridgeState === 'not-installed' && (
                <div className="m-4 rounded-lg border border-amber-500/25 bg-amber-500/10 p-4 text-sm leading-6 text-amber-200">
                    Docker/OrbStack was not found on this Mac.{' '}
                    <a href="https://orbstack.dev" target="_blank" rel="noreferrer" className="inline-flex items-center gap-1 font-semibold text-amber-100 underline">
                        Install OrbStack <ExternalLink size={12} />
                    </a>
                </div>
            )}

            {bridgeState === 'stopped' && (
                <div className="m-4 flex items-center justify-between gap-3 rounded-lg border border-amber-500/25 bg-amber-500/10 p-4 text-sm text-amber-200">
                    <span>OrbStack is installed but not running.</span>
                    <button
                        type="button"
                        onClick={startOrbStack}
                        disabled={startingOrb}
                        className="inline-flex h-8 items-center gap-2 rounded-md bg-amber-500 px-3 text-xs font-bold text-black transition-colors hover:bg-amber-400 disabled:opacity-50"
                    >
                        {startingOrb ? <Loader2 size={13} className="animate-spin" /> : <Play size={13} />}
                        Start OrbStack
                    </button>
                </div>
            )}

            {bridgeState === 'error' && bridgeError && (
                <div className="m-4 rounded-lg border border-red-500/25 bg-red-500/10 p-4 text-sm leading-6 text-red-300">
                    {bridgeError}
                </div>
            )}

            {bridgeState === 'running' && (
                <div className="flex min-h-0 flex-1 flex-col overflow-hidden">
                    <div className="flex shrink-0 gap-1 border-b border-[var(--border)] px-4 pt-3">
                        {TABS.map(tab => (
                            <button
                                key={tab.id}
                                type="button"
                                onClick={() => setActiveTab(tab.id)}
                                className={`inline-flex items-center gap-1.5 rounded-t-md border-b-2 px-3 py-2 text-xs font-semibold transition-colors ${
                                    activeTab === tab.id
                                        ? 'border-blue-500 text-blue-400'
                                        : 'border-transparent text-[var(--text-tertiary)] hover:text-[var(--text-secondary)]'
                                }`}
                            >
                                <tab.icon size={13} />
                                {tab.label}
                                <span className="rounded-full bg-[var(--bg-tertiary)] px-1.5 text-[10px] text-[var(--text-tertiary)]">{counts[tab.id]}</span>
                            </button>
                        ))}
                    </div>

                    <div className="min-h-0 flex-1 overflow-y-auto p-4">
                        {listError && (
                            <div className="mb-3 flex items-center gap-2 rounded-md border border-red-500/25 bg-red-500/10 p-3 text-xs text-red-400">
                                <XCircle size={14} />
                                {listError}
                            </div>
                        )}
                        <div className="grid gap-2">
                            {renderRows()}
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
}

function Row({ children }) {
    return (
        <div className="rounded-lg border border-[var(--border)] bg-[var(--bg-secondary)] p-3">
            <div className="flex items-center justify-between gap-3">
                {children}
            </div>
        </div>
    );
}

function RowMain({ title, subtitle, tag, tagOk }) {
    return (
        <div className="min-w-0">
            <div className="flex items-center gap-2">
                <span className="truncate font-mono text-sm text-[var(--text-primary)]">{title}</span>
                {tag && (
                    <span className={`shrink-0 rounded-full px-2 py-0.5 text-[10px] font-semibold ${tagOk ? 'bg-emerald-500/15 text-emerald-500' : 'bg-[var(--bg-tertiary)] text-[var(--text-tertiary)]'}`}>
                        {tag}
                    </span>
                )}
            </div>
            {subtitle && <div className="truncate text-xs text-[var(--text-tertiary)]">{subtitle}</div>}
        </div>
    );
}

function RowActions({ children }) {
    return <div className="flex shrink-0 items-center gap-1.5">{children}</div>;
}

function ActionButton({ icon: Icon, label, danger, busy, onClick }) {
    return (
        <button
            type="button"
            onClick={onClick}
            disabled={busy}
            className={`inline-flex h-7 items-center gap-1.5 rounded-md border px-2.5 text-[11px] font-semibold transition-colors disabled:cursor-not-allowed disabled:opacity-50 ${
                danger
                    ? 'border-red-500/30 text-red-400 hover:bg-red-500/10'
                    : 'border-[var(--border)] text-[var(--text-primary)] hover:bg-[var(--bg-tertiary)]'
            }`}
        >
            {busy ? <Loader2 size={12} className="animate-spin" /> : <Icon size={12} />}
            {label}
        </button>
    );
}

function EmptyState({ label }) {
    return (
        <div className="flex h-40 flex-col items-center justify-center gap-2 text-center text-[var(--text-tertiary)]">
            <CheckCircle2 size={22} />
            <span className="text-sm">{label}</span>
        </div>
    );
}

import { useServiceAutoStart } from '../context/WindowActivityContext';
import { useCallback, useEffect, useRef, useState } from 'react';
import { AlertCircle, ExternalLink, Play, RefreshCw, RotateCw } from 'lucide-react';
import { launchArgsFor } from '../lib/localServices';

const GH_ORIGIN = 'http://127.0.0.1:6282';

export default function GithubOverviewMode() {
    const autoStart = useServiceAutoStart('github-overview');
    const mountedRef = useRef(false);
    useEffect(() => { mountedRef.current = true; return () => { mountedRef.current = false; }; }, []);
    const webviewRef = useRef(null);
    const canUseWebview = typeof window !== 'undefined' && Boolean(window.electron);
    const [frameKey, setFrameKey] = useState(0);
    const [status, setStatus] = useState('loading'); // 'loading' | 'online' | 'offline'
    const [contentReady, setContentReady] = useState(false);
    const [loadError, setLoadError] = useState(null);
    const [refreshingAll, setRefreshingAll] = useState(false);

    useEffect(() => {
        let active = true;
        setStatus('loading');
        setContentReady(false);
        setLoadError(null);
        if (canUseWebview) return () => { active = false; };
        fetch(GH_ORIGIN, { cache: 'no-store', mode: 'no-cors' })
            .then(res => {
                if (!active) return;
                if (res.type !== 'opaque' && !res.ok) throw new Error(`HTTP ${res.status}`);
                setStatus('online');
            })
            .catch(err => {
                if (!active) return;
                setLoadError(err.message || 'GitHub Overview is not reachable.');
                setStatus('offline');
            });
        return () => { active = false; };
    }, [canUseWebview, frameKey]);

    useEffect(() => {
        if (!canUseWebview) return undefined;
        const webview = webviewRef.current;
        if (!webview) return undefined;
        const onReady = () => { setContentReady(true); setLoadError(null); setStatus('online'); };
        const onFail = (event) => {
            if (!event.isMainFrame || event.errorCode === -3) return;
            setLoadError(event.errorDescription || `Failed to load (code ${event.errorCode})`);
            setStatus('offline');
        };
        const onNewWindow = (event) => {
            if (event.url && (event.url.startsWith('http://') || event.url.startsWith('https://'))) {
                event.preventDefault();
                if (window.electron?.openExternal) {
                    window.electron.openExternal(event.url);
                } else {
                    window.open(event.url, '_blank', 'noopener,noreferrer');
                }
            }
        };
        webview.addEventListener('dom-ready', onReady);
        webview.addEventListener('did-fail-load', onFail);
        webview.addEventListener('new-window', onNewWindow);
        return () => {
            webview.removeEventListener('dom-ready', onReady);
            webview.removeEventListener('did-fail-load', onFail);
            webview.removeEventListener('new-window', onNewWindow);
        };
    }, [canUseWebview, frameKey]);

    const reload = useCallback(() => {
        setLoadError(null);
        setContentReady(false);
        setFrameKey(k => k + 1);
    }, []);

    // Launch the local server from here rather than sending the user to a
    // terminal. The command lives in the shared local-service catalog so the
    // Localhost Manager starts it exactly the same way.
    const [starting, setStarting] = useState(false);
    const canStart = Boolean(window.electron?.localhostStartNow) && Boolean(launchArgsFor('github-overview'));

    const startServer = useCallback(async () => {
        const launch = launchArgsFor('github-overview');
        if (!launch || !window.electron?.localhostStartNow) return;
        setStarting(true);
        setLoadError(null);
        try {
            const result = await window.electron.localhostStartNow(launch);
            if (!mountedRef.current) return;
            if (!result?.ok) throw new Error(result?.error || 'GitHub Overview did not start.');
            // The binary binds its port a moment after spawn (it prunes its poll
            // log first), so wait for it to answer before reloading the view.
            const canProbe = Boolean(window.electron.localhostCheckHealth);
            for (let attempt = 0; attempt < 10; attempt += 1) {
                if (!mountedRef.current) return;
                await new Promise(r => setTimeout(r, 500));
                if (!canProbe) {
                    // Health bridge missing until Perci restarts; fall back to a
                    // fixed grace period rather than reloading after one tick.
                    if (attempt >= 4) break;
                    continue;
                }
                const probe = await window.electron.localhostCheckHealth(GH_ORIGIN);
                if (probe?.ok) break;
            }
            if (!mountedRef.current) return;
            reload();
        } catch (err) {
            if (!mountedRef.current) return;
            setLoadError(err.message || 'GitHub Overview did not start.');
        } finally {
            if (mountedRef.current) setStarting(false);
        }
    }, [reload]);

    // GitHub Overview is a first-class window, so opening it starts its server.
    // One automatic attempt per mount — if the launch fails, the offline screen
    // keeps its Start button rather than retrying in a loop.
    const autoStartedRef = useRef(false);
    useEffect(() => {
        if (!autoStart || status !== 'offline' || autoStartedRef.current || !canStart) return;
        autoStartedRef.current = true;
        startServer();
    }, [status, canStart, startServer, autoStart]);

    const handleRefreshAll = useCallback(async () => {
        setRefreshingAll(true);
        try {
            await fetch(`${GH_ORIGIN}/repos/poll-all`, { method: 'POST' });
        } catch (err) {
            console.error('Failed to trigger refresh all:', err);
        } finally {
            setTimeout(() => setRefreshingAll(false), 800);
        }
    }, []);

    const isOffline = status === 'offline' || Boolean(loadError);

    return (
        <div className="h-full w-full flex flex-col bg-[var(--bg-primary)]">
            <div className="flex items-center gap-2 px-3 py-2 border-b border-[var(--border)] bg-[var(--bg-secondary)]/30 shrink-0">
                <button
                    onClick={reload}
                    className="p-1 rounded text-[var(--text-secondary)] hover:text-[var(--text-primary)] hover:bg-[var(--bg-hover)] transition-colors"
                    title="Reload page"
                >
                    <RotateCw size={14} />
                </button>
                <div className="flex-1 flex items-center gap-2 px-3 py-1.5 rounded-lg bg-[var(--bg-tertiary)] text-xs font-mono text-[var(--text-secondary)]">
                    <span className={`w-2 h-2 rounded-full shrink-0 ${status === 'online' ? 'bg-emerald-400' : (status === 'loading' || starting) ? 'bg-yellow-400 animate-pulse' : 'bg-red-400'}`} />
                    {GH_ORIGIN}
                </div>
                {window.electron?.openExternal && (
                    <button
                        onClick={() => window.electron.openExternal(GH_ORIGIN)}
                        className="p-1 rounded text-[var(--text-secondary)] hover:text-[var(--text-primary)] hover:bg-[var(--bg-hover)] transition-colors"
                        title="Open in browser"
                    >
                        <ExternalLink size={14} />
                    </button>
                )}
            </div>

            {isOffline ? (
                <div className="flex flex-1 items-center justify-center p-8">
                    <div className="max-w-lg text-center">
                        <h2 className="text-lg font-semibold text-[var(--text-primary)]">
                            {starting ? 'Starting GitHub Overview…' : 'GitHub Overview is not running'}
                        </h2>
                        <p className="mt-2 text-sm leading-6 text-[var(--text-secondary)]">
                            GitHub Overview is a self-contained Go binary that polls your repos for commits, CI status, alerts, and PRs. It needs to be running locally on port <code className="rounded bg-[var(--bg-tertiary)] px-1.5 py-0.5 text-xs">6282</code>.
                        </p>
                        {!canStart && (
                            <div className="mt-4 rounded-xl border border-[var(--border)] bg-[var(--bg-secondary)] p-3 text-left">
                                <p className="text-[11px] font-medium text-[var(--text-tertiary)] uppercase tracking-wide mb-2">Install &amp; run</p>
                                <div className="space-y-1.5 font-mono text-xs text-[var(--text-secondary)]">
                                    <p>git clone https://github.com/toshon-jennings/github-overview ~/github-overview</p>
                                    <p>cd ~/github-overview &amp;&amp; go build -o github-overview .</p>
                                    <p>./github-overview serve</p>
                                </div>
                            </div>
                        )}
                        <p className="mt-3 text-xs text-[var(--text-tertiary)]">
                            {canStart
                                ? 'Perci can start it for you from ~/github-overview. A GitHub token is optional but recommended for useful poll rates.'
                                : 'Requires Go 1.25+. A GitHub token is optional but recommended for useful poll rates.'}
                        </p>
                        {loadError && (
                            <p className="mt-3 inline-flex items-center gap-1.5 text-xs text-red-400">
                                <AlertCircle size={13} /> {loadError}
                            </p>
                        )}
                        <div className="mt-5 flex justify-center gap-2">
                            {canStart && (
                                <button type="button" onClick={startServer} disabled={starting}
                                    className="inline-flex items-center gap-2 rounded-lg bg-[var(--accent)] px-3 py-2 text-sm font-medium text-white transition-colors hover:bg-[var(--accent-hover)] disabled:opacity-60">
                                    {starting
                                        ? <><RefreshCw size={14} className="animate-spin" /> Starting…</>
                                        : <><Play size={14} /> Start GitHub Overview</>}
                                </button>
                            )}
                            <button type="button" onClick={reload}
                                className="inline-flex items-center gap-2 rounded-lg border border-[var(--border)] px-3 py-2 text-sm font-medium text-[var(--text-secondary)] transition-colors hover:bg-[var(--bg-hover)] hover:text-[var(--text-primary)]">
                                <RefreshCw size={14} /> Reload
                            </button>
                        </div>
                    </div>
                </div>
            ) : canUseWebview ? (
                <div className="relative min-h-0 flex-1">
                    <webview
                        ref={webviewRef}
                        key={frameKey}
                        src={GH_ORIGIN}
                        className="absolute inset-0 h-full w-full border-0"
                        partition="persist:perci-github-overview"
                        allowpopups="true"
                    />
                    {!contentReady && (
                        <div className="absolute inset-0 z-10 flex items-center justify-center bg-[var(--bg-primary)]/80 backdrop-blur-sm">
                            <div className="inline-flex items-center gap-2 rounded-md border border-[var(--border)] bg-[var(--bg-secondary)] px-3 py-2 text-xs font-medium text-[var(--text-secondary)]">
                                <RefreshCw size={12} className="animate-spin" /> Loading GitHub Overview…
                            </div>
                        </div>
                    )}
                </div>
            ) : (
                <iframe
                    ref={webviewRef}
                    key={frameKey}
                    src={GH_ORIGIN}
                    className="flex-1 min-h-0 w-full border-0"
                    sandbox="allow-scripts allow-same-origin allow-forms allow-popups"
                    title="GitHub Overview"
                    onLoad={() => { setContentReady(true); setStatus('online'); }}
                />
            )}
        </div>
    );
}

import { AUTOMATIC_SERVICES } from '../lib/performancePolicy';
import React, { useState, useEffect } from 'react';
import { createPortal } from 'react-dom';
import { X, Key, Globe, RefreshCw, ChevronDown, Check, Wifi, WifiOff, User, ScrollText, Search, Server, Plus, Trash2, Monitor, Moon, Sun, Bot, Database, Keyboard, Palette, Zap, ExternalLink } from 'lucide-react';
import { useChat } from '../context/ChatContext';
import { useMode, PXPIPE_WINDOW_ID } from '../context/ModeContext';
import { useTheme } from '../context/ThemeContext';

import openclawLogo from '../assets/openclaw-color.png';
import TasteSkillDial from './TasteSkillDial';
import { isPxpipeEnabled, setPxpipeEnabled, checkPxpipeAlive, PXPIPE_ORIGIN } from '../lib/pxpipe';

const LOCAL_IMAGE_PATHS = {
    openclaw: openclawLogo,
};

function formatBytes(value) {
    const bytes = Number(value) || 0;
    if (bytes < 1024) return `${bytes} B`;
    if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
    if (bytes < 1024 * 1024 * 1024) return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
    return `${(bytes / (1024 * 1024 * 1024)).toFixed(1)} GB`;
}

const SUPERMEMORY_MODEL_PROVIDERS = [
    { id: 'openrouter', label: 'OpenRouter', baseURL: 'https://openrouter.ai/api/v1', model: 'anthropic/claude-sonnet-4', needsKey: true },
    { id: 'openai', label: 'OpenAI', baseURL: 'https://api.openai.com/v1', model: 'gpt-4o-mini', needsKey: true },
    { id: 'anthropic', label: 'Anthropic', baseURL: 'https://api.anthropic.com/v1', model: 'claude-sonnet-4-20250514', needsKey: true },
    { id: 'mistral', label: 'Mistral', baseURL: 'https://api.mistral.ai/v1', model: 'mistral-small-latest', needsKey: true },
    { id: 'groq', label: 'Groq', baseURL: 'https://api.groq.com/openai/v1', model: 'llama-3.3-70b-versatile', needsKey: true },
    { id: 'gemini', label: 'Gemini', baseURL: '', model: 'gemini-2.0-flash', needsKey: true },
    { id: 'ollama', label: 'Ollama', baseURL: 'http://localhost:11434/v1', model: 'llama3.2', needsKey: false },
    { id: 'lmstudio', label: 'LM Studio', baseURL: 'http://localhost:1234/v1', model: 'local-model', needsKey: false },
    { id: 'jan', label: 'Jan', baseURL: 'http://localhost:1337/v1', model: 'local-model', needsKey: false },
];

function getSupermemoryProviderMeta(provider) {
    return SUPERMEMORY_MODEL_PROVIDERS.find(option => option.id === provider) || SUPERMEMORY_MODEL_PROVIDERS[0];
}

// Collapsible section wrapper
function Section({ title, icon: Icon, defaultOpen = true, children }) {
    const [open, setOpen] = useState(defaultOpen);
    return (
        <div className="border-t border-[var(--border)] pt-4">
            <button
                type="button"
                onClick={() => setOpen(o => !o)}
                className="w-full flex items-center justify-between gap-2 text-left group mb-3"
            >
                <span className="flex items-center gap-2 text-sm font-semibold text-[var(--text-primary)]">
                    {Icon && <Icon size={15} className="text-[var(--accent)]" />}
                    {title}
                </span>
                <ChevronDown
                    size={16}
                    className={`text-[var(--text-tertiary)] transition-transform duration-200 ${open ? 'rotate-180' : ''}`}
                />
            </button>
            {open && <div className="space-y-3">{children}</div>}
        </div>
    );
}

export function SettingsModal({ isOpen, onClose }) {
    const {
        apiKeys,
        updateApiKey,
        selectedProvider,
        selectedModel,
        updateProvider,
        updateModel,
        availableModels,
        addCustomModel,
        removeCustomModel,
        isLoadingModels,
        refreshModels,
        userName,
        setUserName,
        customInstructions,
        setCustomInstructions,
        lmStudioUrl,
        setLmStudioUrl,
        janUrl,
        setJanUrl,
        searchEngine,
        setSearchEngine,
        searxngUrl,
        setSearxngUrl
    } = useChat();
    const {
        openClawConfig,
        setOpenClawConfig,
        setShowOpenClawDashboard,
        cycleOrder,
        setCycleOrder,
        cycleScope,
        setCycleScope,
        openWindow, performancePolicy, updatePerformancePolicy,
    } = useMode();
    const { themeMode, setThemeMode, resolvedTheme } = useTheme();

    const [modelSearch, setModelSearch] = useState('');
    const [customModelId, setCustomModelId] = useState('');
    const [customModelName, setCustomModelName] = useState('');
    const [editingName, setEditingName] = useState('');
    const [editingInstructions, setEditingInstructions] = useState('');
    const [testingProfileId, setTestingProfileId] = useState(null);
    const [connectionResults, setConnectionResults] = useState({});
    const [providerDiscovery, setProviderDiscovery] = useState(null);
    const [isDiscoveringProviders, setIsDiscoveringProviders] = useState(false);
    const [startingJanModel, setStartingJanModel] = useState(null);
    const [setupMessage, setSetupMessage] = useState('');
    const [pxpipeOn, setPxpipeOn] = useState(() => isPxpipeEnabled());
    const [pxpipeAlive, setPxpipeAlive] = useState(null);
    const [credentialDrafts, setCredentialDrafts] = useState({});
    const [credentialPersistence, setCredentialPersistence] = useState(() => window.electron?.credentials ? 'secure' : 'session-only');

    // Local OpenClaw Gateway Config & Sandbox/Dreaming States
    const [localOpenClawConfig, setLocalOpenClawConfig] = useState(null);
    const [sandboxMode, setSandboxMode] = useState('off');
    const [dreamingEnabled, setDreamingEnabled] = useState(false);
    const [configLoadError, setConfigLoadError] = useState(null);
    const [configNeedsSave, setConfigNeedsSave] = useState(false);
    const [isRestartingGateway, setIsRestartingGateway] = useState(false);
    const [gatewayRestartStatus, setGatewayRestartStatus] = useState('');

    // G-Dash: the user's own Google OAuth client ID + secret (Bring-Your-Own).
    const [gdashClientId, setGdashClientId] = useState('');
    const [gdashClientSecret, setGdashClientSecret] = useState('');

    // Jules — Google cloud coding agent
    const [julesApiKey, setJulesApiKey] = useState('');

    // Memory backend — memU Docker stack or Supermemory binary.
    const [memoryBackend, setMemoryBackend] = useState('memu');
    const [supermemoryConfig, setSupermemoryConfig] = useState({
        enabled: false,
        provider: 'openrouter',
        providerKey: '',
        openrouterKey: '',
        modelBaseURL: 'https://openrouter.ai/api/v1',
        model: 'anthropic/claude-sonnet-4',
        dataDir: '',
        containerTag: 'perci_memory',
        binaryPath: '',
        port: 6768,
    });
    const [supermemoryStatus, setSupermemoryStatus] = useState(null);
    const [memoryMessage, setMemoryMessage] = useState('');
    const [isWipingMemory, setIsWipingMemory] = useState(false);

    useEffect(() => {
        if (isOpen) {
            setEditingName(userName || '');
            setEditingInstructions(customInstructions || '');
            setModelSearch('');
            window.electron?.credentials?.status?.()
                .then(status => setCredentialPersistence(status?.persistence || 'session-only'))
                .catch(() => setCredentialPersistence('session-only'));

            // Load local openclaw config if in electron environment
            if (window.electron?.readOpenClawConfig) {
                const loadConfig = async () => {
                    try {
                        const config = await window.electron.readOpenClawConfig();
                        if (config && !config.error) {
                            setLocalOpenClawConfig(config);
                            setSandboxMode(config.agents?.defaults?.sandbox?.mode || 'off');
                            setDreamingEnabled(Boolean(config.plugins?.entries?.['memory-core']?.config?.dreaming?.enabled));
                            setConfigLoadError(null);
                        } else {
                            setConfigLoadError(config?.error || 'Failed to load local config');
                        }
                    } catch (err) {
                        setConfigLoadError(err.message);
                    }
                };
                loadConfig();
            }

            // Load the saved G-Dash client ID and secret (decrypted by the main process).
            if (window.electron?.getAppData) {
                window.electron.getAppData()
                    .then((data) => {
                        setGdashClientId(data?.gdash_google_client_id || '');
                        const backend = data?.perci_memory_backend || (data?.perci_supermemory_enabled === 'true' ? 'supermemory' : 'memu');
                        setMemoryBackend(backend === 'supermemory' ? 'supermemory' : 'memu');
                    })
                    .catch(() => { /* leave fields blank */ });
            }
            if (window.electron?.supermemoryConfig) {
                window.electron.supermemoryConfig()
                    .then((config) => {
                        if (config && !config.error) {
                            setSupermemoryConfig(prev => ({
                                ...prev,
                                ...config,
                            }));
                        }
                    })
                    .catch(() => { /* leave defaults */ });
                window.electron.supermemoryStatus?.()
                    .then((status) => setSupermemoryStatus(status || null))
                    .catch(() => { /* leave unknown */ });
            }
        }
    }, [apiKeys.openrouter, isOpen, userName, customInstructions]);

    const saveCredentialDraft = async (provider) => {
        const value = credentialDrafts[provider]?.trim();
        if (!value) return;
        try {
            const result = await updateApiKey(provider, value);
            setCredentialPersistence(result?.persistence || credentialPersistence);
            setCredentialDrafts(prev => ({ ...prev, [provider]: '' }));
        } catch (err) {
            setSetupMessage(err?.message || 'Could not store that credential.');
        }
    };

    const deleteCredential = async (provider) => {
        try {
            await updateApiKey(provider, '');
            setCredentialDrafts(prev => ({ ...prev, [provider]: '' }));
        } catch (err) {
            setSetupMessage(err?.message || 'Could not remove that credential.');
        }
    };

    const saveGdashClientId = async () => {
        if (!window.electron?.setAppData) return;
        try {
            await window.electron.setAppData({ gdash_google_client_id: gdashClientId.trim() });
        } catch (err) {
            console.error('Failed to save G-Dash client ID:', err);
        }
    };

    const saveGdashClientSecret = async () => {
        if (!window.electron?.setGdashClientSecret) return;
        if (!gdashClientSecret.trim()) return;
        try {
            await window.electron.setGdashClientSecret(gdashClientSecret.trim());
            setGdashClientSecret('');
        } catch (err) {
            console.error('Failed to save G-Dash client secret:', err);
        }
    };

    const saveJulesApiKey = async () => {
        if (!window.electron?.setJulesApiKey) return;
        if (!julesApiKey.trim()) return;
        try {
            await window.electron.setJulesApiKey(julesApiKey.trim());
            setJulesApiKey('');
        } catch (err) {
            console.error('Failed to save Jules API key:', err);
        }
    };

    const saveSupermemoryConfig = async (patch = {}) => {
        if (!window.electron?.supermemoryConfig) return;
        const next = { ...supermemoryConfig, ...patch };
        setSupermemoryConfig(next);
        try {
            const saved = await window.electron.supermemoryConfig(patch);
            if (saved && !saved.error) {
                setSupermemoryConfig(prev => ({ ...prev, ...saved }));
            } else if (saved?.error) {
                setMemoryMessage(saved.error);
            }
        } catch (err) {
            setMemoryMessage(err.message || 'Failed to save Supermemory settings.');
        }
    };

    const saveMemoryBackend = async (backend) => {
        setMemoryBackend(backend);
        if (!window.electron?.supermemoryConfig) return;
        try {
            const enabled = backend === 'supermemory';
            await window.electron.supermemoryConfig({ enabled });
            setSupermemoryConfig(prev => ({ ...prev, enabled }));
            window.dispatchEvent(new CustomEvent('perci-memory-backend-change', { detail: { backend } }));
            setMemoryMessage(enabled ? 'Supermemory selected as the active memory backend.' : 'memU Docker selected as the active memory backend.');
        } catch (err) {
            setMemoryMessage(err.message || 'Failed to save memory backend.');
        }
    };

    const refreshSupermemoryStatus = async () => {
        if (!window.electron?.supermemoryStatus) return;
        try {
            const status = await window.electron.supermemoryStatus();
            setSupermemoryStatus(status || null);
        } catch (err) {
            setMemoryMessage(err.message || 'Failed to refresh Supermemory status.');
        }
    };

    const wipeSupermemoryData = async () => {
        if (!window.electron?.supermemoryConfig) return;
        const ok = window.confirm(
            'This deletes the local Supermemory data directory and clears the saved Supermemory instance key. Export anything you need first. Continue?'
        );
        if (!ok) return;
        setIsWipingMemory(true);
        setMemoryMessage('');
        try {
            const result = await window.electron.supermemoryConfig({ action: 'wipe-data' });
            if (result?.ok) {
                setMemoryMessage('Supermemory data directory wiped.');
                setSupermemoryConfig(prev => ({ ...prev, apiKey: '' }));
                await refreshSupermemoryStatus();
            } else {
                setMemoryMessage(result?.error || 'Could not wipe Supermemory data.');
            }
        } catch (err) {
            setMemoryMessage(err.message || 'Could not wipe Supermemory data.');
        } finally {
            setIsWipingMemory(false);
        }
    };

    const saveLocalOpenClawConfig = async (config) => {
        if (!window.electron?.writeOpenClawConfig) return;
        try {
            const res = await window.electron.writeOpenClawConfig(config);
            if (res?.ok) {
                setConfigNeedsSave(true);
            }
        } catch (err) {
            console.error('Failed to write openclaw config:', err);
        }
    };

    const handleSandboxModeChange = async (e) => {
        const mode = e.target.value;
        setSandboxMode(mode);
        if (!localOpenClawConfig) return;

        const updatedConfig = {
            ...localOpenClawConfig,
            agents: {
                ...localOpenClawConfig.agents,
                defaults: {
                    ...localOpenClawConfig.agents?.defaults,
                    sandbox: {
                        ...localOpenClawConfig.agents?.defaults?.sandbox,
                        mode: mode
                    }
                }
            }
        };
        setLocalOpenClawConfig(updatedConfig);
        await saveLocalOpenClawConfig(updatedConfig);
    };

    const handleToggleDreaming = async () => {
        const enabled = !dreamingEnabled;
        setDreamingEnabled(enabled);
        if (!localOpenClawConfig) return;

        const updatedConfig = {
            ...localOpenClawConfig,
            plugins: {
                ...localOpenClawConfig.plugins,
                entries: {
                    ...localOpenClawConfig.plugins?.entries,
                    'memory-core': {
                        ...localOpenClawConfig.plugins?.entries?.['memory-core'],
                        config: {
                            ...localOpenClawConfig.plugins?.entries?.['memory-core']?.config,
                            dreaming: {
                                ...localOpenClawConfig.plugins?.entries?.['memory-core']?.config?.dreaming,
                                enabled: enabled
                            }
                        }
                    }
                }
            }
        };
        setLocalOpenClawConfig(updatedConfig);
        await saveLocalOpenClawConfig(updatedConfig);
    };

    const handleRestartGateway = async () => {
        if (isRestartingGateway) return;
        setIsRestartingGateway(true);
        setGatewayRestartStatus('Restarting...');
        try {
            const result = await window.electron.restartOpenClawGateway();
            if (result?.ok) {
                setGatewayRestartStatus('Gateway restarted!');
                setConfigNeedsSave(false);
                setTimeout(() => setGatewayRestartStatus(''), 3000);
            } else {
                setGatewayRestartStatus(`Failed: ${result?.error || 'Unknown error'}`);
            }
        } catch (err) {
            setGatewayRestartStatus(`Failed: ${err.message}`);
        } finally {
            setIsRestartingGateway(false);
        }
    };

    const loadProviderDiscovery = async () => {
        if (!window.electron?.discoverModelProviders) {
            setProviderDiscovery({
                generatedAt: Date.now(),
                providers: [
                    { id: 'ollama', name: 'Ollama', status: availableModels.ollama?.length ? 'ready' : 'offline', modelCount: availableModels.ollama?.length || 0, models: availableModels.ollama || [] },
                    { id: 'lmstudio', name: 'LM Studio', status: availableModels.lmstudio?.length ? 'ready' : 'offline', modelCount: availableModels.lmstudio?.length || 0, models: availableModels.lmstudio || [] },
                    { id: 'jan', name: 'Jan', status: availableModels.jan?.length ? 'ready' : 'offline', modelCount: availableModels.jan?.length || 0, models: availableModels.jan || [] },
                ]
            });
            return;
        }

        setIsDiscoveringProviders(true);
        try {
            const discovery = await window.electron.discoverModelProviders();
            setProviderDiscovery(discovery);
            const readyJan = discovery?.providers?.find(provider => provider.id === 'jan' && provider.status === 'ready' && provider.endpoint);
            if (readyJan?.endpoint) {
                setJanUrl(readyJan.endpoint);
            }
        } catch (err) {
            setSetupMessage(err.message || 'Could not check local providers.');
        } finally {
            setIsDiscoveringProviders(false);
        }
    };

    useEffect(() => {
        if (isOpen) {
            loadProviderDiscovery();
        }
    }, [isOpen]); // eslint-disable-line react-hooks/exhaustive-deps

    useEffect(() => {
        if (!isOpen) return undefined;
        setPxpipeOn(isPxpipeEnabled());
        setPxpipeAlive(null);
        let cancelled = false;
        checkPxpipeAlive().then(alive => {
            if (!cancelled) setPxpipeAlive(alive);
        });
        return () => { cancelled = true; };
    }, [isOpen]);

    if (!isOpen) return null;

    // iconClass holds the full Tailwind class as a literal — a composed
    // `text-${color}-500` is invisible to Tailwind's scanner and gets purged.
    const providers = [
        { id: 'openrouter', name: 'OpenRouter', needsKey: true, iconClass: 'text-violet-500', badge: 'Recommended' },
        { id: 'deepinfra',  name: 'DeepInfra',  needsKey: true, iconClass: 'text-emerald-500' },
        { id: 'anthropic',  name: 'Anthropic',  needsKey: true, iconClass: 'text-amber-500'  },
        { id: 'mistral',    name: 'Mistral',    needsKey: true, iconClass: 'text-sky-500'    },
        { id: 'groq',       name: 'Groq',       needsKey: true, iconClass: 'text-orange-500' },
        { id: 'openai',     name: 'OpenAI',     needsKey: true, iconClass: 'text-green-500'  },
        { id: 'gemini',     name: 'Gemini',     needsKey: true, iconClass: 'text-blue-500'   },
        { id: 'ollama',     name: 'Ollama',     needsKey: false, iconClass: 'text-purple-500', local: true },
        { id: 'lmstudio',  name: 'LM Studio',  needsKey: false, iconClass: 'text-pink-500',   local: true },
        { id: 'jan',        name: 'Jan',        needsKey: false, iconClass: 'text-teal-500',   local: true },
    ];

    const currentProviderModels = availableModels[selectedProvider] || [];
    const selectedModelObj = currentProviderModels.find(m => m.id === selectedModel);
    const supermemoryProviderMeta = getSupermemoryProviderMeta(supermemoryConfig.provider || 'openrouter');
    const hasSupermemoryProviderKey = Boolean(
        supermemoryConfig.providerKey ||
        apiKeys[supermemoryProviderMeta.id] ||
        supermemoryStatus?.hasProviderKey
    );
    const supermemoryProviderText = supermemoryProviderMeta.needsKey
        ? hasSupermemoryProviderKey
            ? `Supermemory uses the ${supermemoryProviderMeta.label} key already saved in Perci.`
            : `Add a ${supermemoryProviderMeta.label} key in Settings > Models before starting Supermemory.`
        : `Supermemory uses the local ${supermemoryProviderMeta.label} endpoint.`;

    const filteredModels = modelSearch.trim()
        ? currentProviderModels.filter(m =>
            m.name.toLowerCase().includes(modelSearch.toLowerCase()) ||
            m.id.toLowerCase().includes(modelSearch.toLowerCase())
          )
        : currentProviderModels;

    const selectedProviderMeta = providers.find(p => p.id === selectedProvider) || null;
    const discoveryById = (providerDiscovery?.providers || []).reduce((acc, p) => {
        acc[p.id] = p;
        return acc;
    }, {});
    const janDiscovery = discoveryById['jan'];

    const handleSaveName = () => {
        if (editingName.trim() !== userName) setUserName(editingName.trim());
    };

    const handleSaveInstructions = () => {
        if (editingInstructions !== customInstructions) setCustomInstructions(editingInstructions);
    };

    const handleClose = () => {
        handleSaveName();
        handleSaveInstructions();
        onClose();
    };

    const handleRefreshModelSetup = async () => {
        setSetupMessage('');
        refreshModels();
        await loadProviderDiscovery();
    };

    const handleAddCustomModel = () => {
        const id = customModelId.trim();
        if (!id || !selectedProvider) return;
        addCustomModel(selectedProvider, id, customModelName.trim());
        updateModel(id);
        setCustomModelId('');
        setCustomModelName('');
    };

    const handleStartJan = async (modelId) => {
        if (!window.electron?.startJanServer) return;
        setStartingJanModel(modelId || 'default');
        setSetupMessage('');
        try {
            const result = await window.electron.startJanServer({ modelId, port: 6767 });
            if (!result?.ok) {
                setSetupMessage(result?.error || 'Jan did not start.');
                return;
            }
            setSetupMessage(`Jan started ${result.modelId} on port ${result.port}.`);
            if (result.endpoint) {
                setJanUrl(result.endpoint);
            }
            await loadProviderDiscovery();
            refreshModels();
            updateProvider('jan');
        } catch (err) {
            setSetupMessage(err.message || 'Jan did not start.');
        } finally {
            setStartingJanModel(null);
        }
    };

    const updateOpenClawProfile = (profileId, patch) => {
        setOpenClawConfig(prev => ({
            ...prev,
            profiles: prev.profiles.map(profile => (
                profile.id === profileId ? { ...profile, ...patch } : profile
            ))
        }));
    };

    const addOpenClawProfile = () => {
        const id = `profile-${Date.now()}`;
        setOpenClawConfig(prev => ({
            activeProfileId: id,
            profiles: [
                ...prev.profiles,
                {
                    id,
                    name: 'New OpenClaw Gateway',
                    mode: 'appliance',
                    gatewayUrl: 'ws://clawbox.local:18789',
                    controlUrl: 'http://clawbox.local:18789/openclaw',
                    token: ''
                }
            ]
        }));
    };

    const removeOpenClawProfile = (profileId) => {
        setOpenClawConfig(prev => {
            if (prev.profiles.length <= 1) return prev;
            const profiles = prev.profiles.filter(profile => profile.id !== profileId);
            return {
                activeProfileId: prev.activeProfileId === profileId ? profiles[0].id : prev.activeProfileId,
                profiles
            };
        });
    };

    const testOpenClawProfile = async (profile) => {
        setTestingProfileId(profile.id);
        try {
            const result = window.electron?.testOpenClawConnection
                ? await window.electron.testOpenClawConnection(profile)
                : await fetch(profile.controlUrl, { method: 'GET' }).then(response => ({ ok: response.ok, status: response.status, url: profile.controlUrl }));
            setConnectionResults(prev => ({ ...prev, [profile.id]: result }));
        } catch (err) {
            setConnectionResults(prev => ({ ...prev, [profile.id]: { ok: false, error: err.message, url: profile.controlUrl } }));
        } finally {
            setTestingProfileId(null);
        }
    };

    const openOpenClawDashboard = (profile) => {
        setOpenClawConfig(prev => ({ ...prev, activeProfileId: profile.id }));
        setShowOpenClawDashboard(true);
        onClose();
    };

    return createPortal(
        <div
            className="fixed inset-0 bg-black/60 backdrop-blur-sm flex items-center justify-center z-[9999]"
            onClick={handleClose}
        >
            <div
                className="bg-[var(--bg-primary)] w-full max-w-3xl rounded-2xl border border-[var(--border)] flex flex-col"
                style={{ maxHeight: '90vh' }}
                onClick={e => e.stopPropagation()}
            >
                {/* Header */}
                <div className="flex-shrink-0 px-6 py-5 border-b border-[var(--border)] bg-[var(--bg-secondary)] rounded-t-2xl flex items-center justify-between">
                    <div>
                        <h2 className="text-xl font-semibold text-[var(--text-primary)]">Settings</h2>
                        <p className="text-sm text-[var(--text-tertiary)] mt-0.5">Manage your profile and preferences</p>
                    </div>
                    <button
                        onClick={handleClose}
                        className="p-1.5 hover:bg-[var(--bg-hover)] rounded-md transition-colors text-[var(--text-tertiary)] hover:text-[var(--text-primary)]"
                    >
                        <X size={20} />
                    </button>
                </div>

                {/* Scrollable body */}
                <div className="flex-1 overflow-y-auto px-6 py-5 space-y-0">

                    <Section title="Performance" icon={Zap}>
                        <p className="text-sm text-[var(--text-secondary)]">Remember your layout without loading every tool. Changes to restoration apply next time Perci opens.</p>
                        <label className="flex items-center justify-between gap-4 py-2 text-sm text-[var(--text-primary)]">
                            Load restored tools when selected
                            <input type="checkbox" checked={performancePolicy.restoreViews === 'deferred'} onChange={event => updatePerformancePolicy({ ...performancePolicy, restoreViews: event.target.checked ? 'deferred' : 'immediate' })} className="accent-[var(--accent)]" />
                        </label>
                        <label className="flex items-center justify-between gap-4 py-2 text-sm text-[var(--text-primary)]">
                            Pause hidden tool updates
                            <input type="checkbox" checked={performancePolicy.pauseHiddenViews} onChange={event => updatePerformancePolicy({ ...performancePolicy, pauseHiddenViews: event.target.checked })} className="accent-[var(--accent)]" />
                        </label>
                        <p className="text-xs text-[var(--text-secondary)]">Pausing updates keeps your work in memory. Running jobs and services continue.</p>
                        <div className="divide-y divide-[var(--border)]">
                            {Object.entries(AUTOMATIC_SERVICES).map(([id, label]) => (
                                <label key={id} className="flex items-center justify-between gap-4 py-2 text-sm text-[var(--text-primary)]">
                                    {label}
                                    <select aria-label={`${label} service startup`} value={performancePolicy.services[id]} onChange={event => updatePerformancePolicy({ ...performancePolicy, services: { ...performancePolicy.services, [id]: event.target.value } })} className="rounded-md border border-[var(--border)] bg-[var(--bg-secondary)] px-2 py-1 text-[var(--text-primary)]">
                                        <option value="on-open">When opened</option>
