                                                        : 'border-[var(--border)] bg-[var(--bg-primary)] focus:ring-2 ring-[var(--accent)]'
                                                }`}
                                                placeholder={apiKeys[selectedProvider]
                                                    ? `${credentialPersistence === 'secure' ? 'Stored with OS protection' : 'Stored for this session'} — enter to replace`
