// Windows whose content is an embedded <webview>/<iframe>; CSS transforms can make
// embedded frames flicker (and reload), so these minimize with a plain fade instead
// of the whirlpool spin.
const NO_WHIRLPOOL_IDS = new Set([OPENCLAW_WINDOW_ID, HERMES_WINDOW_ID, YOUTUBE_WINDOW_ID, GDASH_WINDOW_ID, EIDOS_WINDOW_ID, LOCALHOST_WINDOW_ID, KLIPIT_WINDOW_ID, AUTOFORGE_WINDOW_ID, OPEN_NOTEBOOK_WINDOW_ID, SIMPLEX_WINDOW_ID, PXPIPE_WINDOW_ID, KEYSAFE_WINDOW_ID, APFEL_WINDOW_ID, DOTENVX_WINDOW_ID, OPENCODE_WINDOW_ID, GITHUB_OVERVIEW_WINDOW_ID]);

const WINDOW_DEFAULTS = { width: 960, height: 640, minWidth: 420, minHeight: 300, cascade: 34 };
const MODE_DEFAULT_SIZES = {
    [MODES.CODEX_MICRO]: { width: 760, height: 760 },
};
const DOCK_RESERVED_HEIGHT = 64;
const DESKTOP_HOST_SELECTOR = '.perci-desktop-host';
const DESKTOP_SURFACE_SELECTOR = '.perci-dock-reserved';

function viewportSize() {
    if (typeof window === 'undefined') return { width: 1440, height: 900 };
    const host = document.querySelector(DESKTOP_HOST_SELECTOR);
    const hostRect = host?.getBoundingClientRect();
    if (hostRect?.width > 0 && hostRect?.height > 0) {
        return { width: hostRect.width, height: hostRect.height };
    }

    const surface = document.querySelector(DESKTOP_SURFACE_SELECTOR);
    const surfaceRect = surface?.getBoundingClientRect();
    if (surfaceRect?.width > 0 && surfaceRect?.height > 0) {
        const dockSpace = parseFloat(getComputedStyle(surface).getPropertyValue('--perci-dock-space')) || 0;
        return { width: surfaceRect.width, height: Math.max(0, surfaceRect.height - dockSpace) };
    }

    return { width: window.innerWidth, height: Math.max(0, window.innerHeight - DOCK_RESERVED_HEIGHT) };
}

function defaultBounds(index = 0, modeId) {
    const { width: vw, height: vh } = viewportSize();
    const preferred = MODE_DEFAULT_SIZES[modeId] || WINDOW_DEFAULTS;
    const width = Math.min(preferred.width, Math.round(vw * 0.72));
    const height = Math.min(preferred.height, Math.max(WINDOW_DEFAULTS.minHeight, Math.round((vh - 120) * 0.94)));
    const offset = (index % 6) * WINDOW_DEFAULTS.cascade;
    return { x: 80 + offset, y: 36 + offset, width, height };
}

function clampBounds(bounds) {
    const { width: vw, height: vh } = viewportSize();
    const availableHeight = Math.max(0, vh);
    const width = Math.min(vw, Math.max(WINDOW_DEFAULTS.minWidth, Math.min(bounds.width, vw)));
    const height = Math.min(availableHeight, Math.max(WINDOW_DEFAULTS.minHeight, Math.min(bounds.height, availableHeight)));
    const x = Math.min(Math.max(bounds.x, 0), Math.max(0, vw - width));
    const y = Math.min(Math.max(bounds.y, 0), Math.max(0, availableHeight - height));
    return { x, y, width, height };
}

// Rebuilds the persisted open-window set on load: validates shape, re-clamps
// geometry to the current viewport, and re-derives non-persisted fields.
function hydrateWindows(saved) {
    if (!Array.isArray(saved)) return [];
    const validStates = new Set(['normal', 'minimized', 'maximized']);
    return saved
        // The YouTube window's content (its embed URL) isn't persisted, so drop
        // any stale chip on reload rather than rehydrate an empty player.
        .filter(w => w && typeof w.id === 'string' && typeof w.modeId === 'string' && w.id !== YOUTUBE_WINDOW_ID)
        .map(w => ({
            id: w.id,
            modeId: w.modeId,
            title: WINDOW_TITLES[w.modeId] || w.title || w.modeId,
            state: validStates.has(w.state) ? w.state : 'normal',
            z: Number(w.z) || 20,
            focusedAt: Number(w.focusedAt) || Date.now(),
            bounds: clampBounds(w.bounds && typeof w.bounds === 'object' ? w.bounds : defaultBounds(0, w.modeId)),
            restoreBounds: w.restoreBounds && typeof w.restoreBounds === 'object' ? clampBounds(w.restoreBounds) : undefined,
            noWhirlpool: NO_WHIRLPOOL_IDS.has(w.modeId),
        }));
}

